const ResponsiveContainer = dynamic(() => import('recharts').then(m => m.ResponsiveContainer), { ssr: false });

interface ScorecardItem {
  ratioKey: string;
  name: string;
  value: number;
  target: number;
  status: 'green' | 'amber' | 'red';
  percentOfTarget: number;
}

