  v_subcontractor UUID;
  v_fuel UUID;
  v_admin_exp UUID;
  v_bank_charges UUID;
  v_equipment UUID;
  -- Fiscal Periods
  v_jan_fp UUID;
  v_feb_fp UUID;
  v_mar_fp UUID;
  -- Journal Entry IDs
  v_je_id UUID;
