        const poNum = `PO-${year}${String(month).padStart(2, '0')}-${String(i + 1).padStart(3, '0')}`;

        const poResult = await client.query(`
          INSERT INTO purchase_orders (company_id, po_number, supplier_id, order_date, status, subtotal, tax_amount, total, created_by)
          VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'seed')
          ON CONFLICT DO NOTHING
          RETURNING id
        `, [companyId, poNum, supplier.id, orderDate, status, subtotal, tax, total]);

        if (poResult.rows[0]) {
          const poId = poResult.rows[0].id;
