        const supplier = suppliers.rows[Math.floor(Math.random() * suppliers.rows.length)];
        const amount = Math.round((3000 + Math.random() * 40000) * 100) / 100;
        const payDate = `${year}-${String(month).padStart(2, '0')}-${String(15 + Math.floor(Math.random() * 13)).padStart(2, '0')}`;

        await client.query(`
          INSERT INTO supplier_payments (company_id, supplier_id, total_amount, payment_date, payment_method, reference, status, created_by)
          VALUES ($1, $2, $3, $4, 'eft', $5, 'confirmed', 'seed')
