/**
 * ISAFlow Historical Seed Data — 2020 to 2026
 * Seeds realistic financial data across ALL modules for comprehensive testing.
 *
 * Usage: DATABASE_URL=... node scripts/seed-historical-data.mjs
 */

import pg from 'pg';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('ERROR: DATABASE_URL required. Run: export DATABASE_URL=$(grep DATABASE_URL .env.local | cut -d= -f2-)');
  process.exit(1);
}

const client = new pg.Client({ connectionString: DATABASE_URL });

async function seed() {
  await client.connect();
  console.log('=== ISAFlow Historical Seed (2020-2026) ===\n');

  // ── 1. FISCAL PERIODS (2020-2026) ──────────────────────────────────────
  console.log('1. Seeding fiscal periods 2020-2026...');
  for (let year = 2020; year <= 2026; year++) {
    for (let month = 1; month <= 12; month++) {
      const lastDay = new Date(year, month, 0).getDate();
      const startDate = `${year}-${String(month).padStart(2, '0')}-01`;
      const endDate = `${year}-${String(month).padStart(2, '0')}-${lastDay}`;
      const name = `${new Date(year, month - 1).toLocaleString('en', { month: 'long' })} ${year}`;
      const status = (year < 2026 || (year === 2026 && month < 3)) ? 'closed' : (year === 2026 && month === 3) ? 'open' : 'open';
      await client.query(`
        INSERT INTO fiscal_periods (name, start_date, end_date, status, company_id)
        SELECT $1, $2, $3, $4, id FROM companies LIMIT 1
        ON CONFLICT DO NOTHING
      `, [name, startDate, endDate, status]);
    }
  }
  console.log('  ✓ Fiscal periods seeded\n');

  // ── 2. HISTORICAL JOURNAL ENTRIES (2020-2026) ──────────────────────────
