          await client.query(`INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description) VALUES ($1, $2, 0, $3, $4) ON CONFLICT DO NOTHING`, [jeId, acctMap['4100'], revenue, `Sales ${monthStr}`]);
