      'TAKEALOT ORDER', 'BUILDERS WAREHOUSE', 'OFFICE NATIONAL', 'SAGE SUBSCRIPTION',
      'SALARY - SIPHO NKOSI', 'SALARY - LERATO MOLEFE', 'SALARY - JOHAN VAN WYK',
      'SARS PAYMENT VAT', 'SARS PAYMENT PAYE', 'INSURANCE PREMIUM', 'RENTAL PAYMENT',
      'CLIENT DEPOSIT', 'FIBRE INSTALLATION FEE', 'PROJECT MILESTONE PAYMENT',
    ];

    for (let year = 2020; year <= 2026; year++) {
      const maxMonth = year === 2026 ? 3 : 12;
      for (let month = 1; month <= maxMonth; month++) {
        // 15-25 transactions per month
        const numTx = 15 + Math.floor(Math.random() * 11);
        for (let i = 0; i < numTx; i++) {
          const desc = merchantDescriptions[Math.floor(Math.random() * merchantDescriptions.length)];
          const isDebit = desc.includes('SALARY') || desc.includes('FUEL') || desc.includes('CHARGES') || desc.includes('FEE') || desc.includes('PAYMENT') || desc.includes('PREMIUM') || desc.includes('RENTAL') || Math.random() > 0.4;
          const amount = isDebit
            ? -(Math.round((500 + Math.random() * 30000) * 100) / 100)
            : Math.round((5000 + Math.random() * 100000) * 100) / 100;
          const txDate = `${year}-${String(month).padStart(2, '0')}-${String(1 + Math.floor(Math.random() * 28)).padStart(2, '0')}`;

          await client.query(`
            INSERT INTO bank_transactions (bank_account_id, transaction_date, description, amount, company_id)
            VALUES ($1, $2, $3, $4, $5)
          `, [bankAccountId, txDate, desc, amount, companyId]);
          bankTxCount++;
        }
      }
    }
  }
  console.log(`  ✓ ${bankTxCount} bank transactions seeded\n`);

  // ── 6. PAYROLL RUNS & PAYSLIPS (2021-2026) ─────────────────────────────
  console.log('6. Seeding payroll runs and payslips...');
  const employees = await client.query(`SELECT id, first_name, last_name FROM employees`);
  let payrollCount = 0;

  const baseSalaries = { 0: 18000, 1: 22000, 2: 28000, 3: 16000 }; // Per employee

  for (let year = 2021; year <= 2026; year++) {
    const maxMonth = year === 2026 ? 3 : 12;
    for (let month = 1; month <= maxMonth; month++) {
      const periodStart = `${year}-${String(month).padStart(2, '0')}-01`;
      const periodEnd = `${year}-${String(month).padStart(2, '0')}-${new Date(year, month, 0).getDate()}`;
      const payDate = periodEnd;
      const runNum = `PR-${year}-${String(month).padStart(2, '0')}`;

      const runResult = await client.query(`
        INSERT INTO payroll_runs (company_id, run_number, period_start, period_end, pay_date, status, total_gross, total_net, total_paye, total_uif, total_sdl, employee_count, created_by)
        VALUES ($1, $2, $3, $4, $5, 'completed', 0, 0, 0, 0, 0, $6, 'seed')
        ON CONFLICT DO NOTHING
        RETURNING id
      `, [companyId, runNum, periodStart, periodEnd, payDate, employees.rows.length]);

      if (runResult.rows[0]) {
        const runId = runResult.rows[0].id;
        let totalGross = 0, totalPaye = 0, totalUif = 0, totalSdl = 0, totalNet = 0;

        for (let e = 0; e < employees.rows.length; e++) {
          const emp = employees.rows[e];
          const salary = (baseSalaries[e] || 20000) * (1 + (year - 2021) * 0.05); // 5% annual increase
          const paye = Math.round(salary * 0.22 * 100) / 100; // ~22% effective
          const uifEmp = Math.round(Math.min(salary, 17811.84) * 0.01 * 100) / 100;
          const uifEr = uifEmp;
          const sdl = Math.round(salary * 0.01 * 100) / 100;
          const net = Math.round((salary - paye - uifEmp) * 100) / 100;

          await client.query(`
            INSERT INTO payslips (payroll_run_id, employee_id, gross_pay, net_pay, paye, uif_employee, uif_employer, sdl, basic_salary)
            VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
          `, [runId, emp.id, salary, net, paye, uifEmp, uifEr, sdl, salary]);

          totalGross += salary; totalPaye += paye; totalUif += uifEmp + uifEr; totalSdl += sdl; totalNet += net;
        }

        await client.query(`
          UPDATE payroll_runs SET total_gross = $1, total_net = $2, total_paye = $3, total_uif = $4, total_sdl = $5 WHERE id = $6
        `, [totalGross, totalNet, totalPaye, totalUif, totalSdl, runId]);
        payrollCount++;
      }
    }
  }
  console.log(`  ✓ ${payrollCount} payroll runs seeded (${payrollCount * employees.rows.length} payslips)\n`);

  // ── 7. LEAVE BALANCES & APPLICATIONS (2021-2026) ───────────────────────
  console.log('7. Seeding leave data...');
  const leaveTypes = await client.query(`SELECT id, code FROM leave_types`);
  let leaveCount = 0;

  for (const emp of employees.rows) {
    for (let year = 2021; year <= 2026; year++) {
      for (const lt of leaveTypes.rows) {
        const accrued = lt.code === 'annual' ? 15 : lt.code === 'sick' ? 10 : lt.code === 'family_responsibility' ? 3 : 0;
        const taken = Math.floor(Math.random() * Math.min(accrued, 10));
        await client.query(`
          INSERT INTO leave_balances (employee_id, leave_type_id, leave_type_code, year, opening_balance, accrued, taken, closing_balance)
          VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
          ON CONFLICT (employee_id, leave_type_code, year) DO NOTHING
        `, [emp.id, lt.id, lt.code, year, 0, accrued, taken, accrued - taken]);
      }

      // 1-3 leave applications per year per employee
      const numApps = 1 + Math.floor(Math.random() * 3);
      for (let i = 0; i < numApps; i++) {
        const month = 1 + Math.floor(Math.random() * 12);
        const startDay = 5 + Math.floor(Math.random() * 15);
        const days = 1 + Math.floor(Math.random() * 5);
        const startDate = `${year}-${String(month).padStart(2, '0')}-${String(startDay).padStart(2, '0')}`;
        const endDate = new Date(new Date(startDate).getTime() + days * 86400000).toISOString().split('T')[0];
        const lt = leaveTypes.rows[Math.floor(Math.random() * Math.min(3, leaveTypes.rows.length))];
        const status = year < 2026 ? 'approved' : (Math.random() > 0.5 ? 'approved' : 'pending');

        await client.query(`
          INSERT INTO leave_applications (company_id, employee_id, leave_type_id, leave_type_code, start_date, end_date, days, reason, status, created_by)
          VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'seed')
        `, [companyId, emp.id, lt.id, lt.code, startDate, endDate, days, 'Annual leave', status]);
        leaveCount++;
      }
    }
  }
  console.log(`  ✓ ${leaveCount} leave applications seeded\n`);

  // ── 8. PURCHASE ORDERS & GRNs (2024-2026) ─────────────────────────────
  console.log('8. Seeding purchase orders and GRNs...');
  let poCount = 0;

  for (let year = 2024; year <= 2026; year++) {
    const maxMonth = year === 2026 ? 3 : 12;
    for (let month = 1; month <= maxMonth; month++) {
      const numPOs = 1 + Math.floor(Math.random() * 3);
      for (let i = 0; i < numPOs; i++) {
        const supplier = suppliers.rows[Math.floor(Math.random() * suppliers.rows.length)];
        const subtotal = Math.round((5000 + Math.random() * 50000) * 100) / 100;
        const tax = Math.round(subtotal * 0.15 * 100) / 100;
        const total = subtotal + tax;
        const orderDate = `${year}-${String(month).padStart(2, '0')}-${String(3 + Math.floor(Math.random() * 15)).padStart(2, '0')}`;
        const isPast = new Date(orderDate) < new Date('2026-02-01');
        const status = isPast ? 'received' : (Math.random() > 0.5 ? 'approved' : 'draft');
        const poNum = `PO-${year}${String(month).padStart(2, '0')}-${String(i + 1).padStart(3, '0')}`;

        const poResult = await client.query(`
          INSERT INTO purchase_orders (company_id, po_number, supplier_id, order_date, status, subtotal, tax_amount, total, created_by)
          VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'seed')
          ON CONFLICT DO NOTHING
          RETURNING id
        `, [companyId, poNum, supplier.id, orderDate, status, subtotal, tax, total]);

        if (poResult.rows[0]) {
          const poId = poResult.rows[0].id;
          // Add 1-3 line items
          const numItems = 1 + Math.floor(Math.random() * 3);
          for (let j = 0; j < numItems; j++) {
            const qty = 5 + Math.floor(Math.random() * 50);
            const unitPrice = Math.round((100 + Math.random() * 5000) * 100) / 100;
            const lineTotal = Math.round(qty * unitPrice * 100) / 100;
            const lineTax = Math.round(lineTotal * 0.15 * 100) / 100;

            await client.query(`
              INSERT INTO po_items (purchase_order_id, description, quantity, unit_price, tax_rate, line_total, tax_amount, quantity_received, sort_order)
              VALUES ($1, $2, $3, $4, 15, $5, $6, $7, $8)
            `, [poId, `Item ${j + 1} for ${poNum}`, qty, unitPrice, lineTotal, lineTax, status === 'received' ? qty : 0, j]);
          }
          poCount++;
        }
      }
    }
  }
  console.log(`  ✓ ${poCount} purchase orders seeded\n`);

  // ── 9. STOCK MOVEMENTS (2024-2026) ─────────────────────────────────────
  console.log('9. Seeding stock movements...');
  const products = await client.query(`SELECT id, code FROM products WHERE product_type = 'inventory'`);
  let stockCount = 0;

  for (const prod of products.rows) {
    for (let year = 2024; year <= 2026; year++) {
      const maxMonth = year === 2026 ? 3 : 12;
      for (let month = 1; month <= maxMonth; month++) {
        const qty = 10 + Math.floor(Math.random() * 50);
        const cost = Math.round((50 + Math.random() * 500) * 100) / 100;
        const txDate = `${year}-${String(month).padStart(2, '0')}-15`;

        await client.query(`
          INSERT INTO stock_movements (product_id, movement_type, quantity, unit_cost, total_cost, notes, created_by, created_at)
          VALUES ($1, 'purchase', $2, $3, $4, $5, 'seed', $6)
        `, [prod.id, qty, cost, qty * cost, `Restock ${txDate}`, txDate]);
        stockCount++;
      }
    }
  }
  console.log(`  ✓ ${stockCount} stock movements seeded\n`);

  // ── 10. ASSET DEPRECIATION SCHEDULE (2025-2026) ────────────────────────
  console.log('10. Seeding asset depreciation schedule...');
  const assets = await client.query(`SELECT id, purchase_price, useful_life_years, depreciation_method FROM assets`);
  let depCount = 0;

  for (const asset of assets.rows) {
    const monthlyDep = Math.round(asset.purchase_price / (asset.useful_life_years * 12) * 100) / 100;
    let accumulated = 0;

    for (let year = 2025; year <= 2026; year++) {
      const maxMonth = year === 2026 ? 3 : 12;
      for (let month = 1; month <= maxMonth; month++) {
        accumulated += monthlyDep;
        const bookValue = Math.max(0, asset.purchase_price - accumulated);
        const periodDate = `${year}-${String(month).padStart(2, '0')}-28`;

        await client.query(`
          INSERT INTO asset_depreciation_schedule (asset_id, period_date, depreciation_method, amount, accumulated_total, book_value_after)
          VALUES ($1, $2, $3, $4, $5, $6)
        `, [asset.id, periodDate, asset.depreciation_method, monthlyDep, accumulated, bookValue]);
        depCount++;
      }
    }

    // Update asset running totals
    await client.query(`
      UPDATE assets SET accumulated_depreciation = $1, current_book_value = $2, last_depreciation_date = '2026-03-28' WHERE id = $3
    `, [accumulated, Math.max(0, asset.purchase_price - accumulated), asset.id]);
  }
  console.log(`  ✓ ${depCount} depreciation entries seeded\n`);

  // ── 11. SARS SUBMISSIONS (2020-2026) ───────────────────────────────────
  console.log('11. Seeding SARS submissions...');
  let sarsCount = 0;

  for (let year = 2020; year <= 2026; year++) {
    const maxMonth = year === 2026 ? 2 : 12;
    for (let month = 1; month <= maxMonth; month++) {
      // EMP201 monthly
      await client.query(`
        INSERT INTO sars_submissions (company_id, form_type, tax_period, status, form_data, created_by)
        VALUES ($1, 'EMP201', $2, 'submitted', $3, 'seed')
        ON CONFLICT DO NOTHING
      `, [companyId, `${year}-${String(month).padStart(2, '0')}`, JSON.stringify({ paye: 15000, uif: 1200, sdl: 800 })]);
      sarsCount++;

      // VAT201 bi-monthly (every 2 months)
      if (month % 2 === 0) {
        await client.query(`
          INSERT INTO sars_submissions (company_id, form_type, tax_period, status, form_data, created_by)
          VALUES ($1, 'VAT201', $2, 'submitted', $3, 'seed')
          ON CONFLICT DO NOTHING
        `, [companyId, `${year}-${String(month).padStart(2, '0')}`, JSON.stringify({ output: 35000, input: 12000, net: 23000 })]);
        sarsCount++;
      }
    }
  }
  console.log(`  ✓ ${sarsCount} SARS submissions seeded\n`);

  // ── 12. CUSTOMER PAYMENTS (2020-2026) ──────────────────────────────────
  console.log('12. Seeding customer payments...');
  let payCount = 0;

  for (let year = 2020; year <= 2026; year++) {
    const maxMonth = year === 2026 ? 3 : 12;
    for (let month = 1; month <= maxMonth; month++) {
      const numPayments = 2 + Math.floor(Math.random() * 4);
      for (let i = 0; i < numPayments; i++) {
        const customer = customers.rows[Math.floor(Math.random() * customers.rows.length)];
        const amount = Math.round((5000 + Math.random() * 80000) * 100) / 100;
        const payDate = `${year}-${String(month).padStart(2, '0')}-${String(10 + Math.floor(Math.random() * 18)).padStart(2, '0')}`;

        await client.query(`
          INSERT INTO customer_payments (company_id, customer_id, amount, payment_date, payment_method, reference, status, created_by)
          VALUES ($1, $2, $3, $4, 'eft', $5, 'confirmed', 'seed')
        `, [companyId, customer.id, amount, payDate, `RCP-${year}${String(month).padStart(2, '0')}-${i + 1}`]);
        payCount++;
      }
    }
  }
  console.log(`  ✓ ${payCount} customer payments seeded\n`);

  // ── 13. SUPPLIER PAYMENTS (2020-2026) ──────────────────────────────────
  console.log('13. Seeding supplier payments...');
  let supPayCount = 0;

  for (let year = 2020; year <= 2026; year++) {
    const maxMonth = year === 2026 ? 3 : 12;
    for (let month = 1; month <= maxMonth; month++) {
      const numPayments = 2 + Math.floor(Math.random() * 3);
      for (let i = 0; i < numPayments; i++) {
        const supplier = suppliers.rows[Math.floor(Math.random() * suppliers.rows.length)];
        const amount = Math.round((3000 + Math.random() * 40000) * 100) / 100;
        const payDate = `${year}-${String(month).padStart(2, '0')}-${String(15 + Math.floor(Math.random() * 13)).padStart(2, '0')}`;

        await client.query(`
          INSERT INTO supplier_payments (company_id, supplier_id, total_amount, payment_date, payment_method, reference, status, created_by)
          VALUES ($1, $2, $3, $4, 'eft', $5, 'confirmed', 'seed')
        `, [companyId, supplier.id, amount, payDate, `PAY-${year}${String(month).padStart(2, '0')}-${i + 1}`]);
        supPayCount++;
      }
    }
  }
  console.log(`  ✓ ${supPayCount} supplier payments seeded\n`);

  // ── SUMMARY ────────────────────────────────────────────────────────────
  console.log('=== SEED COMPLETE ===\n');
  const counts = await client.query(`
    SELECT
      (SELECT COUNT(*) FROM gl_journal_entries) as journal_entries,
      (SELECT COUNT(*) FROM gl_journal_lines) as journal_lines,
      (SELECT COUNT(*) FROM customer_invoices) as customer_invoices,
      (SELECT COUNT(*) FROM supplier_invoices) as supplier_invoices,
      (SELECT COUNT(*) FROM customer_payments) as customer_payments,
      (SELECT COUNT(*) FROM supplier_payments) as supplier_payments,
      (SELECT COUNT(*) FROM bank_transactions) as bank_transactions,
      (SELECT COUNT(*) FROM payroll_runs) as payroll_runs,
      (SELECT COUNT(*) FROM payslips) as payslips,
      (SELECT COUNT(*) FROM leave_applications) as leave_applications,
      (SELECT COUNT(*) FROM purchase_orders) as purchase_orders,
      (SELECT COUNT(*) FROM stock_movements) as stock_movements,
      (SELECT COUNT(*) FROM asset_depreciation_schedule) as depreciation_entries,
      (SELECT COUNT(*) FROM sars_submissions) as sars_submissions
  `);
  console.log('Final record counts:');
  for (const [key, value] of Object.entries(counts.rows[0])) {
    console.log(`  ${key}: ${value}`);
  }

  await client.end();
}

seed().catch(err => { console.error('SEED FAILED:', err.message); process.exit(1); });

