      const sup = suppliers[Math.floor(Math.random() * suppliers.length)];
      const subtotal = Math.round((5000+Math.random()*50000)*100)/100;
      const tax = Math.round(subtotal*0.15*100)/100;
      const num = 'PO-2026' + m + '-' + String(i+1).padStart(3,'0');
      const pr = await c.query('INSERT INTO purchase_orders (company_id,po_number,supplier_id,order_date,status,subtotal,tax_amount,total,created_by) VALUES (\$1,\$2,\$3,\$4,\$5,\$6,\$7,\$8,\$9) ON CONFLICT DO NOTHING RETURNING id', [companyId, num, sup.id, monthStr+'-05', 'approved', subtotal, tax, subtotal+tax, uid]);
      if (pr.rows[0]) {
        const qty = 10+Math.floor(Math.random()*40);
        await c.query('INSERT INTO po_items (purchase_order_id,description,quantity,unit_price,tax_rate,line_total,tax_amount,quantity_received,sort_order) VALUES (\$1,\$2,\$3,\$4,15,\$5,\$6,0,0)', [pr.rows[0].id, 'Materials for '+num, qty, Math.round(subtotal/qty*100)/100, subtotal, tax]);
      }
    }
    counts['po_' + m] = 2;

    // Additional customer payments
    for (let i = 0; i < 3; i++) {
      const cust = customers[Math.floor(Math.random() * customers.length)];
      const amount = Math.round((10000+Math.random()*80000)*100)/100;
      await c.query('INSERT INTO customer_payments (company_id,client_id,total_amount,payment_date,payment_method,payment_number,status,created_by) VALUES (\$1,\$2,\$3,\$4,\$5,\$6,\$7,\$8)', [companyId, cust.id, amount, monthStr+'-'+String(10+Math.floor(Math.random()*18)).padStart(2,'0'), 'eft', 'RCP-2026'+m+'-SEED-'+(i+1), 'confirmed', uid]);
    }
    counts['cp_' + m] = 3;

    // Additional supplier payments
    for (let i = 0; i < 2; i++) {
      const sup = suppliers[Math.floor(Math.random() * suppliers.length)];
      const amount = Math.round((5000+Math.random()*40000)*100)/100;
      await c.query('INSERT INTO supplier_payments (company_id,supplier_id,total_amount,payment_date,payment_method,payment_number,reference,status,created_by) VALUES (\$1,\$2,\$3,\$4,\$5,\$6,\$7,\$8,\$9)', [companyId, sup.id, amount, monthStr+'-'+String(15+Math.floor(Math.random()*13)).padStart(2,'0'), 'eft', 'PAY-2026'+m+'-SEED-'+(i+1), 'PAY-ref', 'processed', uid]);
    }
    counts['sp_' + m] = 2;

    // Leave balances for 2026
    for (const emp of employees) {
      for (const lt of leaveTypes) {
        const accrued = lt.code === 'annual' ? 15 : lt.code === 'sick' ? 10 : lt.code === 'family_responsibility' ? 3 : 0;
        await c.query('INSERT INTO leave_balances (employee_id,leave_type_id,leave_type_code,year,accrued,taken,closing_balance) VALUES (\$1,\$2,\$3,2026,\$4,0,\$5) ON CONFLICT (employee_id,leave_type_code,year) DO NOTHING', [emp.id, lt.id, lt.code, accrued, accrued]);
      }
    }
  }

  console.log('\\n=== JAN-FEB 2026 SEEDED ===');
  for (const [k,v] of Object.entries(counts)) console.log('  ' + k + ': ' + v);

  // Final totals
  const r = await c.query('SELECT (SELECT COUNT(*) FROM bank_transactions WHERE transaction_date >= \\'2026-01-01\\' AND transaction_date < \\'2026-03-01\\') as bt, (SELECT COUNT(*) FROM payroll_runs WHERE period_start >= \\'2026-01-01\\' AND period_start < \\'2026-03-01\\') as pr, (SELECT COUNT(*) FROM sars_submissions WHERE period_start >= \\'2026-01-01\\' AND period_start < \\'2026-03-01\\') as sars, (SELECT COUNT(*) FROM leave_applications WHERE start_date >= \\'2026-01-01\\') as la, (SELECT COUNT(*) FROM purchase_orders WHERE order_date >= \\'2026-01-01\\' AND order_date < \\'2026-03-01\\') as po');
  console.log('\\nJan-Feb 2026 totals:');
  for (const [k,v] of Object.entries(r.rows[0])) console.log('  ' + k + ': ' + v);

  await c.end();
}
run().catch(e => { console.error(e.message); process.exit(1); });
