/**
 * Payroll Run Detail Page
 * View run summary, payslips, complete/reverse, download payslips.
 * Route: /payroll/runs/[runId]
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  CalendarDays, Loader2, AlertCircle, ArrowLeft,
  CheckCircle, RotateCcw, FileText, Download,
} from 'lucide-react';
import Link from 'next/link';
import { notify } from '@/utils/toast';

interface Payslip {
  id: string;
  employee_number?: string;
  first_name?: string;
  last_name?: string;
  department?: string;
  basic_salary: number;
  travel_allowance: number;
  housing_allowance: number;
  cell_allowance: number;
  other_allowances: number;
  gross_pay: number;
  paye: number;
  uif_employee: number;
  uif_employer: number;
  sdl: number;
  medical_aid: number;
  retirement_fund: number;
  other_deductions: number;
  total_deductions: number;
  net_pay: number;
  ytd_gross: number;
  ytd_paye: number;
}

interface PayrollRunDetail {
  id: string;
  period_start: string;
  period_end: string;
  run_date: string;
  status: string;
  total_gross: number;
  total_paye: number;
  total_uif_employee: number;
  total_uif_employer: number;
  total_sdl: number;
  total_net: number;
  total_company_cost: number;
  journal_entry_id: string | null;
  payslips: Payslip[];
}

