/**
 * Purchase Order Detail Page
 * View purchase order information
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, ClipboardList, Loader2, AlertCircle } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const STATUS_COLORS: Record<string, string> = {
  draft: 'bg-gray-500/20 text-gray-400',
  pending: 'bg-amber-500/20 text-amber-400',
  approved: 'bg-blue-500/20 text-blue-400',
  sent: 'bg-indigo-500/20 text-indigo-400',
  received: 'bg-teal-500/20 text-teal-400',
  partially_received: 'bg-purple-500/20 text-purple-400',
  cancelled: 'bg-gray-500/20 text-gray-500',
  closed: 'bg-gray-500/20 text-gray-500',
};

interface PurchaseOrder {
  id: string;
  po_number: string;
  supplier_name: string | null;
  supplier_id: string | null;
  order_date: string | null;
  expected_delivery_date: string | null;
  status: string;
  subtotal: number;
  tax_amount: number;
  total: number;
  notes: string | null;
  reference: string | null;
  created_at: string;
}

export default function PurchaseOrderDetailPage() {
  const router = useRouter();
  const { poId } = router.query;
  const [po, setPo] = useState<PurchaseOrder | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!poId) return;
    loadPO();
  }, [poId]);

  const loadPO = async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/accounting/purchase-orders?id=${poId}`);
      const json = await res.json();
      const data = json.data || json;
      // API may return a single object or an array — find matching record
      if (Array.isArray(data)) {
        const match = data.find((p: PurchaseOrder) => p.id === poId);
        setPo(match || null);
        if (!match) setError('Purchase order not found');
      } else {
        setPo(data);
      }
    } catch {
      setError('Failed to load purchase order');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh]">
          <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
        </div>
      </AppLayout>
    );
  }

  if (!po) {
    return (
      <AppLayout>
        <div className="flex items-center justify-center min-h-[60vh] flex-col">
          <AlertCircle className="h-8 w-8 text-red-400 mb-2" />
          <p className="text-[var(--ff-text-secondary)]">{error || 'Purchase order not found'}</p>
          <Link href="/accounting/purchase-orders" className="mt-4 text-sm text-blue-400 hover:text-blue-300">
            Back to Purchase Orders
          </Link>
        </div>
      </AppLayout>
    );
  }

  const fields: { label: string; value: string | number | null | undefined; highlight?: boolean }[] = [
    { label: 'PO Number', value: po.po_number, highlight: true },
    { label: 'Supplier', value: po.supplier_name },
    { label: 'Order Date', value: po.order_date?.split('T')[0] },
    { label: 'Expected Delivery', value: po.expected_delivery_date?.split('T')[0] },
    { label: 'Reference', value: po.reference },
    { label: 'Subtotal', value: fmt(Number(po.subtotal)) },
    { label: 'Tax', value: fmt(Number(po.tax_amount)) },
    { label: 'Total', value: fmt(Number(po.total)), highlight: true },
  ];

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/purchase-orders" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Purchase Orders
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-blue-500/10">
              <ClipboardList className="h-6 w-6 text-blue-500" />
            </div>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">{po.po_number}</h1>
              {po.supplier_name && (
                <p className="text-sm text-[var(--ff-text-secondary)]">{po.supplier_name}</p>
              )}
            </div>
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${STATUS_COLORS[po.status] || 'bg-gray-500/20 text-gray-400'}`}>
              {po.status.replace(/_/g, ' ')}
            </span>
          </div>
        </div>

        {/* Details */}
        <div className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {fields.map((f, i) => (
              <div key={i} className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
                <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{f.label}</p>
                <p className={`text-lg font-semibold mt-1 ${f.highlight ? 'text-blue-400' : 'text-[var(--ff-text-primary)]'}`}>
                  {f.value || '—'}
                </p>
              </div>
            ))}
          </div>

          {/* Notes */}
          {po.notes && (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
              <p className="text-xs text-[var(--ff-text-tertiary)] uppercase mb-1">Notes</p>
              <p className="text-sm text-[var(--ff-text-secondary)]">{po.notes}</p>
            </div>
          )}

          {/* Created info */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
            <p className="text-xs text-[var(--ff-text-tertiary)] uppercase mb-1">Created</p>
            <p className="text-sm text-[var(--ff-text-secondary)]">{po.created_at?.split('T')[0] || '—'}</p>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Purchase Orders API — CRUD
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validatePurchaseOrder, calculatePOTotals, generatePONumber } from '@/modules/accounting/services/procurementService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = (req as any).companyId as string | undefined;

  if (req.method === 'GET') {
    const { status, supplierId } = req.query;
    let rows: Row[];
    if (status) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.status = ${String(status)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else if (supplierId) {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id WHERE po.supplier_id = ${String(supplierId)} ORDER BY po.created_at DESC LIMIT 200` as Row[];
    } else {
      rows = await sql`SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON po.supplier_id = s.id ORDER BY po.created_at DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validatePurchaseOrder(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const totals = calculatePOTotals(body.items);
    const countRes = await sql`SELECT COUNT(*) as cnt FROM purchase_orders` as Row[];
    const poNumber = generatePONumber(Number((countRes[0] as any)?.cnt || 0));

    const inserted = await sql`
      INSERT INTO purchase_orders (company_id, po_number, supplier_id, order_date, expected_delivery_date, subtotal, tax_amount, total, notes, reference, created_by)
      VALUES (${companyId || null}, ${poNumber}, ${body.supplierId}, ${body.orderDate || new Date().toISOString().split('T')[0]}, ${body.expectedDeliveryDate || null}, ${totals.subtotal}, ${totals.taxAmount}, ${totals.total}, ${body.notes || null}, ${body.reference || null}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    const poId = String(inserted[0]?.id);
    for (let i = 0; i < body.items.length; i++) {
      const item = body.items[i];
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const lineTax = Math.round(lineTotal * (item.taxRate || 15) / 100 * 100) / 100;
      await sql`INSERT INTO po_items (purchase_order_id, product_id, description, quantity, unit_price, tax_rate, line_total, tax_amount, sort_order) VALUES (${poId}, ${item.productId || null}, ${item.description}, ${item.quantity}, ${item.unitPrice}, ${item.taxRate || 15}, ${lineTotal}, ${lineTax}, ${i})`;
    }

    log.info('Purchase order created', { poNumber, supplier: body.supplierId, total: totals.total }, 'accounting');
    return apiResponse.created(res, { ...inserted[0], items: body.items });
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

