/**
 * Customer Quote Service — Sage-parity quotes with convert-to-invoice
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface QuoteLine {
  id: string;
  quoteId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
  accountId: string | null;
}

export interface Quote {
  id: string;
  quoteNumber: string;
  clientId: string | null;
  customerName: string;
  quoteDate: string;
  expiryDate: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  total: number;
  notes: string | null;
  terms: string | null;
  convertedInvoiceId: string | null;
  createdAt: string;
  updatedAt: string;
  lines?: QuoteLine[];
}

interface QuoteFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface QuoteInput {
  customerName: string;
  clientId?: string;
  quoteDate?: string;
  expiryDate?: string;
  notes?: string;
  terms?: string;
  lines: { description: string; quantity: number; unitPrice: number; taxRate?: number; accountId?: string }[];
}

function mapQuote(r: Row): Quote {
  return {
    id: r.id, quoteNumber: r.quote_number, clientId: r.client_id,
    customerName: r.customer_name, quoteDate: r.quote_date,
    expiryDate: r.expiry_date, status: r.status,
    subtotal: Number(r.subtotal), taxAmount: Number(r.tax_amount),
    total: Number(r.total), notes: r.notes, terms: r.terms,
    convertedInvoiceId: r.converted_invoice_id,
    createdAt: r.created_at, updatedAt: r.updated_at,
  };
}

function mapLine(r: Row): QuoteLine {
  return {
    id: r.id, quoteId: r.quote_id, lineNumber: r.line_number,
    description: r.description, quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price), taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total), accountId: r.account_id,
  };
}

async function nextQuoteNumber(): Promise<string> {
  const rows = (await sql`
    SELECT quote_number FROM customer_quotes ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  if (rows.length === 0) return 'QUO-00001';
  const last = rows[0].quote_number;
  const num = parseInt(last.replace('QUO-', ''), 10) || 0;
  return `QUO-${String(num + 1).padStart(5, '0')}`;
}

function calcTotals(lines: QuoteInput['lines']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const l of lines) {
    const lt = l.quantity * l.unitPrice;
    subtotal += lt;
    taxAmount += lt * ((l.taxRate ?? 15) / 100);
  }
  return { subtotal: Math.round(subtotal * 100) / 100, taxAmount: Math.round(taxAmount * 100) / 100, total: Math.round((subtotal + taxAmount) * 100) / 100 };
}

export async function getQuotes(_companyId: string, filters?: QuoteFilters): Promise<{ quotes: Quote[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT * FROM customer_quotes
      WHERE (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes
      WHERE (quote_number ILIKE ${pattern} OR customer_name ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT * FROM customer_quotes WHERE status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_quotes WHERE status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM customer_quotes ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM customer_quotes`) as Row[];
  }
  return { quotes: rows.map(mapQuote), total: Number(countRows[0]?.cnt || 0) };
}

export async function getQuote(_companyId: string, id: string): Promise<Quote | null> {
  const rows = (await sql`SELECT * FROM customer_quotes WHERE id = ${id}::UUID`) as Row[];
  if (rows.length === 0) return null;
  const quote = mapQuote(rows[0]);
  const lineRows = (await sql`
    SELECT * FROM customer_quote_lines WHERE quote_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  quote.lines = lineRows.map(mapLine);
  return quote;
}

export async function createQuote(_companyId: string, input: QuoteInput, userId?: string): Promise<Quote> {
  const quoteNumber = await nextQuoteNumber();
  const { subtotal, taxAmount, total } = calcTotals(input.lines);
  const qd = input.quoteDate || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_quotes (quote_number, client_id, customer_name, quote_date, expiry_date,
      subtotal, tax_amount, total, notes, terms, created_by)
    VALUES (${quoteNumber}, ${input.clientId || null}, ${input.customerName}, ${qd},
      ${input.expiryDate || null}, ${subtotal}, ${taxAmount}, ${total},
      ${input.notes || null}, ${input.terms || null}, ${userId || null})
    RETURNING *
  `) as Row[];

  const quote = mapQuote(rows[0]);
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${quote.id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote created', { quoteNumber, total });
  return (await getQuote('', quote.id))!;
}

export async function updateQuote(_companyId: string, id: string, input: QuoteInput): Promise<Quote | null> {
  const existing = await getQuote('', id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, total } = calcTotals(input.lines);

  await sql`
    UPDATE customer_quotes SET customer_name = ${input.customerName}, client_id = ${input.clientId || null},
      quote_date = ${input.quoteDate || existing.quoteDate}, expiry_date = ${input.expiryDate || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total = ${total},
      notes = ${input.notes || null}, terms = ${input.terms || null}, updated_at = NOW()
    WHERE id = ${id}::UUID AND status = 'draft'
  `;
  await sql`DELETE FROM customer_quote_lines WHERE quote_id = ${id}::UUID`;
  for (let i = 0; i < input.lines.length; i++) {
    const l = input.lines[i];
    if (!l) continue;
    const lineTotal = Math.round(l.quantity * l.unitPrice * 100) / 100;
    await sql`
      INSERT INTO customer_quote_lines (quote_id, line_number, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${id}::UUID, ${i + 1}, ${l.description}, ${l.quantity}, ${l.unitPrice}, ${l.taxRate ?? 15}, ${lineTotal}, ${l.accountId || null})
    `;
  }
  log.info('Quote updated', { id });
  return getQuote('', id);
}

export async function deleteQuote(_companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`DELETE FROM customer_quotes WHERE id = ${id}::UUID AND status = 'draft' RETURNING id`) as Row[];
  return rows.length > 0;
}

export async function updateQuoteStatus(_companyId: string, id: string, status: string): Promise<Quote | null> {
  await sql`UPDATE customer_quotes SET status = ${status}, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Quote status changed', { id, status });
  return getQuote('', id);
}

export async function convertToInvoice(_companyId: string, id: string, userId?: string): Promise<{ quote: Quote; invoiceId: string } | null> {
  const quote = await getQuote('', id);
  if (!quote || quote.status !== 'accepted') return null;

  // Create invoice from quote
  const invRows = (await sql`
    INSERT INTO customer_invoices (client_id, invoice_date, due_date, subtotal, tax_amount, total, notes, status, created_by)
    VALUES (${quote.clientId}, ${quote.quoteDate}, ${quote.expiryDate || quote.quoteDate}, ${quote.subtotal},
      ${quote.taxAmount}, ${quote.total}, ${'Converted from ' + quote.quoteNumber}, 'draft', ${userId || null})
    RETURNING id
  `) as Row[];
  const invoiceId = invRows[0].id;

  // Copy lines
  for (const line of quote.lines || []) {
    await sql`
      INSERT INTO customer_invoice_items (invoice_id, description, quantity, unit_price, tax_rate, line_total, account_id)
      VALUES (${invoiceId}::UUID, ${line.description}, ${line.quantity}, ${line.unitPrice}, ${line.taxRate}, ${line.lineTotal}, ${line.accountId})
    `;
  }

  await sql`UPDATE customer_quotes SET status = 'converted', converted_invoice_id = ${invoiceId}::UUID, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Quote converted to invoice', { quoteId: id, invoiceId });
  return { quote: (await getQuote('', id))!, invoiceId };
}

/**
 * Supplier Invoice Actions API
 * POST /api/accounting/supplier-invoices-action
 *   action: approve | cancel | match
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  approveSupplierInvoice,
  cancelSupplierInvoice,
  performThreeWayMatch,
} from '@/modules/accounting/services/supplierInvoiceService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, invoiceId } = req.body;
    const userId = req.user.id;

    if (!action || !invoiceId) {
      return apiResponse.badRequest(res, 'action and invoiceId are required');
    }

    switch (action) {
      case 'approve': {
        const invoice = await approveSupplierInvoice(companyId, invoiceId, userId);
        return apiResponse.success(res, invoice);
      }
      case 'cancel': {
        const invoice = await cancelSupplierInvoice(companyId, invoiceId);
        return apiResponse.success(res, invoice);
      }
      case 'match': {
        const result = await performThreeWayMatch(companyId, invoiceId);
        return apiResponse.success(res, result);
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Supplier invoice action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Customer Sales Order Service — CRUD with items
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface SalesOrderItem {
  id: string;
  salesOrderId: string;
  lineNumber: number;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  lineTotal: number;
}

export interface SalesOrder {
  id: string;
  orderNumber: string;
  customerId: string | null;
  customerName: string;
  orderDate: string;
  deliveryDate: string | null;
  reference: string | null;
  status: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  notes: string | null;
  internalNotes: string | null;
  createdAt: string;
  updatedAt: string;
  items?: SalesOrderItem[];
}

interface SalesOrderFilters {
  status?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

interface SalesOrderInput {
  customer_id?: string;
  order_date?: string;
  delivery_date?: string;
  reference?: string;
  notes?: string;
  internal_notes?: string;
  items: { description: string; quantity: number; unit_price: number; tax_rate?: number }[];
}

function mapOrder(r: Row): SalesOrder {
  return {
    id: r.id,
    orderNumber: r.order_number,
    customerId: r.customer_id,
    customerName: r.customer_name || '',
    orderDate: r.order_date,
    deliveryDate: r.delivery_date,
    reference: r.reference,
    status: r.status,
    subtotal: Number(r.subtotal),
    taxAmount: Number(r.tax_amount),
    totalAmount: Number(r.total_amount),
    notes: r.notes,
    internalNotes: r.internal_notes,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function mapItem(r: Row): SalesOrderItem {
  return {
    id: r.id,
    salesOrderId: r.sales_order_id,
    lineNumber: r.line_number,
    description: r.description,
    quantity: Number(r.quantity),
    unitPrice: Number(r.unit_price),
    taxRate: Number(r.tax_rate),
    lineTotal: Number(r.line_total),
  };
}

async function nextOrderNumber(companyId: string): Promise<string> {
  // Use company_document_numbers for sequential numbering
  const rows = (await sql`
    INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number)
    VALUES (${companyId}::UUID, 'sales_order', 'SO-', 1)
    ON CONFLICT (company_id, document_type)
    DO UPDATE SET next_number = company_document_numbers.next_number + 1
    RETURNING next_number - 1 AS current_number, prefix
  `) as Row[];

  if (rows.length === 0) return 'SO-00001';
  const num = Number(rows[0].current_number);
  const prefix = rows[0].prefix || 'SO-';
  return `${prefix}${String(num).padStart(5, '0')}`;
}

function calcTotals(items: SalesOrderInput['items']) {
  let subtotal = 0;
  let taxAmount = 0;
  for (const item of items) {
    const lt = item.quantity * item.unit_price;
    subtotal += lt;
    taxAmount += lt * ((item.tax_rate ?? 15) / 100);
  }
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    taxAmount: Math.round(taxAmount * 100) / 100,
    totalAmount: Math.round((subtotal + taxAmount) * 100) / 100,
  };
}

export async function getSalesOrders(companyId: string, filters?: SalesOrderFilters): Promise<{ orders: SalesOrder[]; total: number }> {
  const limit = filters?.limit || 100;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.search && filters?.status) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND so.status = ${filters.status}
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND so.status = ${filters.status}
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.search) {
    const pattern = `%${filters.search}%`;
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
        AND (so.order_number ILIKE ${pattern} OR c.name ILIKE ${pattern} OR so.reference ILIKE ${pattern})
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID AND so.status = ${filters.status}
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_sales_orders so
      WHERE so.company_id = ${companyId}::UUID AND so.status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT so.*, c.name AS customer_name
      FROM customer_sales_orders so
      LEFT JOIN customers c ON c.id = so.customer_id
      WHERE so.company_id = ${companyId}::UUID
      ORDER BY so.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM customer_sales_orders so
      WHERE so.company_id = ${companyId}::UUID
    `) as Row[];
  }

  return { orders: rows.map(mapOrder), total: Number(countRows[0]?.cnt || 0) };
}

export async function getSalesOrder(companyId: string, id: string): Promise<SalesOrder | null> {
  const rows = (await sql`
    SELECT so.*, c.name AS customer_name
    FROM customer_sales_orders so
    LEFT JOIN customers c ON c.id = so.customer_id
    WHERE so.id = ${id}::UUID AND so.company_id = ${companyId}::UUID
  `) as Row[];
  if (rows.length === 0) return null;
  const order = mapOrder(rows[0]);
  const itemRows = (await sql`
    SELECT * FROM customer_sales_order_items
    WHERE sales_order_id = ${id}::UUID ORDER BY line_number
  `) as Row[];
  order.items = itemRows.map(mapItem);
  return order;
}

export async function createSalesOrder(companyId: string, input: SalesOrderInput, userId?: string): Promise<SalesOrder> {
  const orderNumber = await nextOrderNumber(companyId);
  const { subtotal, taxAmount, totalAmount } = calcTotals(input.items);
  const orderDate = input.order_date || new Date().toISOString().split('T')[0];

  const rows = (await sql`
    INSERT INTO customer_sales_orders (
      company_id, order_number, customer_id, order_date, delivery_date,
      reference, subtotal, tax_amount, total_amount, notes, internal_notes, created_by
    ) VALUES (
      ${companyId}::UUID, ${orderNumber}, ${input.customer_id || null},
      ${orderDate}, ${input.delivery_date || null}, ${input.reference || null},
      ${subtotal}, ${taxAmount}, ${totalAmount},
      ${input.notes || null}, ${input.internal_notes || null}, ${userId || null}
    ) RETURNING *
  `) as Row[];

  const order = mapOrder(rows[0]);
  for (let i = 0; i < input.items.length; i++) {
    const item = input.items[i];
    if (!item) continue;
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    await sql`
      INSERT INTO customer_sales_order_items (
        sales_order_id, line_number, description, quantity, unit_price, tax_rate, line_total
      ) VALUES (
        ${order.id}::UUID, ${i + 1}, ${item.description}, ${item.quantity},
        ${item.unit_price}, ${item.tax_rate ?? 15}, ${lineTotal}
      )
    `;
  }
  log.info('Sales order created', { orderNumber, totalAmount });
  return (await getSalesOrder(companyId, order.id))!;
}

export async function updateSalesOrder(companyId: string, id: string, input: SalesOrderInput): Promise<SalesOrder | null> {
  const existing = await getSalesOrder(companyId, id);
  if (!existing || existing.status !== 'draft') return null;
  const { subtotal, taxAmount, totalAmount } = calcTotals(input.items);

  await sql`
    UPDATE customer_sales_orders SET
      customer_id = ${input.customer_id || existing.customerId},
      order_date = ${input.order_date || existing.orderDate},
      delivery_date = ${input.delivery_date || null},
      reference = ${input.reference || null},
      subtotal = ${subtotal}, tax_amount = ${taxAmount}, total_amount = ${totalAmount},
      notes = ${input.notes || null}, internal_notes = ${input.internal_notes || null},
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
  `;

  await sql`DELETE FROM customer_sales_order_items WHERE sales_order_id = ${id}::UUID`;
  for (let i = 0; i < input.items.length; i++) {
    const item = input.items[i];
    if (!item) continue;
    const lineTotal = Math.round(item.quantity * item.unit_price * 100) / 100;
    await sql`
      INSERT INTO customer_sales_order_items (
        sales_order_id, line_number, description, quantity, unit_price, tax_rate, line_total
      ) VALUES (
        ${id}::UUID, ${i + 1}, ${item.description}, ${item.quantity},
        ${item.unit_price}, ${item.tax_rate ?? 15}, ${lineTotal}
      )
    `;
  }
  log.info('Sales order updated', { id });
  return getSalesOrder(companyId, id);
}

export async function deleteSalesOrder(companyId: string, id: string): Promise<boolean> {
  const rows = (await sql`
    DELETE FROM customer_sales_orders
    WHERE id = ${id}::UUID AND company_id = ${companyId}::UUID AND status = 'draft'
    RETURNING id
  `) as Row[];
  return rows.length > 0;
}

/**
 * Create Supplier Invoice Page
 * PRD-060 Phase 2: Capture invoice with line items
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Receipt, Plus, Trash2, Loader2, Info } from 'lucide-react';
import { ScanAndFillButton } from '@/components/accounting/ScanAndFillButton';
import { fuzzyMatchSupplier } from '@/modules/accounting/utils/fuzzyMatch';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

interface LineItem {
  key: string;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  glAccountId: string;
}

import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface Supplier { id: number; name: string }
interface GLAccount { id: string; accountCode: string; accountName: string }

export default function NewSupplierInvoicePage() {
  const router = useRouter();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [glAccounts, setGLAccounts] = useState<GLAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [scanBanner, setScanBanner] = useState<string | null>(null);

  const [form, setForm] = useState({
    invoiceNumber: '',
    supplierId: '',
    invoiceDate: new Date().toISOString().split('T')[0],
    dueDate: '',
    paymentTerms: 'net30',
    reference: '',
    notes: '',
    taxRate: 15,
  });

  const [lines, setLines] = useState<LineItem[]>([
    { key: crypto.randomUUID(), description: '', quantity: 1, unitPrice: 0, taxRate: 15, glAccountId: '' },
  ]);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/accounting/suppliers-list').then(r => r.json()),
      apiFetch('/api/accounting/chart-of-accounts').then(r => r.json()),
    ]).then(([suppRes, accRes]) => {
      const suppData = suppRes.data || suppRes;
      setSuppliers(Array.isArray(suppData) ? suppData : suppData.suppliers || []);
      const accData = accRes.data || accRes;
      setGLAccounts(Array.isArray(accData) ? accData.filter((a: GLAccount) => a.accountCode >= '5000') : []);
    });
  }, []);

  const addLine = () => {
    setLines(prev => [...prev, {
      key: crypto.randomUUID(), description: '', quantity: 1, unitPrice: 0,
      taxRate: form.taxRate, glAccountId: '',
    }]);
  };

  const updateLine = (key: string, field: keyof LineItem, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };

  const removeLine = (key: string) => {
    if (lines.length <= 1) return;
    setLines(prev => prev.filter(l => l.key !== key));
  };

  const subtotal = lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0);
  const totalTax = lines.reduce((sum, l) => sum + (l.quantity * l.unitPrice * l.taxRate / 100), 0);
  const total = subtotal + totalTax;

  function handleExtracted(data: ExtractedDocument) {
    const updates: Partial<typeof form> = {};
    if (data.referenceNumber) updates.invoiceNumber = data.referenceNumber;
    if (data.date) updates.invoiceDate = data.date;
    if (data.dueDate) updates.dueDate = data.dueDate;
    if (data.purchaseOrderRef) updates.reference = data.purchaseOrderRef;
    if (data.vatRate !== null) updates.taxRate = data.vatRate;

    // Map payment terms
    if (data.paymentTerms) {
      const pt = data.paymentTerms.toLowerCase();
      if (pt.includes('immediate') || pt.includes('cod') || pt.includes('0 day')) updates.paymentTerms = 'immediate';
      else if (pt.includes('30')) updates.paymentTerms = 'net30';
      else if (pt.includes('60')) updates.paymentTerms = 'net60';
      else if (pt.includes('90')) updates.paymentTerms = 'net90';
    }

    setForm(f => ({ ...f, ...updates }));

    // Fuzzy match supplier
    if (data.vendorName && suppliers.length > 0) {
      const match = fuzzyMatchSupplier(data.vendorName, suppliers.map(s => ({ id: String(s.id), name: s.name })));
      if (match) {
        setForm(f => ({ ...f, supplierId: String(match.id) }));
      }
    }

    // Populate line items
    if (data.lineItems.length > 0) {
      setLines(data.lineItems.map(li => ({
        key: crypto.randomUUID(),
        description: li.description,
        quantity: li.quantity ?? 1,
        unitPrice: li.unitPrice ?? 0,
        taxRate: data.vatRate ?? form.taxRate,
        glAccountId: '',
      })));
    }

    setScanBanner(`Auto-filled from document (${Math.round(data.confidence * 100)}% confidence). Review all fields before submitting.`);
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/supplier-invoices', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          invoiceNumber: form.invoiceNumber,
          supplierId: form.supplierId,
          invoiceDate: form.invoiceDate,
          dueDate: form.dueDate || undefined,
          paymentTerms: form.paymentTerms || undefined,
          reference: form.reference || undefined,
          notes: form.notes || undefined,
          taxRate: form.taxRate,
          items: lines.map(l => ({
            description: l.description,
            quantity: l.quantity,
            unitPrice: l.unitPrice,
            taxRate: l.taxRate,
            glAccountId: l.glAccountId || undefined,
          })),
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error?.message || 'Failed to create invoice');
      }

      const json = await res.json();
      const invoice = json.data || json;
      router.push(`/accounting/supplier-invoices/${invoice.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create invoice');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
