            {/* Totals */}
            <div className="mt-4 pt-4 border-t border-[var(--ff-border-light)] flex justify-end">
              <div className="w-64 space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--ff-text-secondary)]">Subtotal</span>
                  <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(subtotal)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--ff-text-secondary)]">VAT</span>
                  <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(totalTax)}</span>
                </div>
                <div className="flex justify-between text-base font-bold border-t border-[var(--ff-border-medium)] pt-2">
                  <span className="text-[var(--ff-text-primary)]">Total</span>
                  <span className="font-mono text-teal-500">{formatCurrency(total)}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Notes */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
            <textarea value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
              className="ff-input w-full" rows={3} placeholder="Optional notes..." />
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/supplier-invoices"
              className="px-4 py-2 border border-[var(--ff-border-medium)] rounded-lg text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm font-medium">
              Cancel
            </Link>
            <button type="submit" disabled={isSubmitting}
              className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Invoice
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Supplier Payments API
 * GET  /api/accounting/supplier-payments - List payments
 * POST /api/accounting/supplier-payments - Create payment with allocations
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getSupplierPayments,
  getSupplierPaymentById,
  createSupplierPayment,
} from '@/modules/accounting/services/supplierPaymentService';
import type { PaymentStatus } from '@/modules/accounting/types/ap.types';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { id, status, supplier_id, limit, offset } = req.query;

      // Single payment by ID
      if (id) {
        const payment = await getSupplierPaymentById(companyId, id as string);
        if (!payment) return apiResponse.notFound(res, 'Payment', id as string);
        return apiResponse.success(res, payment);
      }

      const result = await getSupplierPayments(companyId, {
        status: status as PaymentStatus | undefined,
        supplierId: supplier_id ? Number(supplier_id) : undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get supplier payments', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get supplier payments');
    }
  }

  if (req.method === 'POST') {
    try {
      const { supplierId, paymentDate, totalAmount, paymentMethod,
        bankAccountId, reference, description, allocations } = req.body;

      if (!supplierId || !paymentDate || !totalAmount || !allocations || !Array.isArray(allocations)) {
        return apiResponse.badRequest(res, 'supplierId, paymentDate, totalAmount, and allocations are required');
      }

      // User identity comes from JWT (req.user), never from client request body
      const userId = req.user.id;

      const payment = await createSupplierPayment(companyId, {
        supplierId: Number(supplierId),
        paymentDate, totalAmount: Number(totalAmount),
        paymentMethod, bankAccountId, reference, description,
        allocations,
      }, userId);

      return apiResponse.created(res, payment);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create payment';
      log.error('Failed to create supplier payment', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Supplier Payment Actions API
 * POST /api/accounting/supplier-payments-action
 *   action: approve | process
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  approveSupplierPayment,
  processSupplierPayment,
} from '@/modules/accounting/services/supplierPaymentService';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { action, paymentId } = req.body;
    const userId = req.user.id;

    if (!action || !paymentId) {
      return apiResponse.badRequest(res, 'action and paymentId are required');
    }

    switch (action) {
      case 'approve': {
        const payment = await approveSupplierPayment(companyId, paymentId, userId);
        return apiResponse.success(res, payment);
      }
      case 'process': {
        const payment = await processSupplierPayment(companyId, paymentId, userId);
        return apiResponse.success(res, payment);
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Supplier payment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Create Supplier Payment Page
 * PRD-060 Phase 2: Payment with invoice allocation
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Wallet, Loader2, Plus, Trash2, Info } from 'lucide-react';
import { ScanAndFillButton } from '@/components/accounting/ScanAndFillButton';
import { fuzzyMatchSupplier } from '@/modules/accounting/utils/fuzzyMatch';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

interface Supplier { id: number; name: string }
interface OutstandingInvoice {
  id: string;
  invoiceNumber: string;
  totalAmount: number;
  balance: number;
}

import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface Allocation { key: string; invoiceId: string; amount: number }

export default function NewSupplierPaymentPage() {
  const router = useRouter();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [invoices, setInvoices] = useState<OutstandingInvoice[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [scanBanner, setScanBanner] = useState<string | null>(null);

  const [form, setForm] = useState({
    supplierId: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'eft',
    reference: '',
    description: '',
  });

  const [allocations, setAllocations] = useState<Allocation[]>([
    { key: crypto.randomUUID(), invoiceId: '', amount: 0 },
  ]);

  useEffect(() => {
    apiFetch('/api/accounting/suppliers-list').then(r => r.json()).then(res => {
      const data = res.data || res;
      setSuppliers(Array.isArray(data) ? data : data.suppliers || []);
    });
  }, []);

  // Load outstanding invoices for selected supplier
  useEffect(() => {
    if (!form.supplierId) { setInvoices([]); return; }
    apiFetch(`/api/accounting/supplier-invoices?supplier_id=${form.supplierId}&status=approved`)
      .then(r => r.json())
      .then(res => {
        const payload = res.data || res;
        const all = payload.invoices || [];
        setInvoices(all.filter((inv: OutstandingInvoice) => inv.balance > 0));
      });
  }, [form.supplierId]);

  const addAllocation = () => {
    setAllocations(prev => [...prev, { key: crypto.randomUUID(), invoiceId: '', amount: 0 }]);
  };

  const updateAllocation = (key: string, field: keyof Allocation, value: string | number) => {
    setAllocations(prev => prev.map(a => a.key === key ? { ...a, [field]: value } : a));
  };

  const removeAllocation = (key: string) => {
    if (allocations.length <= 1) return;
    setAllocations(prev => prev.filter(a => a.key !== key));
  };

  const totalAmount = allocations.reduce((sum, a) => sum + (a.amount || 0), 0);

  function handleExtracted(data: ExtractedDocument) {
    if (data.date) setForm(f => ({ ...f, paymentDate: data.date! }));
    if (data.referenceNumber) setForm(f => ({ ...f, reference: data.referenceNumber! }));

    if (data.vendorName && suppliers.length > 0) {
      const match = fuzzyMatchSupplier(data.vendorName, suppliers.map(s => ({ id: String(s.id), name: s.name })));
      if (match) setForm(f => ({ ...f, supplierId: String(match.id) }));
    }

    // Auto-allocate if we have a total and matching invoice
    if (data.totalAmount && invoices.length > 0) {
      const exactMatch = invoices.find(inv => Math.abs(inv.balance - data.totalAmount!) < 0.02);
      if (exactMatch) {
        setAllocations([{ key: crypto.randomUUID(), invoiceId: exactMatch.id, amount: data.totalAmount }]);
      }
    }

    setScanBanner(`Auto-filled from document (${Math.round(data.confidence * 100)}% confidence). Review all fields.`);
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/supplier-payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          supplierId: Number(form.supplierId),
          paymentDate: form.paymentDate,
          totalAmount,
          paymentMethod: form.paymentMethod,
          reference: form.reference || undefined,
          description: form.description || undefined,
          allocations: allocations
            .filter(a => a.invoiceId && a.amount > 0)
            .map(a => ({ invoiceId: a.invoiceId, amount: a.amount })),
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error?.message || 'Failed to create payment');
      }

      const json = await res.json();
      const payment = json.data || json;
      router.push(`/accounting/supplier-payments/${payment.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create payment');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/supplier-payments" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-teal-600 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Payments
          </Link>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Wallet className="h-6 w-6 text-teal-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Supplier Payment</h1>
            </div>
            <ScanAndFillButton onExtracted={handleExtracted} label="Scan Document" />
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6 max-w-4xl">
          {scanBanner && (
            <div className="p-3 bg-teal-500/10 rounded-lg text-teal-400 text-sm flex items-center gap-2">
              <Info className="h-4 w-4 flex-shrink-0" />{scanBanner}
              <button type="button" onClick={() => setScanBanner(null)} className="ml-auto text-teal-500 hover:text-teal-300 text-xs">Dismiss</button>
            </div>
          )}
          {error && (
            <div className="p-3 bg-red-500/10 rounded-lg text-red-400 text-sm">{error}</div>
          )}

          {/* Payment Details */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <h3 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Payment Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Supplier *</label>
                <select required value={form.supplierId}
                  onChange={e => setForm(f => ({ ...f, supplierId: e.target.value }))}
                  className="ff-select w-full">
                  <option value="">Select supplier...</option>
                  {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Date *</label>
                <input type="date" required value={form.paymentDate}
                  onChange={e => setForm(f => ({ ...f, paymentDate: e.target.value }))}
                  className="ff-input w-full" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Method</label>
                <select value={form.paymentMethod}
                  onChange={e => setForm(f => ({ ...f, paymentMethod: e.target.value }))}
                  className="ff-select w-full">
                  <option value="eft">EFT</option>
                  <option value="cheque">Cheque</option>
                  <option value="cash">Cash</option>
                  <option value="card">Card</option>
                </select>
              </div>
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Reference</label>
                <input type="text" value={form.reference}
                  onChange={e => setForm(f => ({ ...f, reference: e.target.value }))}
                  className="ff-input w-full" placeholder="Bank reference" />
              </div>
            </div>
          </div>

          {/* Allocations */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">Invoice Allocations</h3>
              <button type="button" onClick={addAllocation}
                className="inline-flex items-center gap-1 text-sm text-teal-600 hover:text-teal-700 font-medium">
                <Plus className="h-4 w-4" /> Add Allocation
              </button>
            </div>

            {invoices.length === 0 && form.supplierId && (
              <p className="text-sm text-[var(--ff-text-tertiary)] mb-4">No outstanding invoices for this supplier</p>
            )}

            <div className="space-y-3">
              {allocations.map((alloc, idx) => {
                const selectedInvoice = invoices.find(i => i.id === alloc.invoiceId);
                return (
                  <div key={alloc.key} className="grid grid-cols-12 gap-2 items-end">
                    <div className="col-span-6">
                      {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Invoice</label>}
                      <select value={alloc.invoiceId}
                        onChange={e => updateAllocation(alloc.key, 'invoiceId', e.target.value)}
                        className="ff-select w-full text-sm">
                        <option value="">Select invoice...</option>
                        {invoices.map(inv => (
                          <option key={inv.id} value={inv.id}>
                            {inv.invoiceNumber} — Balance: {formatCurrency(inv.balance)}
                          </option>
                        ))}
                      </select>
                    </div>
                    <div className="col-span-2">
                      {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Balance</label>}
                      <div className="ff-input w-full text-sm text-right bg-[var(--ff-bg-tertiary)] font-mono">
                        {selectedInvoice ? formatCurrency(selectedInvoice.balance) : '-'}
                      </div>
                    </div>
                    <div className="col-span-3">
                      {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Pay Amount</label>}
                      <input type="number" step="0.01" min="0"
                        max={selectedInvoice?.balance || undefined}
                        value={alloc.amount || ''}
                        onChange={e => updateAllocation(alloc.key, 'amount', Number(e.target.value))}
                        className="ff-input w-full text-sm text-right" />
                    </div>
                    <div className="col-span-1 flex justify-center">
                      {allocations.length > 1 && (
                        <button type="button" onClick={() => removeAllocation(alloc.key)}
                          className="p-1 text-red-400 hover:text-red-300">
                          <Trash2 className="h-4 w-4" />
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>

            <div className="mt-4 pt-4 border-t border-[var(--ff-border-light)] flex justify-end">
              <div className="text-right">
                <p className="text-sm text-[var(--ff-text-secondary)]">Total Payment</p>
                <p className="text-2xl font-bold font-mono text-teal-500">{formatCurrency(totalAmount)}</p>
              </div>
            </div>
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/supplier-payments"
              className="px-4 py-2 border border-[var(--ff-border-medium)] rounded-lg text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm font-medium">
              Cancel
            </Link>
            <button type="submit" disabled={isSubmitting || totalAmount <= 0}
              className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Payment
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Create Customer Payment Page
 * PRD-060 Phase 3: Payment with invoice allocation
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Wallet, Loader2, Plus, Trash2, Info } from 'lucide-react';
import { ScanAndFillButton } from '@/components/accounting/ScanAndFillButton';
import { fuzzyMatchClient } from '@/modules/accounting/utils/fuzzyMatch';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

interface Client { id: string; company_name: string }
interface OutstandingInvoice {
  id: string;
  invoice_number: string;
  total_amount: number;
  amount_paid: number;
}

import { formatCurrency } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface Allocation { key: string; invoiceId: string; amount: number }

export default function NewCustomerPaymentPage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [invoices, setInvoices] = useState<OutstandingInvoice[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [scanBanner, setScanBanner] = useState<string | null>(null);

  const [form, setForm] = useState({
    clientId: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'eft',
    bankReference: '',
    description: '',
  });

  const [allocations, setAllocations] = useState<Allocation[]>([
    { key: crypto.randomUUID(), invoiceId: '', amount: 0 },
  ]);

  useEffect(() => {
    apiFetch('/api/accounting/customers').then(r => r.json()).then(res => {
      const data = res.data || res;
      setClients(Array.isArray(data) ? data : data.clients || []);
    });
  }, []);

  // Load outstanding invoices when client changes
  useEffect(() => {
    if (!form.clientId) { setInvoices([]); return; }
    apiFetch(`/api/customer-invoices?client_id=${form.clientId}&status=approved&status=sent&status=partially_paid&status=overdue`)
      .then(r => r.json())
      .then(res => {
        const data = res.data || res;
        const list = Array.isArray(data) ? data : data.invoices || [];
        setInvoices(list.filter((inv: OutstandingInvoice) =>
          Number(inv.total_amount) - Number(inv.amount_paid) > 0.01
        ));
      });
  }, [form.clientId]);

  const totalAllocated = allocations.reduce((s, a) => s + (a.amount || 0), 0);

  const addAllocation = () => {
    setAllocations(prev => [...prev, { key: crypto.randomUUID(), invoiceId: '', amount: 0 }]);
  };

  const removeAllocation = (key: string) => {
    setAllocations(prev => prev.filter(a => a.key !== key));
  };

  const updateAllocation = (key: string, field: 'invoiceId' | 'amount', value: string | number) => {
    setAllocations(prev => prev.map(a => a.key === key ? { ...a, [field]: value } : a));
  };

  function handleExtracted(data: ExtractedDocument) {
    if (data.date) setForm(f => ({ ...f, paymentDate: data.date! }));
    if (data.referenceNumber) setForm(f => ({ ...f, bankReference: data.referenceNumber! }));

    if (data.customerName && clients.length > 0) {
      const match = fuzzyMatchClient(data.customerName, clients);
      if (match) setForm(f => ({ ...f, clientId: String(match.id) }));
    }

    if (data.totalAmount && invoices.length > 0) {
      const exactMatch = invoices.find(inv =>
        Math.abs((Number(inv.total_amount) - Number(inv.amount_paid)) - data.totalAmount!) < 0.02
      );
      if (exactMatch) {
        setAllocations([{ key: crypto.randomUUID(), invoiceId: exactMatch.id, amount: data.totalAmount }]);
      }
    }

    setScanBanner(`Auto-filled from document (${Math.round(data.confidence * 100)}% confidence). Review all fields.`);
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const res = await apiFetch('/api/accounting/customer-payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          clientId: form.clientId,
          paymentDate: form.paymentDate,
          totalAmount: totalAllocated,
          paymentMethod: form.paymentMethod,
          bankReference: form.bankReference || undefined,
          description: form.description || undefined,
          allocations: allocations
            .filter(a => a.invoiceId && a.amount > 0)
            .map(a => ({ invoiceId: a.invoiceId, amount: a.amount })),
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Failed to create payment');
      router.push('/accounting/customer-payments');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create payment');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting/customer-payments" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Payments
            </Link>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-teal-500/10">
                  <Wallet className="h-6 w-6 text-teal-500" />
                </div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Record Customer Payment</h1>
              </div>
              <ScanAndFillButton onExtracted={handleExtracted} label="Scan Document" />
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-4xl space-y-6">
          {scanBanner && (
            <div className="p-3 bg-teal-500/10 rounded-lg text-teal-400 text-sm flex items-center gap-2">
              <Info className="h-4 w-4 flex-shrink-0" />{scanBanner}
              <button type="button" onClick={() => setScanBanner(null)} className="ml-auto text-teal-500 hover:text-teal-300 text-xs">Dismiss</button>
            </div>
          )}
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          {/* Payment Details */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Payment Details</h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Client *</label>
                <select
                  value={form.clientId}
                  onChange={e => setForm(f => ({ ...f, clientId: e.target.value }))}
                  className="ff-select w-full"
                  required
                >
                  <option value="">Select client...</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.company_name}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Date *</label>
                <input
                  type="date"
                  value={form.paymentDate}
                  onChange={e => setForm(f => ({ ...f, paymentDate: e.target.value }))}
                  className="ff-input w-full"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Method</label>
                <select
                  value={form.paymentMethod}
                  onChange={e => setForm(f => ({ ...f, paymentMethod: e.target.value }))}
                  className="ff-select w-full"
                >
                  <option value="eft">EFT</option>
                  <option value="cheque">Cheque</option>
                  <option value="cash">Cash</option>
                  <option value="card">Card</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Bank Reference</label>
                <input
                  type="text"
                  value={form.bankReference}
                  onChange={e => setForm(f => ({ ...f, bankReference: e.target.value }))}
                  className="ff-input w-full"
                  placeholder="e.g. REF123456"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Description</label>
              <input
                type="text"
                value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                className="ff-input w-full"
                placeholder="Optional payment description"
              />
            </div>
          </div>

          {/* Invoice Allocations */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Invoice Allocations</h2>
              <button
                type="button"
                onClick={addAllocation}
                className="inline-flex items-center gap-1 text-sm text-teal-500 hover:text-teal-400"
              >
                <Plus className="h-4 w-4" /> Add Line
              </button>
            </div>

            {invoices.length === 0 && form.clientId && (
              <p className="text-sm text-[var(--ff-text-tertiary)]">No outstanding invoices for this client</p>
            )}

            <div className="space-y-3">
              {allocations.map(alloc => {
                const inv = invoices.find(i => i.id === alloc.invoiceId);
                const balance = inv ? Number(inv.total_amount) - Number(inv.amount_paid) : 0;
                return (
                  <div key={alloc.key} className="flex items-center gap-3">
                    <select
                      value={alloc.invoiceId}
                      onChange={e => updateAllocation(alloc.key, 'invoiceId', e.target.value)}
                      className="ff-select flex-1"
                    >
                      <option value="">Select invoice...</option>
                      {invoices.map(inv => (
                        <option key={inv.id} value={inv.id}>
                          {inv.invoice_number} — Balance: {formatCurrency(Number(inv.total_amount) - Number(inv.amount_paid))}
                        </option>
                      ))}
                    </select>
                    <input
                      type="number"
                      step="0.01"
                      min="0"
                      max={balance || undefined}
                      value={alloc.amount || ''}
                      onChange={e => updateAllocation(alloc.key, 'amount', Number(e.target.value))}
                      className="ff-input w-40"
                      placeholder="Amount"
                    />
                    {allocations.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeAllocation(alloc.key)}
                        className="p-2 text-red-400 hover:text-red-300"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                );
              })}
            </div>

            <div className="pt-3 border-t border-[var(--ff-border-light)] flex justify-between">
              <span className="text-sm font-medium text-[var(--ff-text-secondary)]">Total Allocated</span>
              <span className="text-lg font-bold text-[var(--ff-text-primary)]">{formatCurrency(totalAllocated)}</span>
            </div>
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/customer-payments" className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
              Cancel
            </Link>
            <button
              type="submit"
              disabled={isSubmitting || totalAllocated <= 0}
              className="inline-flex items-center gap-2 px-6 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 transition-colors text-sm font-medium"
            >
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Payment
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

