    e.preventDefault();
    setError(''); setBusy(true);

    // Group by supplier
    const grouped: Record<string, { invoiceId: string; amount: number }[]> = {};
    for (const l of lines) {
      if (!l.supplierId || !l.invoiceId || l.amount <= 0) continue;
      if (!grouped[l.supplierId]) grouped[l.supplierId] = [];
      grouped[l.supplierId]!.push({ invoiceId: l.invoiceId, amount: l.amount });
    }

    const payments = Object.entries(grouped).map(([supplierId, allocs]) => ({
      supplierId,
      invoiceAllocations: allocs,
    }));

    if (payments.length === 0) { setError('Add at least one payment'); setBusy(false); return; }

    try {
      const res = await apiFetch('/api/accounting/batch-payments', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ paymentMethod: method, notes: notes || undefined, payments }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      router.push('/accounting/batch-payments');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setBusy(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/batch-payments" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
            <ArrowLeft className="h-4 w-4" /> Back to Batches
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-indigo-500/10"><Layers className="h-6 w-6 text-indigo-500" /></div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Batch Payment</h1>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-5xl space-y-6">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Payment Settings</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Method</label>
                <select value={method} onChange={e => setMethod(e.target.value)} className="ff-select w-full">
                  <option value="eft">EFT</option><option value="cheque">Cheque</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
                <input value={notes} onChange={e => setNotes(e.target.value)} className="ff-input w-full" placeholder="Optional batch notes" />
              </div>
            </div>
          </div>

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Invoices to Pay</h2>
              <button type="button" onClick={addLine} className="inline-flex items-center gap-1 text-sm text-indigo-500 hover:text-indigo-400">
                <Plus className="h-4 w-4" /> Add Line
              </button>
            </div>

            <div className="space-y-3">
              {lines.map(line => {
                const supplierInvoices = invoices.filter(i => !line.supplierId || String(i.supplier_id) === line.supplierId);
                const inv = invoices.find(i => i.id === line.invoiceId);
                const balance = inv ? Number(inv.total_amount) - Number(inv.amount_paid) : 0;
                return (
                  <div key={line.key} className="flex items-center gap-3">
                    <select value={line.supplierId} onChange={e => setLines(p => p.map(l => l.key === line.key ? { ...l, supplierId: e.target.value, invoiceId: '' } : l))} className="ff-select flex-1">
                      <option value="">Select Supplier</option>
                      {suppliers.map(s => <option key={s.id} value={s.id}>{s.company_name}</option>)}
                    </select>
                    <select value={line.invoiceId} onChange={e => { const i = invoices.find(x => x.id === e.target.value); setLines(p => p.map(l => l.key === line.key ? { ...l, invoiceId: e.target.value, amount: i ? Number(i.total_amount) - Number(i.amount_paid) : 0 } : l)); }} className="ff-select flex-1">
                      <option value="">Select Invoice</option>
                      {supplierInvoices.map(i => <option key={i.id} value={i.id}>{i.invoice_number} — {fmt(Number(i.total_amount) - Number(i.amount_paid))}</option>)}
                    </select>
                    <input type="number" step="0.01" min="0" max={balance || undefined} value={line.amount || ''} onChange={e => setLines(p => p.map(l => l.key === line.key ? { ...l, amount: Number(e.target.value) } : l))} className="ff-input w-36" placeholder="Amount" />
                    {lines.length > 1 && <button type="button" onClick={() => removeLine(line.key)} className="p-2 text-red-400 hover:text-red-300"><Trash2 className="h-4 w-4" /></button>}
                  </div>
                );
              })}
            </div>

            <div className="pt-3 border-t border-[var(--ff-border-light)] flex justify-between">
              <span className="text-sm font-medium text-[var(--ff-text-secondary)]">Batch Total</span>
              <span className="text-lg font-bold text-[var(--ff-text-primary)]">{fmt(total)}</span>
            </div>
          </div>

          <div className="flex justify-end gap-3">
            <Link href="/accounting/batch-payments" className="px-4 py-2 text-sm text-[var(--ff-text-secondary)]">Cancel</Link>
            <button type="submit" disabled={busy || total <= 0} className="inline-flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 text-sm font-medium">
              {busy && <Loader2 className="h-4 w-4 animate-spin" />} Create Batch
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Batch Payment Detail Page
 * View batch summary, constituent payments, approve/process/cancel
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Layers, Loader2, AlertCircle, Check, Zap, XCircle } from 'lucide-react';
import { formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const STATUS_BADGE: Record<string, string> = {
  draft: 'bg-gray-500/20 text-gray-400',
  approved: 'bg-blue-500/20 text-blue-400',
  processed: 'bg-teal-500/20 text-teal-400',
  cancelled: 'bg-red-500/20 text-red-400',
};

interface BatchPayment {
  id: string;
  paymentNumber: string;
  supplierName: string;
  amount: number;
  status: string;
}

interface BatchDetail {
  id: string;
  batchNumber: string;
  batchDate: string;
  totalAmount: number;
  paymentCount: number;
  paymentMethod: string;
  bankAccountId?: string;
  status: string;
  payments: BatchPayment[];
}

export default function BatchPaymentDetailPage() {
  const router = useRouter();
  const batchId = router.query.batchId as string;

  const [batch, setBatch] = useState<BatchDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [actionBusy, setActionBusy] = useState('');

  const load = useCallback(async () => {
    if (!batchId) return;
    setIsLoading(true);
    setError('');
    try {
      const res = await apiFetch(`/api/accounting/batch-payments?id=${batchId}`);
      const json = await res.json();
      setBatch(json.data || null);
    } catch {
      setError('Failed to load batch');
    } finally {
      setIsLoading(false);
    }
  }, [batchId]);

  useEffect(() => { load(); }, [load]);

  async function doAction(action: string) {
    if (!batch) return;
    setActionBusy(action);
    try {
      const res = await apiFetch('/api/accounting/batch-payments-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, id: batch.id }),
      });
      if (!res.ok) {
        const json = await res.json();
        setError(json.error || `Failed to ${action}`);
      } else {
        load();
      }
    } catch {
      setError(`Failed to ${action} batch`);
    } finally {
      setActionBusy('');
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link href="/accounting/batch-payments" className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)]">
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div className="p-2 rounded-lg bg-indigo-500/10">
                <Layers className="h-6 w-6 text-indigo-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  {batch?.batchNumber || 'Batch Detail'}
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {batch ? `${batch.paymentCount} payments • ${batch.paymentMethod?.toUpperCase()}` : 'Loading...'}
                </p>
              </div>
              {batch && (
                <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${STATUS_BADGE[batch.status] || ''}`}>
                  {batch.status}
                </span>
              )}
            </div>
            {batch && (
              <div className="flex items-center gap-2">
                {batch.status === 'draft' && (
                  <>
                    <button onClick={() => doAction('approve')} disabled={!!actionBusy}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm font-medium disabled:opacity-50">
                      {actionBusy === 'approve' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />} Approve
                    </button>
                    <button onClick={() => doAction('cancel')} disabled={!!actionBusy}
                      className="inline-flex items-center gap-2 px-4 py-2 bg-red-600/10 text-red-400 rounded-lg hover:bg-red-600/20 text-sm font-medium disabled:opacity-50">
                      <XCircle className="h-4 w-4" /> Cancel
                    </button>
                  </>
                )}
                {batch.status === 'approved' && (
                  <button onClick={() => doAction('process')} disabled={!!actionBusy}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50">
                    {actionBusy === 'process' ? <Loader2 className="h-4 w-4 animate-spin" /> : <Zap className="h-4 w-4" />} Process
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 space-y-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-indigo-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : batch ? (
            <>
              {/* Summary Cards */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <p className="text-xs text-[var(--ff-text-tertiary)]">Batch Total</p>
                  <p className="text-xl font-bold text-indigo-400">{fmt(batch.totalAmount)}</p>
                </div>
                <div className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <p className="text-xs text-[var(--ff-text-tertiary)]">Batch Date</p>
                  <p className="text-lg font-medium text-[var(--ff-text-primary)]">{formatDate(batch.batchDate)}</p>
                </div>
                <div className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <p className="text-xs text-[var(--ff-text-tertiary)]">Payment Count</p>
                  <p className="text-lg font-medium text-[var(--ff-text-primary)]">{batch.paymentCount}</p>
                </div>
                <div className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <p className="text-xs text-[var(--ff-text-tertiary)]">Method</p>
                  <p className="text-lg font-medium text-[var(--ff-text-primary)] uppercase">{batch.paymentMethod}</p>
                </div>
              </div>

              {/* Constituent Payments */}
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                <div className="px-4 py-3 border-b border-[var(--ff-border-light)]">
                  <h3 className="text-sm font-medium text-[var(--ff-text-primary)]">Payments in this Batch</h3>
                </div>
                {batch.payments && batch.payments.length > 0 ? (
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)]">
                        <th className="px-4 py-3 text-left text-[var(--ff-text-secondary)] font-medium">Payment #</th>
                        <th className="px-4 py-3 text-left text-[var(--ff-text-secondary)] font-medium">Supplier</th>
                        <th className="px-4 py-3 text-right text-[var(--ff-text-secondary)] font-medium">Amount</th>
                        <th className="px-4 py-3 text-left text-[var(--ff-text-secondary)] font-medium">Status</th>
                      </tr>
                    </thead>
                    <tbody>
                      {batch.payments.map((p) => (
                        <tr key={p.id} className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-tertiary)]">
                          <td className="px-4 py-3 text-[var(--ff-text-primary)] font-mono">
                            <Link href={`/accounting/supplier-payments/${p.id}`} className="hover:text-indigo-400">
                              {p.paymentNumber}
                            </Link>
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)]">{p.supplierName}</td>
                          <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">{fmt(Number(p.amount))}</td>
                          <td className="px-4 py-3">
                            <span className={`px-2 py-0.5 rounded text-xs font-medium ${STATUS_BADGE[p.status] || ''}`}>{p.status}</span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (
                  <div className="p-8 text-center text-[var(--ff-text-tertiary)]">No individual payments in this batch</div>
                )}
              </div>
            </>
          ) : null}
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Customer Payment Detail Page
 * View payment details, allocations, and perform actions (confirm/cancel)
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Wallet, Loader2, AlertCircle, Check, X } from 'lucide-react';
import { AccountingDocumentPanel } from '@/modules/accounting/documents';
import { notify } from '@/utils/toast';
import { formatCurrency, formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-gray-500/20 text-gray-400',
    confirmed: 'bg-teal-500/20 text-teal-400',
    reconciled: 'bg-blue-500/20 text-blue-400',
    cancelled: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

interface Allocation {
  id: string;
  invoiceId: string;
  amountAllocated: number;
  invoiceNumber?: string;
}

interface Payment {
  id: string;
  paymentNumber: string;
  clientId: string;
  clientName?: string;
  paymentDate: string;
  totalAmount: number;
  paymentMethod: string;
  bankReference?: string;
  description?: string;
  status: string;
  glJournalEntryId?: string;
  allocations: Allocation[];
}

export default function CustomerPaymentDetailPage() {
  const router = useRouter();
  const paymentId = router.query.paymentId as string;

  const [payment, setPayment] = useState<Payment | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [acting, setActing] = useState(false);

  const loadPayment = useCallback(async () => {
    if (!paymentId) return;
    setIsLoading(true);
    setError('');
    try {
      const res = await apiFetch(`/api/accounting/customer-payments?id=${paymentId}`);
      const json = await res.json();
      const data = json.data || json;
      setPayment(data);
    } catch {
      setError('Failed to load payment');
    } finally {
      setIsLoading(false);
    }
  }, [paymentId]);

  useEffect(() => { loadPayment(); }, [loadPayment]);

  async function handleAction(action: 'confirm' | 'cancel') {
    if (!payment) return;

    if (action === 'cancel') {
      const reason = prompt('Reason for cancellation:');
      if (reason === null) return;
      setActing(true);
      try {
        const res = await apiFetch('/api/accounting/customer-payments-action', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ action: 'cancel', paymentId: payment.id, reason }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || 'Cancel failed');
        notify.success('Payment cancelled');
        loadPayment();
      } catch (err) {
        notify.error(err instanceof Error ? err.message : 'Failed to cancel');
      } finally {
        setActing(false);
      }
    } else {
      setActing(true);
      try {
        const res = await apiFetch('/api/accounting/customer-payments-action', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ action: 'confirm', paymentId: payment.id }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.error || 'Confirm failed');
        notify.success('Payment confirmed and GL posted');
        loadPayment();
      } catch (err) {
        notify.error(err instanceof Error ? err.message : 'Failed to confirm');
      } finally {
        setActing(false);
      }
    }
  }

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link href="/accounting/customer-payments" className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)]">
                <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Wallet className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <div className="flex items-center gap-3">
                  <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                    {payment?.paymentNumber || 'Payment'}
                  </h1>
                  {payment && <StatusBadge status={payment.status} />}
                </div>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {payment?.clientName || 'Loading...'}
                </p>
              </div>
            </div>
            {payment && (
              <div className="flex gap-2">
                {payment.status === 'draft' && (
                  <button onClick={() => handleAction('confirm')} disabled={acting}
                    className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-500 text-white rounded-lg text-sm disabled:opacity-50">
                    <Check className="h-4 w-4" /> Confirm & Post GL
                  </button>
                )}
                {payment.status === 'confirmed' && (
                  <button onClick={() => handleAction('cancel')} disabled={acting}
                    className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-500 text-white rounded-lg text-sm disabled:opacity-50">
                    <X className="h-4 w-4" /> Cancel Payment
                  </button>
                )}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 space-y-6">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : payment ? (
            <>
              {/* Payment Info */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label: 'Amount', value: formatCurrency(payment.totalAmount) },
                  { label: 'Date', value: formatDate(payment.paymentDate) },
                  { label: 'Method', value: payment.paymentMethod.toUpperCase() },
                  { label: 'Bank Reference', value: payment.bankReference || '-' },
                ].map(item => (
                  <div key={item.label} className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                    <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">{item.label}</p>
                    <p className="text-sm font-medium text-[var(--ff-text-primary)]">{item.value}</p>
                  </div>
                ))}
              </div>

              {payment.description && (
                <div className="p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
                  <p className="text-xs text-[var(--ff-text-tertiary)] mb-1">Description</p>
                  <p className="text-sm text-[var(--ff-text-primary)]">{payment.description}</p>
                </div>
              )}

              {payment.glJournalEntryId && (
                <div className="p-3 rounded-lg bg-blue-500/10 border border-blue-500/20">
                  <Link href={`/accounting/journal-entries/${payment.glJournalEntryId}`}
                    className="text-sm text-blue-400 hover:text-blue-300">
                    View GL Journal Entry
                  </Link>
                </div>
              )}

              {/* Allocations */}
              <div>
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-3">Invoice Allocations</h2>
                <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border-light)]">
                        <th className="text-left px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Invoice #</th>
                        <th className="text-right px-4 py-3 text-[var(--ff-text-secondary)] font-medium">Amount Allocated</th>
                      </tr>
                    </thead>
                    <tbody>
                      {payment.allocations.map(alloc => (
                        <tr key={alloc.id} className="border-b border-[var(--ff-border-light)]">
                          <td className="px-4 py-3">
                            <Link href={`/accounting/customer-invoices/${alloc.invoiceId}`}
                              className="text-blue-400 hover:text-blue-300 font-mono">
                              {alloc.invoiceNumber || alloc.invoiceId}
                            </Link>
                          </td>
                          <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                            {formatCurrency(alloc.amountAllocated)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
