  vendorVatNumber: null,
  vendorAddress: null,
  vendorBankDetails: null,
  customerName: null,
  customerVatNumber: null,
  date: '2026-03-20',
  dueDate: null,
  paymentTerms: null,
  referenceNumber: 'REC-456',
