  it('flags future date as error', () => {
    const r = validateReceiptExtraction(makeReceipt({ date: '2030-01-01' }));
    expect(r.valid).toBe(false);
  });
});

describe('Merchant to Account Mapping', () => {
  it('maps Woolworths to Materials & Supplies', () => {
