    dateFrom?: string;
    dateTo?: string;
    limit?: number;
    offset?: number;
  },
): Promise<{ entries: TimeEntry[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;

  const conditions: string[] = ['te.company_id = $1::UUID'];
  const params: unknown[] = [companyId];
