/**
 * COMPREHENSIVE WORKFLOW AUDIT
 * Tests the full accounting lifecycle end-to-end:
 * - Bank transactions → categorization → reconciliation
 * - Supplier invoices → approval → payment → allocation
 * - Customer invoices → send → payment → allocation
 * - Credit notes → application
 * - Journal entries → posting
 * - Reports → data integrity
 * - VLM document pipeline
 * - SARS compliance
 * - Asset management
 * - Inventory management
 */
import { test, expect } from '@playwright/test';

const CID = '00000000-0000-0000-0000-000000000001';

// Helper to make authenticated API calls
async function api(request: any, method: string, path: string, body?: any) {
  const opts: any = { headers: { 'X-Company-Id': CID } };
  if (body) opts.data = body;
  return method === 'GET' ? request.get(path, opts) : request.post(path, opts);
}

// ═══════════════════════════════════════════════════════════════════════════
// 1. SUPPLIER INVOICE LIFECYCLE
// ═══════════════════════════════════════════════════════════════════════════
test.describe('Supplier Invoice Lifecycle', () => {
  test('list supplier invoices with data', async ({ request }) => {
    const res = await api(request, 'GET', '/api/accounting/supplier-invoices');
    expect(res.status()).toBe(200);
    const json = await res.json();
    expect(json.data.length).toBeGreaterThan(0);
  });

  test('view supplier invoice detail', async ({ request }) => {
    const res = await api(request, 'GET', '/api/accounting/supplier-invoices-detail?id=e1000000-0000-0000-0000-000000000003');
    expect(res.status()).toBe(200);
    const json = await res.json();
    expect(json.data.invoice_number).toBe('TLK-2026-1234');
    expect(json.data.status).toBe('approved');
  });

  test('supplier invoice has correct VAT calculation', async ({ request }) => {
    const res = await api(request, 'GET', '/api/accounting/supplier-invoices-detail?id=e1000000-0000-0000-0000-000000000003');
    const inv = (await res.json()).data;
    const subtotal = parseFloat(inv.subtotal);
    const tax = parseFloat(inv.tax_amount);
    const total = parseFloat(inv.total_amount);
    expect(Math.abs(subtotal + tax - total)).toBeLessThan(0.02);
  });

  test('draft invoices can be listed', async ({ request }) => {
    const res = await api(request, 'GET', '/api/accounting/supplier-invoices?status=draft');
    expect(res.status()).toBe(200);
  });

  test('paid invoices have zero balance', async ({ request }) => {
    const res = await api(request, 'GET', '/api/accounting/supplier-invoices-detail?id=e1000000-0000-0000-0000-000000000010');
    const inv = (await res.json()).data;
    if (inv?.status === 'paid') {
      const balance = parseFloat(inv.total_amount) - parseFloat(inv.amount_paid);
      expect(balance).toBeCloseTo(0, 1);
    }
  });
});

// ═══════════════════════════════════════════════════════════════════════════
// 2. CUSTOMER INVOICE LIFECYCLE
// ═══════════════════════════════════════════════════════════════════════════
test.describe('Customer Invoice Lifecycle', () => {
  test('list customer invoices with data', async ({ request }) => {
