/**
 * Enhanced Reporting Engine — ratios, comparatives, management packs, formatting
 * Pure business logic — no database dependencies.
 */

export interface FinancialData {
  revenue: number;
  costOfSales: number;
  operatingExpenses: number;
  netProfit: number;
  totalAssets: number;
  totalLiabilities: number;
  totalEquity: number;
  currentAssets: number;
  currentLiabilities: number;
  inventory: number;
  accountsReceivable: number;
  accountsPayable: number;
  cash: number;
  // Extended (optional for backward compat)
  depreciation?: number;
  amortization?: number;
  interestExpense?: number;
  operatingCashFlow?: number;
  capitalExpenditure?: number;
  employeeCount?: number;
}

export interface RatioResult {
  grossProfitMargin: number;
  netProfitMargin: number;
  operatingProfitMargin: number;
  currentRatio: number;
  quickRatio: number;
  debtToEquity: number;
  returnOnAssets: number;
  returnOnEquity: number;
  debtorDays: number;
  creditorDays: number;
  inventoryTurnover: number;
}

export interface ExtendedRatioResult extends RatioResult {
  // Profitability
  ebitda: number;
  ebitdaMargin: number;
  roce: number; // Return on Capital Employed
  // Leverage
  interestCoverage: number;
  debtRatio: number;
  equityMultiplier: number;
  // Liquidity
  cashRatio: number;
  workingCapital: number;
  operatingCashFlowRatio: number;
  // Efficiency
  assetTurnover: number;
  receivablesTurnover: number;
  payablesTurnover: number;
  inventoryDays: number;
  cashConversionCycle: number;
  // Cash Flow
  freeCashFlow: number;
  // Per-Unit
  revenuePerEmployee: number;
  // DuPont Decomposition
  dupontMargin: number;
  dupontTurnover: number;
  dupontLeverage: number;
}

export interface VarianceResult {
  amount: number;
  percentage: number;
  direction: 'favorable' | 'unfavorable' | 'on_budget';
}

export interface ComparativeRow {
  account: string;
  currentAmount: number;
  priorAmount: number;
  changeAmount: number;
  changePercent: number;
}

export interface ManagementPackSection {
  title: string;
  items: Array<{ label: string; value: string | number }>;
}

export interface ManagementPack {
  companyName: string;
  period: string;
  generatedAt: string;
  profitMargin: number;
  sections: ManagementPackSection[];
}

// ═══════════════════════════════════════════════════════════════════════════
// FINANCIAL RATIOS
// ═══════════════════════════════════════════════════════════════════════════

function safeDiv(numerator: number, denominator: number): number {
  return denominator === 0 ? 0 : Math.round((numerator / denominator) * 10000) / 10000;
}

function pct(numerator: number, denominator: number): number {
  return Math.round(safeDiv(numerator, denominator) * 10000) / 100;
}

export function calculateFinancialRatios(data: FinancialData): RatioResult {
  const grossProfit = data.revenue - data.costOfSales;
  const operatingProfit = grossProfit - data.operatingExpenses;

  return {
    grossProfitMargin: pct(grossProfit, data.revenue),
    netProfitMargin: pct(data.netProfit, data.revenue),
    operatingProfitMargin: pct(operatingProfit, data.revenue),
    currentRatio: Math.round(safeDiv(data.currentAssets, data.currentLiabilities) * 100) / 100,
    quickRatio: Math.round(safeDiv(data.currentAssets - data.inventory, data.currentLiabilities) * 100) / 100,
    debtToEquity: Math.round(safeDiv(data.totalLiabilities, data.totalEquity) * 100) / 100,
    returnOnAssets: pct(data.netProfit, data.totalAssets),
    returnOnEquity: pct(data.netProfit, data.totalEquity),
    debtorDays: Math.round(safeDiv(data.accountsReceivable, data.revenue) * 365 * 100) / 100,
    creditorDays: Math.round(safeDiv(data.accountsPayable, data.costOfSales) * 365 * 100) / 100,
    inventoryTurnover: Math.round(safeDiv(data.costOfSales, data.inventory) * 100) / 100,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// EXTENDED FINANCIAL RATIOS (30+)
// ═══════════════════════════════════════════════════════════════════════════

export function calculateExtendedRatios(data: FinancialData): ExtendedRatioResult {
  const base = calculateFinancialRatios(data);
  const grossProfit = data.revenue - data.costOfSales;
  const ebit = grossProfit - data.operatingExpenses;
  const dep = data.depreciation ?? 0;
  const amort = data.amortization ?? 0;
  const interest = data.interestExpense ?? 0;
  const opCF = data.operatingCashFlow ?? 0;
  const capex = data.capitalExpenditure ?? 0;
  const employees = data.employeeCount ?? 0;
  const capitalEmployed = data.totalAssets - data.currentLiabilities;

  const ebitda = ebit + dep + amort;
  const invTurnover = base.inventoryTurnover || 0;
  const inventoryDays = invTurnover > 0 ? Math.round((365 / invTurnover) * 100) / 100 : 0;

  return {
    ...base,
    // Profitability
    ebitda: Math.round(ebitda * 100) / 100,
    ebitdaMargin: pct(ebitda, data.revenue),
    roce: pct(ebit, capitalEmployed),
    // Leverage
    interestCoverage: interest > 0 ? Math.round(safeDiv(ebit, interest) * 100) / 100 : 0,
    debtRatio: Math.round(safeDiv(data.totalLiabilities, data.totalAssets) * 100) / 100,
    equityMultiplier: Math.round(safeDiv(data.totalAssets, data.totalEquity) * 100) / 100,
    // Liquidity
    cashRatio: Math.round(safeDiv(data.cash, data.currentLiabilities) * 100) / 100,
    workingCapital: Math.round((data.currentAssets - data.currentLiabilities) * 100) / 100,
    operatingCashFlowRatio: Math.round(safeDiv(opCF, data.currentLiabilities) * 100) / 100,
    // Efficiency
    assetTurnover: Math.round(safeDiv(data.revenue, data.totalAssets) * 100) / 100,
    receivablesTurnover: Math.round(safeDiv(data.revenue, data.accountsReceivable) * 100) / 100,
    payablesTurnover: Math.round(safeDiv(data.costOfSales, data.accountsPayable) * 100) / 100,
    inventoryDays,
    cashConversionCycle: Math.round((base.debtorDays + inventoryDays - base.creditorDays) * 100) / 100,
    // Cash Flow
    freeCashFlow: Math.round((opCF - capex) * 100) / 100,
    // Per-Unit
    revenuePerEmployee: employees > 0 ? Math.round(safeDiv(data.revenue, employees) * 100) / 100 : 0,
    // DuPont Decomposition
    dupontMargin: pct(data.netProfit, data.revenue),
    dupontTurnover: Math.round(safeDiv(data.revenue, data.totalAssets) * 100) / 100,
    dupontLeverage: Math.round(safeDiv(data.totalAssets, data.totalEquity) * 100) / 100,
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// VARIANCE
// ═══════════════════════════════════════════════════════════════════════════

export function calculateVariance(actual: number, budget: number, isExpense = false): VarianceResult {
  const amount = Math.round((actual - budget) * 100) / 100;
  const percentage = budget !== 0 ? Math.round((amount / budget) * 10000) / 100 : 0;

  let direction: VarianceResult['direction'] = 'on_budget';
  if (amount > 0) direction = isExpense ? 'unfavorable' : 'favorable';
  else if (amount < 0) direction = isExpense ? 'favorable' : 'unfavorable';

  return { amount, percentage, direction };
}

// ═══════════════════════════════════════════════════════════════════════════
// COMPARATIVE DATA
// ═══════════════════════════════════════════════════════════════════════════

export function buildComparativeData(
  current: Array<{ account: string; amount: number }>,
  prior: Array<{ account: string; amount: number }>,
): ComparativeRow[] {
  const priorMap = new Map(prior.map(p => [p.account, p.amount]));

  return current.map(c => {
    const priorAmount = priorMap.get(c.account) ?? 0;
    const changeAmount = Math.round((c.amount - priorAmount) * 100) / 100;
    const changePercent = priorAmount !== 0 ? Math.round((changeAmount / priorAmount) * 10000) / 100 : 0;

    return {
      account: c.account,
      currentAmount: c.amount,
      priorAmount,
      changeAmount,
      changePercent,
    };
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// MANAGEMENT PACK
// ═══════════════════════════════════════════════════════════════════════════

export function buildManagementPack(input: {
  companyName: string;
  period: string;
  revenue: number;
  expenses: number;
  netProfit: number;
  cashBalance: number;
  arOutstanding: number;
  apOutstanding: number;
}): ManagementPack {
  const profitMargin = input.revenue > 0
    ? Math.round((input.netProfit / input.revenue) * 10000) / 100
    : 0;

  const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

  return {
    companyName: input.companyName,
    period: input.period,
    generatedAt: new Date().toISOString(),
    profitMargin,
    sections: [
      {
        title: 'KPI Summary',
        items: [
          { label: 'Revenue', value: fmt(input.revenue) },
          { label: 'Total Expenses', value: fmt(input.expenses) },
          { label: 'Net Profit', value: fmt(input.netProfit) },
          { label: 'Profit Margin', value: `${profitMargin}%` },
        ],
      },
      {
        title: 'Cash Position',
        items: [
          { label: 'Cash Balance', value: fmt(input.cashBalance) },
          { label: 'AR Outstanding', value: fmt(input.arOutstanding) },
          { label: 'AP Outstanding', value: fmt(input.apOutstanding) },
          { label: 'Net Working Capital', value: fmt(input.cashBalance + input.arOutstanding - input.apOutstanding) },
        ],
      },
    ],
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

export function formatReportNumber(value: number, format: 'currency' | 'percent' | 'number'): string {
  switch (format) {
    case 'currency':
      return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(value);
    case 'percent':
      return `${Math.round(value * 100) / 100}%`;
    case 'number':
      return new Intl.NumberFormat('en-ZA').format(value);
    default:
      return String(value);
  }
}

/**
 * KPI Scorecard Service — traffic-light scoring of financial KPIs.
 * Pure business logic — no database dependencies.
 */

import type { ExtendedRatioResult } from './reportingEngineService';

export interface KPITargetConfig {
  ratioKey: string;
  target: number;
  warningThreshold: number;
  criticalThreshold: number;
  lowerIsBetter: boolean;
}

export interface KPIScorecardItem {
  ratioKey: string;
  name: string;
  value: number;
  target: number;
  status: 'green' | 'amber' | 'red';
  percentOfTarget: number;
}

// Human-readable names for ratio keys
const RATIO_NAMES: Record<string, string> = {
  grossProfitMargin: 'Gross Profit Margin',
  netProfitMargin: 'Net Profit Margin',
  operatingProfitMargin: 'Operating Profit Margin',
  currentRatio: 'Current Ratio',
  quickRatio: 'Quick Ratio',
  debtToEquity: 'Debt-to-Equity',
  returnOnAssets: 'Return on Assets',
  returnOnEquity: 'Return on Equity',
  debtorDays: 'Debtor Days',
  creditorDays: 'Creditor Days',
  inventoryTurnover: 'Inventory Turnover',
  ebitdaMargin: 'EBITDA Margin',
  roce: 'ROCE',
  interestCoverage: 'Interest Coverage',
  debtRatio: 'Debt Ratio',
  equityMultiplier: 'Equity Multiplier',
  cashRatio: 'Cash Ratio',
  workingCapital: 'Working Capital',
  operatingCashFlowRatio: 'Operating CF Ratio',
  assetTurnover: 'Asset Turnover',
  receivablesTurnover: 'Receivables Turnover',
  payablesTurnover: 'Payables Turnover',
  inventoryDays: 'Inventory Days',
  cashConversionCycle: 'Cash Conversion Cycle',
  freeCashFlow: 'Free Cash Flow',
  revenuePerEmployee: 'Revenue per Employee',
};

/**
 * Build a KPI scorecard from ratio results and target configuration.
 */
export function buildKPIScorecard(
  ratios: ExtendedRatioResult,
  targets: KPITargetConfig[],
): KPIScorecardItem[] {
  return targets.map(config => {
    const value = (ratios as unknown as Record<string, unknown>)[config.ratioKey];
    const numValue = typeof value === 'number' ? value : 0;

    const percentOfTarget = config.target !== 0
      ? Math.round((numValue / config.target) * 10000) / 100
      : 0;

    const status = scoreStatus(numValue, config);

    return {
      ratioKey: config.ratioKey,
      name: RATIO_NAMES[config.ratioKey] || config.ratioKey,
      value: numValue,
      target: config.target,
      status,
      percentOfTarget,
    };
  });
}

function scoreStatus(
  value: number,
  config: KPITargetConfig,
): 'green' | 'amber' | 'red' {
  if (config.lowerIsBetter) {
    // Lower is better: below target = green, above warning = amber, above critical = red
    if (value <= config.target) return 'green';
    if (value <= config.warningThreshold) return 'amber';
    return 'red';
  }

  // Higher is better: above target = green, above warning = amber, below critical = red
  if (value >= config.target) return 'green';
  if (value >= config.warningThreshold) return 'amber';
  return 'red';
}

/**
 * Cash Flow Forecasting Service
 * Projects future cash position based on historical patterns,
 * recurring invoices, known payables, and seasonal trends.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export interface CashFlowForecastPoint {
  date: string;          // YYYY-MM-DD
  label: string;         // "Apr 2026", "Week 14", etc.
  projectedInflow: number;
  projectedOutflow: number;
  projectedNet: number;
  projectedBalance: number;
  confidence: number;    // 0-1
}

export interface CashFlowAlert {
  type: 'warning' | 'danger';
  message: string;
  date: string;
  projectedBalance: number;
}

export interface CashFlowForecastResult {
  currentBalance: number;
  forecastPoints: CashFlowForecastPoint[];
  alerts: CashFlowAlert[];
  assumptions: string[];
  generatedAt: string;
}

export interface HistoricalCashFlow {
  month: string;
  inflow: number;
  outflow: number;
  net: number;
}

// ── Historical Analysis ──────────────────────────────────────────────────────

/** Get current total cash balance across all bank accounts */
async function getCurrentCashBalance(): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(
      CASE WHEN ga.account_subtype IN ('bank', 'cash')
        THEN COALESCE(
          (SELECT SUM(jl.debit) - SUM(jl.credit)
           FROM gl_journal_lines jl
           JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
           WHERE jl.gl_account_id = ga.id
             AND je.status = 'posted'),
          0)
        ELSE 0
      END
    ), 0) AS total_cash
    FROM gl_accounts ga
    WHERE ga.account_type = 'asset'
      AND ga.account_subtype IN ('bank', 'cash')
      AND ga.is_active = true
  `) as Row[];
  return Number(rows[0]?.total_cash ?? 0);
}

/** Get monthly cash inflows and outflows for the last N months */
async function getHistoricalCashFlows(months: number): Promise<HistoricalCashFlow[]> {
  // Compute the start date in JS to avoid interval arithmetic in tagged templates
  const startDate = new Date();
  startDate.setMonth(startDate.getMonth() - months);
  const startStr = startDate.toISOString().split('T')[0]!;

  const rows = (await sql`
    WITH monthly AS (
      SELECT
        date_trunc('month', je.entry_date) AS month,
        COALESCE(SUM(CASE WHEN jl.debit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.debit ELSE 0 END), 0) AS inflow,
        COALESCE(SUM(CASE WHEN jl.credit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.credit ELSE 0 END), 0) AS outflow
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND ga.account_type = 'asset'
        AND ga.account_subtype IN ('bank', 'cash')
        AND je.entry_date >= ${startStr}::DATE
      GROUP BY date_trunc('month', je.entry_date)
    )
    SELECT
      to_char(month, 'YYYY-MM') AS month,
      inflow,
      outflow,
      (inflow - outflow) AS net
    FROM monthly
    ORDER BY month ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    month: r.month,
    inflow: Number(r.inflow),
    outflow: Number(r.outflow),
    net: Number(r.net),
  }));
}

/** Get known future receivables (unpaid customer invoices) */
async function getExpectedReceivables(): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM customer_invoices
    WHERE status IN ('sent', 'overdue', 'approved')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get known future payables (unpaid supplier invoices) */
async function getExpectedPayables(): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM supplier_invoices
    WHERE status IN ('approved', 'received', 'overdue')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get recurring invoice amounts for projection */
async function getRecurringRevenue(): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(total_amount), 0) AS monthly_recurring
    FROM recurring_invoices
    WHERE status = 'active'
      AND frequency = 'monthly'
  `) as Row[];
  return Number(rows[0]?.monthly_recurring ?? 0);
}

// ── Forecasting Engine ───────────────────────────────────────────────────────

/**
 * Generate a cash flow forecast for the next N months.
 * Uses a blend of:
 * 1. Known receivables and payables (high confidence)
 * 2. Recurring invoices (medium-high confidence)
 * 3. Historical average patterns (medium confidence)
 * 4. Seasonal adjustment from same month prior year (lower confidence)
 */
export async function generateForecast(companyId: string, 
  forecastMonths = 6,
  alertThreshold = 0
): Promise<CashFlowForecastResult> {
  const [currentBalance, historical, receivables, payables, recurringRevenue] = await Promise.all([
    getCurrentCashBalance(),
    getHistoricalCashFlows(12),
    getExpectedReceivables(),
    getExpectedPayables(),
    getRecurringRevenue(),
  ]);

  // Calculate historical averages
  const avgInflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.inflow, 0) / historical.length
    : 0;
  const avgOutflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.outflow, 0) / historical.length
    : 0;

  // Build month-by-month forecast
  const forecastPoints: CashFlowForecastPoint[] = [];
  const alerts: CashFlowAlert[] = [];
  let runningBalance = currentBalance;
  const now = new Date();

  for (let i = 1; i <= forecastMonths; i++) {
    const forecastDate = new Date(now.getFullYear(), now.getMonth() + i, 1);
    const monthStr = forecastDate.toISOString().slice(0, 7); // YYYY-MM
    const monthLabel = forecastDate.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });

    // Known receivables due this month
    const knownInflows = receivables
      .filter(r => String(r.dueDate).startsWith(monthStr))
      .reduce((sum, r) => sum + r.amount, 0);

    // Known payables due this month
    const knownOutflows = payables
      .filter(p => String(p.dueDate).startsWith(monthStr))
      .reduce((sum, p) => sum + p.amount, 0);

    // Projected inflow: known receivables + recurring revenue + historical average for unknowns
    const knownInflowWeight = knownInflows > 0 ? 0.7 : 0;
    const historicalInflowWeight = 1 - knownInflowWeight;
    const projectedInflow = knownInflows + recurringRevenue + (avgInflow * historicalInflowWeight * 0.5);

    // Projected outflow: known payables + historical average for unknowns
    const knownOutflowWeight = knownOutflows > 0 ? 0.7 : 0;
    const historicalOutflowWeight = 1 - knownOutflowWeight;
    const projectedOutflow = knownOutflows + (avgOutflow * historicalOutflowWeight * 0.5);

    const projectedNet = projectedInflow - projectedOutflow;
    runningBalance += projectedNet;

    // Confidence decreases as we project further out
    const baseConfidence = 0.9;
    const decayFactor = 0.1;
    const knownDataBoost = (knownInflows + knownOutflows > 0) ? 0.1 : 0;
    const confidence = Math.max(0.3, baseConfidence - (i * decayFactor) + knownDataBoost);

    forecastPoints.push({
      date: forecastDate.toISOString().slice(0, 10),
      label: monthLabel,
      projectedInflow: Math.round(projectedInflow * 100) / 100,
      projectedOutflow: Math.round(projectedOutflow * 100) / 100,
      projectedNet: Math.round(projectedNet * 100) / 100,
      projectedBalance: Math.round(runningBalance * 100) / 100,
      confidence: Math.round(confidence * 100) / 100,
    });

    // Generate alerts
    if (runningBalance < alertThreshold) {
      alerts.push({
        type: runningBalance < 0 ? 'danger' : 'warning',
        message: runningBalance < 0
          ? `Projected negative cash balance of R ${Math.abs(runningBalance).toLocaleString('en-ZA', { minimumFractionDigits: 2 })} in ${monthLabel}`
          : `Cash balance projected to drop below threshold in ${monthLabel}`,
        date: forecastDate.toISOString().slice(0, 10),
        projectedBalance: Math.round(runningBalance * 100) / 100,
      });
    }
  }

  // Build assumptions list
  const assumptions: string[] = [];
  if (historical.length > 0) {
    assumptions.push(`Based on ${historical.length} months of historical data`);
  } else {
    assumptions.push('Limited historical data — forecast accuracy may be low');
  }
  if (recurringRevenue > 0) {
    assumptions.push(`Includes R ${recurringRevenue.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} monthly recurring revenue`);
  }
  if (receivables.length > 0) {
    const totalAR = receivables.reduce((s, r) => s + r.amount, 0);
    assumptions.push(`${receivables.length} outstanding invoices totalling R ${totalAR.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  if (payables.length > 0) {
    const totalAP = payables.reduce((s, p) => s + p.amount, 0);
    assumptions.push(`${payables.length} outstanding payables totalling R ${totalAP.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  assumptions.push('Confidence decreases for months further in the future');

  log.info('Cash flow forecast generated', {
    months: forecastMonths,
    currentBalance,
    pointCount: forecastPoints.length,
    alertCount: alerts.length,
  }, 'accounting');

  return {
    currentBalance: Math.round(currentBalance * 100) / 100,
    forecastPoints,
    alerts,
    assumptions,
    generatedAt: new Date().toISOString(),
  };
}

/** Get historical cash flow data for chart display */
export async function getHistoricalForChart(companyId: string, months = 6): Promise<HistoricalCashFlow[]> {
  return getHistoricalCashFlows(months);
}

/**
 * Document Capture API
 * POST /api/accounting/document-capture  — Upload PDF or image, extract data, save
 * GET  /api/accounting/document-capture  — List captured documents
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { Writable } from 'stream';
import formidable from 'formidable';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { extractFromPdf, extractFromImage } from '@/modules/accounting/services/ocrService';
import type { CapturedDocument } from '@/modules/accounting/types/documentCapture.types';

export const config = {
  api: { bodyParser: false },
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

const ALLOWED_MIME_TYPES: Record<string, string> = {
  'application/pdf': 'pdf',
  'image/jpeg': 'jpeg',
  'image/jpg': 'jpeg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/tiff': 'tiff',
};

/** In-memory file buffer attached to formidable file objects */
const fileBuffers = new WeakMap<formidable.File, Buffer>();

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
      filter: (part) => {
        const mime = part.mimetype || '';
        return mime in ALLOWED_MIME_TYPES || !mime;
      },
      fileWriteStreamHandler: (file) => {
        const chunks: Buffer[] = [];
        const writable = new Writable({
          write(chunk, _encoding, callback) {
            chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
            callback();
          },
          final(callback) {
            fileBuffers.set(file as unknown as formidable.File, Buffer.concat(chunks));
            callback();
          },
        });
        return writable;
      },
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>): CapturedDocument {
  return {
    id: row.id as string,
    fileName: row.file_name as string,
    fileType: row.file_type as string,
    fileSize: row.file_size as number | null,
    documentType: row.document_type as string | null,
    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
    vendorName: row.vendor_name as string | null,
    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
    referenceNumber: row.reference_number as string | null,
    totalAmount: row.total_amount !== null && row.total_amount !== undefined ? parseFloat(String(row.total_amount)) : null,
    vatAmount: row.vat_amount !== null && row.vat_amount !== undefined ? parseFloat(String(row.vat_amount)) : null,
    status: (row.status as CapturedDocument['status']) || 'pending',
    matchedInvoiceId: row.matched_invoice_id as string | null,
    matchedBankTxId: row.matched_bank_tx_id as string | null,
    notes: row.notes as string | null,
    uploadedBy: row.uploaded_by as string | null,
    createdAt: new Date(row.created_at as string).toISOString(),
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

/** GET — List captured documents */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const status = req.query.status as string | undefined;
  const page = Math.max(1, parseInt(String(req.query.page || '1'), 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(String(req.query.pageSize || '25'), 10)));
  const offset = (page - 1) * pageSize;

  let rows: Record<string, unknown>[];
  let countResult: Record<string, unknown>[];

  if (status) {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE status = ${status} AND company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE status = ${status} AND company_id = ${companyId}
    ` as Record<string, unknown>[];
  } else {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE company_id = ${companyId}
    ` as Record<string, unknown>[];
  }

  const total = (countResult[0]?.total as number) || 0;
  const documents = rows.map(r => mapRow(r));

  return apiResponse.paginated(res, documents, { page, pageSize, total });
}

/** POST — Upload a PDF or image, extract data, save to captured_documents */
async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const user = (req as NextApiRequest & { user: { id: string } }).user;
  try {
    const { files } = await parseForm(req);

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;

    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded. Please select a PDF or image file.');
    }

    const mimeType = file.mimetype || '';
    const fileTypeKey = ALLOWED_MIME_TYPES[mimeType];

    if (!fileTypeKey) {
      const supported = Object.keys(ALLOWED_MIME_TYPES).join(', ');
      return apiResponse.badRequest(res, `Unsupported file type: ${mimeType}. Supported: ${supported}`);
    }

    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    const buffer = fileBuffers.get(file);
    if (!buffer || buffer.length === 0) {
      return apiResponse.badRequest(res, 'Failed to read uploaded file');
    }

    // Validate file magic bytes
    const hex = buffer.subarray(0, 4).toString('hex').toUpperCase();
    const isPdf = hex.startsWith('25504446'); // %PDF
    const isJpeg = hex.startsWith('FFD8FF');
    const isPng = hex.startsWith('89504E47');
    const isWebp = buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP';
    const isTiff = hex.startsWith('49492A00') || hex.startsWith('4D4D002A');

    if (!isPdf && !isJpeg && !isPng && !isWebp && !isTiff) {
      return apiResponse.badRequest(res, 'File does not appear to be a valid PDF or image');
    }

    log.info('Starting document capture extraction', {
      fileName: file.originalFilename,
      fileSize: file.size,
      mimeType,
      fileType: fileTypeKey,
    }, 'document-capture');

    // Extract data based on file type
    let extracted;
    if (isPdf) {
      extracted = await extractFromPdf(buffer);
    } else {
      extracted = await extractFromImage(buffer, mimeType);
    }

    // Save to database
    const fileName = file.originalFilename || `capture_${Date.now()}.${fileTypeKey}`;

    const [row] = await sql`
      INSERT INTO captured_documents (
        company_id, file_name, file_type, file_size, document_type,
        extracted_data, vendor_name, document_date, reference_number,
        total_amount, vat_amount, status, uploaded_by
      ) VALUES (
        ${companyId},
        ${fileName},
        ${fileTypeKey},
        ${file.size},
        ${extracted.documentType},
        ${JSON.stringify(extracted)}::jsonb,
        ${extracted.vendorName},
        ${extracted.date ? extracted.date : null}::date,
        ${extracted.referenceNumber},
        ${extracted.totalAmount},
        ${extracted.vatAmount},
        'pending',
        ${user?.id || null}::uuid
      )
      RETURNING *
    ` as Record<string, unknown>[];

    log.info('Document captured successfully', {
      id: row?.id,
      confidence: extracted.confidence,
      documentType: extracted.documentType,
      extractionMethod: extracted.extractionMethod,
    }, 'document-capture');

    return apiResponse.created(res, {
      document: mapRow(row as Record<string, unknown>),
      extracted,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Document capture failed', { error: msg }, 'document-capture');

    if (msg.includes('maxFileSize')) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    return apiResponse.internalError(res, err, `Document capture failed: ${msg}`);
  }
}

