/**
 * Contract Extraction Service — Extract terms from contracts → recurring entries.
 * Pure business logic — no database dependencies.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ExtractedContract {
  partyA: string | null;
  partyB: string | null;
  contractDate: string | null;
  startDate: string | null;
  endDate: string | null;
  paymentAmount: number | null;
  paymentFrequency: 'weekly' | 'monthly' | 'quarterly' | 'annually' | null;
  paymentDay: number | null;
  escalationPercent: number | null;
  escalationDate: string | null;
  renewalType: 'auto' | 'manual' | null;
  renewalDate: string | null;
  noticePeriod: string | null;
  description: string | null;
  confidence: number;
}

export interface RecurringInvoiceInput {
  templateName: string;
  supplierId: string;
  frequency: string;
  amount: number;
  nextRunDate: string;
  endDate: string | null;
  description: string;
}

export interface ContractValidation {
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface EscalationEntry {
  year: number;
  amount: number;
  effectiveDate: string;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export function parseContractExtractionResponse(response: string): ExtractedContract | null {
  let jsonStr = response.trim();

  if (jsonStr.includes('<think>')) {
    jsonStr = jsonStr.replace(/<think>[\s\S]*?<\/think>\s*/g, '').trim();
  }
  if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '');
  }
  const match = jsonStr.match(/\{[\s\S]*\}/);
  if (match) jsonStr = match[0];

  try {
    const p = JSON.parse(jsonStr) as Record<string, unknown>;

    const validFreqs = ['weekly', 'monthly', 'quarterly', 'annually'];
    const freq = typeof p.paymentFrequency === 'string' && validFreqs.includes(p.paymentFrequency)
      ? p.paymentFrequency as ExtractedContract['paymentFrequency']
      : null;

    return {
      partyA: typeof p.partyA === 'string' ? p.partyA : null,
      partyB: typeof p.partyB === 'string' ? p.partyB : null,
      contractDate: asDate(p.contractDate),
      startDate: asDate(p.startDate),
      endDate: asDate(p.endDate),
      paymentAmount: typeof p.paymentAmount === 'number' ? p.paymentAmount : null,
      paymentFrequency: freq,
      paymentDay: typeof p.paymentDay === 'number' ? p.paymentDay : null,
      escalationPercent: typeof p.escalationPercent === 'number' ? p.escalationPercent : null,
      escalationDate: asDate(p.escalationDate),
      renewalType: p.renewalType === 'auto' || p.renewalType === 'manual' ? p.renewalType : null,
      renewalDate: asDate(p.renewalDate),
      noticePeriod: typeof p.noticePeriod === 'string' ? p.noticePeriod : null,
      description: typeof p.description === 'string' ? p.description : null,
      confidence: typeof p.confidence === 'number' ? p.confidence : 0.5,
    };
  } catch {
    return null;
  }
}

export function mapContractToRecurringInput(
  contract: ExtractedContract,
  supplierId: string,
): RecurringInvoiceInput {
  return {
    templateName: `${contract.partyB || 'Supplier'} — ${contract.description || 'Contract'}`,
    supplierId,
    frequency: contract.paymentFrequency || 'monthly',
    amount: contract.paymentAmount || 0,
    nextRunDate: contract.startDate || new Date().toISOString().split('T')[0]!,
    endDate: contract.endDate || null,
    description: contract.description || `Contract with ${contract.partyB || 'supplier'}`,
  };
}

export function validateContractExtraction(contract: ExtractedContract): ContractValidation {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (contract.paymentAmount === null || contract.paymentAmount === undefined) {
    errors.push('paymentAmount is required');
  }
  if (!contract.paymentFrequency) {
    errors.push('paymentFrequency is required');
  }
  if (!contract.startDate) {
    warnings.push('startDate not extracted');
  }
  if (!contract.endDate) {
    warnings.push('endDate not extracted — contract may be open-ended');
  }

  return { valid: errors.length === 0, errors, warnings };
}

export function calculateEscalationSchedule(
  baseAmount: number,
  escalationPercent: number,
  startDate: string,
  years: number,
): EscalationEntry[] {
  const entries: EscalationEntry[] = [];
  let amount = baseAmount;
  const startYear = parseInt(startDate.substring(0, 4), 10);
  const monthDay = startDate.substring(4); // -MM-DD

  for (let i = 0; i < years; i++) {
    entries.push({
      year: i + 1,
      amount: Math.round(amount * 100) / 100,
      effectiveDate: `${startYear + i}${monthDay}`,
    });
    amount = amount * (1 + escalationPercent / 100);
  }

  return entries;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function asDate(val: unknown): string | null {
  if (!val || typeof val !== 'string') return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(val)) return val;
  return null;
}

/**
 * Waterfall Data Service — builds data for waterfall charts.
 * Pure business logic — no database dependencies.
 */

export interface WaterfallStep {
  label: string;
  start: number;
  end: number;
  value: number;
  isSubtotal: boolean;
  color: 'green' | 'red' | 'blue' | 'teal';
}

// ---------------------------------------------------------------------------
// Profit Waterfall: Revenue → COGS → Gross Profit → OpEx → Other → Net Profit
// ---------------------------------------------------------------------------

export function buildProfitWaterfall(data: {
  revenue: number;
  costOfSales: number;
  grossProfit: number;
  operatingExpenses: number;
  otherIncome: number;
  otherExpenses: number;
  netProfit: number;
}): WaterfallStep[] {
  const steps: WaterfallStep[] = [];
  let running = 0;

  // Revenue (positive, starts from 0)
  steps.push({ label: 'Revenue', start: 0, end: data.revenue, value: data.revenue, isSubtotal: false, color: 'green' });
  running = data.revenue;

  // Cost of Sales (negative)
  steps.push({ label: 'Cost of Sales', start: running, end: running - data.costOfSales, value: -data.costOfSales, isSubtotal: false, color: 'red' });
  running -= data.costOfSales;

  // Gross Profit (subtotal)
  steps.push({ label: 'Gross Profit', start: 0, end: data.grossProfit, value: data.grossProfit, isSubtotal: true, color: 'teal' });

  // Operating Expenses (negative)
  running = data.grossProfit;
  steps.push({ label: 'Operating Expenses', start: running, end: running - data.operatingExpenses, value: -data.operatingExpenses, isSubtotal: false, color: 'red' });
  running -= data.operatingExpenses;

  // Other Income (positive, skip if zero)
  if (data.otherIncome !== 0) {
    steps.push({ label: 'Other Income', start: running, end: running + data.otherIncome, value: data.otherIncome, isSubtotal: false, color: 'green' });
    running += data.otherIncome;
  }

  // Other Expenses (negative, skip if zero)
  if (data.otherExpenses !== 0) {
    steps.push({ label: 'Other Expenses', start: running, end: running - data.otherExpenses, value: -data.otherExpenses, isSubtotal: false, color: 'red' });
    running -= data.otherExpenses;
  }

  // Net Profit (subtotal)
  steps.push({ label: 'Net Profit', start: 0, end: data.netProfit, value: data.netProfit, isSubtotal: true, color: data.netProfit >= 0 ? 'teal' : 'red' });

  return steps;
}

// ---------------------------------------------------------------------------
// Cash Flow Waterfall: Opening → Operating In → Operating Out → Investing → Financing → Closing
// ---------------------------------------------------------------------------

export function buildCashFlowWaterfall(data: {
  opening: number;
  operatingIn: number;
  operatingOut: number;
  investingNet: number;
  financingNet: number;
  closing: number;
}): WaterfallStep[] {
  const steps: WaterfallStep[] = [];
  let running = data.opening;

  steps.push({ label: 'Opening Balance', start: 0, end: data.opening, value: data.opening, isSubtotal: true, color: 'blue' });

  steps.push({ label: 'Operating Inflows', start: running, end: running + data.operatingIn, value: data.operatingIn, isSubtotal: false, color: 'green' });
  running += data.operatingIn;

  steps.push({ label: 'Operating Outflows', start: running, end: running + data.operatingOut, value: data.operatingOut, isSubtotal: false, color: 'red' });
  running += data.operatingOut;

  if (data.investingNet !== 0) {
    steps.push({ label: 'Investing', start: running, end: running + data.investingNet, value: data.investingNet, isSubtotal: false, color: data.investingNet >= 0 ? 'green' : 'red' });
    running += data.investingNet;
  }

  if (data.financingNet !== 0) {
    steps.push({ label: 'Financing', start: running, end: running + data.financingNet, value: data.financingNet, isSubtotal: false, color: data.financingNet >= 0 ? 'green' : 'red' });
    running += data.financingNet;
  }

  steps.push({ label: 'Closing Balance', start: 0, end: data.closing, value: data.closing, isSubtotal: true, color: 'teal' });

  return steps;
}

// ---------------------------------------------------------------------------
// Variance Waterfall: Budget → each variance → Actual
// ---------------------------------------------------------------------------

export function buildVarianceWaterfall(
  items: Array<{ label: string; budgetAmount: number; actualAmount: number }>,
): WaterfallStep[] {
  const steps: WaterfallStep[] = [];

  const budgetTotal = items.reduce((s, i) => s + i.budgetAmount, 0);
  const actualTotal = items.reduce((s, i) => s + i.actualAmount, 0);

  steps.push({ label: 'Budget Total', start: 0, end: budgetTotal, value: budgetTotal, isSubtotal: true, color: 'blue' });

  let running = budgetTotal;
  for (const item of items) {
    const variance = item.actualAmount - item.budgetAmount;
    if (variance === 0) continue;
    steps.push({
      label: `${item.label} variance`,
      start: running,
      end: running + variance,
      value: variance,
      isSubtotal: false,
      color: variance >= 0 ? 'green' : 'red',
    });
    running += variance;
  }

  steps.push({ label: 'Actual Total', start: 0, end: actualTotal, value: actualTotal, isSubtotal: true, color: 'teal' });

  return steps;
}

/**
 * AI Financial Report Narrative Service
 * Generates management commentary, variance analysis, trend narratives.
 * Pure business logic — no database dependencies.
 */

export type NarrativeTone = 'professional' | 'simplified' | 'executive';

export interface ReportData {
  reportType: 'income_statement' | 'balance_sheet' | 'cash_flow' | 'budget_vs_actual';
  period: string;
  companyName: string;
  currentPeriod: { revenue: number; expenses: number; netProfit: number };
  priorPeriod?: { revenue: number; expenses: number; netProfit: number };
  budget?: { revenue: number; expenses: number; netProfit: number };
}

export interface NarrativeResult {
  summary: string;
  highlights: string[];
  concerns: string[];
  recommendations: string[];
}

export interface VarianceItem {
  account: string;
  actual: number;
  budget: number;
  isExpense: boolean;
}

export interface VarianceCommentary {
  account: string;
  varianceAmount: number;
  percentVariance: number;
  direction: 'favorable' | 'unfavorable' | 'on_budget';
  commentary: string;
}

export interface TrendPoint {
  period: string;
  value: number;
}

export interface TrendResult {
  direction: 'up' | 'down' | 'flat';
  changePercent: number;
  narrative: string;
}

// ═══════════════════════════════════════════════════════════════════════════
// CONTEXT FORMATTING
// ═══════════════════════════════════════════════════════════════════════════

const fmt = (n: number) => `R${Math.abs(n).toLocaleString('en-ZA', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

export function formatNarrativeContext(data: { revenue: number; expenses: number; netProfit: number }): string {
  return `Revenue: ${fmt(data.revenue)} | Expenses: ${fmt(data.expenses)} | Net Profit: ${fmt(data.netProfit)} | Profit Margin: ${data.revenue > 0 ? Math.round((data.netProfit / data.revenue) * 100) : 0}%`;
}

// ═══════════════════════════════════════════════════════════════════════════
// NARRATIVE PROMPT
// ═══════════════════════════════════════════════════════════════════════════

const REPORT_TYPE_LABELS: Record<string, string> = {
  income_statement: 'Income Statement (Profit & Loss)',
  balance_sheet: 'Balance Sheet',
  cash_flow: 'Cash Flow Statement',
  budget_vs_actual: 'Budget vs Actual Report',
};

export function buildNarrativePrompt(data: ReportData, tone: NarrativeTone): string {
  const reportLabel = REPORT_TYPE_LABELS[data.reportType] || data.reportType;

  let context = `Report: ${reportLabel}\nPeriod: ${data.period}\nCompany: ${data.companyName}\n\n`;
  context += `Current Period:\n  ${formatNarrativeContext(data.currentPeriod)}\n`;

  if (data.priorPeriod) {
    context += `\nPrior Period:\n  ${formatNarrativeContext(data.priorPeriod)}\n`;
    const revChange = data.priorPeriod.revenue > 0 ? Math.round(((data.currentPeriod.revenue - data.priorPeriod.revenue) / data.priorPeriod.revenue) * 100) : 0;
    context += `  Revenue Change: ${revChange}%\n`;
  }

  if (data.budget) {
    context += `\nBudget:\n  ${formatNarrativeContext(data.budget)}\n`;
    const revVar = data.budget.revenue > 0 ? Math.round(((data.currentPeriod.revenue - data.budget.revenue) / data.budget.revenue) * 100) : 0;
    context += `  Revenue vs Budget: ${revVar}%\n`;
  }

  return `You are a South African chartered accountant writing a ${tone} management report narrative.

${context}

Write a commentary for this ${reportLabel}. Tone: ${tone}.

Respond in JSON:
{"summary": "2-3 sentence overview", "highlights": ["positive point 1", "..."], "concerns": ["concern 1", "..."], "recommendations": ["action item 1", "..."]}

Rules:
- Use ZAR (South African Rand) for all amounts
- Be specific with numbers and percentages
- ${tone === 'simplified' ? 'Use simple language suitable for non-financial directors' : 'Use professional accounting terminology'}
- Focus on actionable insights`;
}

// ═══════════════════════════════════════════════════════════════════════════
// RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

export function parseNarrativeResponse(response: string): NarrativeResult | null {
  if (!response || response.trim() === '') return null;

  // Try JSON
  try {
    let jsonStr = response;
    const jsonMatch = response.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (jsonMatch) jsonStr = jsonMatch[1]!;
    else {
      const objMatch = response.match(/\{[\s\S]*"summary"[\s\S]*\}/);
      if (objMatch) jsonStr = objMatch[0];
    }

    const parsed = JSON.parse(jsonStr);
    if (parsed.summary) {
      return {
        summary: String(parsed.summary),
        highlights: Array.isArray(parsed.highlights) ? parsed.highlights.map(String) : [],
        concerns: Array.isArray(parsed.concerns) ? parsed.concerns.map(String) : [],
        recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations.map(String) : [],
      };
    }
  } catch { /* not JSON */ }

  // Plain text fallback — use first sentence as summary
  const sentences = response.split(/[.!?]+/).filter(s => s.trim().length > 10);
  if (sentences.length > 0) {
    return {
      summary: sentences.slice(0, 2).join('. ').trim() + '.',
      highlights: [],
      concerns: [],
      recommendations: [],
    };
  }

  return null;
}

// ═══════════════════════════════════════════════════════════════════════════
// VARIANCE COMMENTARY
// ═══════════════════════════════════════════════════════════════════════════

export function buildVarianceCommentary(items: VarianceItem[]): VarianceCommentary[] {
  if (items.length === 0) return [];

  return items
    .map(item => {
      const varianceAmount = item.actual - item.budget;
      const percentVariance = item.budget !== 0 ? Math.round((varianceAmount / item.budget) * 10000) / 100 : 0;

      let direction: VarianceCommentary['direction'] = 'on_budget';
      if (varianceAmount > 0) direction = item.isExpense ? 'unfavorable' : 'favorable';
      else if (varianceAmount < 0) direction = item.isExpense ? 'favorable' : 'unfavorable';

      const dirLabel = direction === 'favorable' ? 'favorably' : direction === 'unfavorable' ? 'unfavorably' : 'on budget';
      const commentary = `${item.account} came in ${dirLabel} at ${fmt(item.actual)} vs budget of ${fmt(item.budget)} (${percentVariance > 0 ? '+' : ''}${percentVariance}%).`;

      return { account: item.account, varianceAmount, percentVariance, direction, commentary };
    })
    .sort((a, b) => Math.abs(b.varianceAmount) - Math.abs(a.varianceAmount));
}

// ═══════════════════════════════════════════════════════════════════════════
// TREND ANALYSIS
// ═══════════════════════════════════════════════════════════════════════════

export function buildTrendAnalysis(points: TrendPoint[], metricName: string): TrendResult {
  if (points.length <= 1) {
    return { direction: 'flat', changePercent: 0, narrative: `${metricName} has insufficient data for trend analysis.` };
  }

  const first = points[0]!.value;
  const last = points[points.length - 1]!.value;
  const changePercent = first !== 0 ? Math.round(((last - first) / first) * 10000) / 100 : 0;

  const FLAT_THRESHOLD = 2; // ±2% = flat
  let direction: TrendResult['direction'] = 'flat';
  if (changePercent > FLAT_THRESHOLD) direction = 'up';
  else if (changePercent < -FLAT_THRESHOLD) direction = 'down';

  const dirLabel = direction === 'up' ? 'increased' : direction === 'down' ? 'decreased' : 'remained stable';
  const narrative = `${metricName} ${dirLabel} by ${Math.abs(changePercent)}% from ${fmt(first)} to ${fmt(last)} over ${points.length} periods.`;

  return { direction, changePercent, narrative };
}

