/**
 * PRD-060: FibreFlow Accounting Module
 * 3-Way Match Validation (PO ↔ GRN ↔ Invoice)
 *
 * Validates that a supplier invoice aligns with the
 * purchase order and goods receipt note.
 */

import type { ThreeWayMatchInput, ThreeWayMatchResult, InvoiceMatchStatus } from '../types/ap.types';

const DEFAULT_TOLERANCE_PERCENT = 2;

/**
 * Validate 3-way match between PO, GRN, and supplier invoice.
 *
 * Checks:
 * 1. Invoice quantity matches PO quantity
 * 2. Invoice unit price matches PO unit price (within tolerance)
 * 3. GRN received quantity matches invoice quantity
 */
export function validateThreeWayMatch(input: ThreeWayMatchInput): ThreeWayMatchResult {
  const tolerance = input.tolerancePercent ?? DEFAULT_TOLERANCE_PERCENT;
  const mismatches: string[] = [];

  // Check quantity match: Invoice vs PO
  const quantityMatch = input.invoiceQuantity === input.poQuantity;
  if (!quantityMatch) {
    mismatches.push(
      `Invoice quantity (${input.invoiceQuantity}) does not match PO quantity (${input.poQuantity})`
    );
  }

  // Check price match: Invoice vs PO (within tolerance)
  const priceDiffPercent =
    input.poUnitPrice > 0
      ? Math.abs(input.invoiceUnitPrice - input.poUnitPrice) / input.poUnitPrice * 100
      : input.invoiceUnitPrice > 0 ? 100 : 0;

  const priceMatch = priceDiffPercent <= tolerance;
  if (!priceMatch) {
    mismatches.push(
      `Invoice unit price (${input.invoiceUnitPrice}) differs from PO price (${input.poUnitPrice}) by ${priceDiffPercent.toFixed(1)}%, exceeds ${tolerance}% tolerance`
    );
  }

  // Check GRN match: GRN received vs Invoice quantity
  const grnMatch = input.grnQuantityReceived === input.invoiceQuantity;
  if (!grnMatch) {
    mismatches.push(
      `GRN received quantity (${input.grnQuantityReceived}) does not match invoice quantity (${input.invoiceQuantity})`
    );
  }

  // Determine overall status
  let status: InvoiceMatchStatus;
  if (quantityMatch && priceMatch && grnMatch) {
    status = 'fully_matched';
  } else if (quantityMatch && priceMatch && !grnMatch) {
    status = 'po_matched';
  } else if (grnMatch && (!quantityMatch || !priceMatch)) {
    status = 'grn_matched';
  } else {
    status = 'unmatched';
  }

  return {
    status,
    quantityMatch,
    priceMatch,
    grnMatch,
    mismatches,
  };
}

/**
 * Fuzzy Match Utility
 * Matches extracted vendor/customer names against existing database records
 * using Dice coefficient on bigrams for SA business name matching.
 */

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

interface MatchCandidate {
  id: string | number;
  name: string;
}

interface MatchResult {
  id: string | number;
  name: string;
  score: number;
}

const DEFAULT_THRESHOLD = 0.6;

/**
 * Find the best matching supplier from a list.
 */
export function fuzzyMatchSupplier(
  extractedName: string,
  suppliers: Array<{ id: string | number; name: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  return findBestMatch(extractedName, suppliers, threshold);
}

/**
 * Find the best matching client from a list.
 * Handles `companyName` field mapping.
 */
export function fuzzyMatchClient(
  extractedName: string,
  clients: Array<{ id: string | number; companyName?: string; name?: string; company_name?: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  const candidates: MatchCandidate[] = clients.map(c => ({
    id: c.id,
    name: c.companyName || c.company_name || c.name || '',
  }));
  return findBestMatch(extractedName, candidates, threshold);
}

// ---------------------------------------------------------------------------
// Core matching
// ---------------------------------------------------------------------------

function findBestMatch(
  query: string,
  candidates: MatchCandidate[],
  threshold: number,
): MatchResult | null {
  if (!query || candidates.length === 0) return null;

  const normalizedQuery = normalize(query);
  if (!normalizedQuery) return null;

  let best: MatchResult | null = null;

  for (const candidate of candidates) {
    const normalizedCandidate = normalize(candidate.name);
    if (!normalizedCandidate) continue;

    // Exact match after normalization
    if (normalizedQuery === normalizedCandidate) {
      return { id: candidate.id, name: candidate.name, score: 1.0 };
    }

    // Containment check (one contains the other)
    if (normalizedQuery.includes(normalizedCandidate) || normalizedCandidate.includes(normalizedQuery)) {
      const score = Math.min(normalizedQuery.length, normalizedCandidate.length) /
        Math.max(normalizedQuery.length, normalizedCandidate.length);
      const adjustedScore = 0.7 + score * 0.3; // Range: 0.7 - 1.0
      if (adjustedScore >= threshold && (!best || adjustedScore > best.score)) {
        best = { id: candidate.id, name: candidate.name, score: Math.round(adjustedScore * 100) / 100 };
      }
      continue;
    }

    // Dice coefficient on bigrams
    const score = diceCoefficient(normalizedQuery, normalizedCandidate);
    if (score >= threshold && (!best || score > best.score)) {
      best = { id: candidate.id, name: candidate.name, score: Math.round(score * 100) / 100 };
    }
  }

  return best;
}

// ---------------------------------------------------------------------------
// Normalization — strips SA business suffixes and noise
// ---------------------------------------------------------------------------

const STRIP_PATTERNS = [
  /\b\(pty\)\b/gi,
  /\bpty\b/gi,
  /\bltd\b/gi,
  /\blimited\b/gi,
  /\binc\b/gi,
  /\bincorporated\b/gi,
  /\bcc\b/gi,
  /\bnpc\b/gi,
  /\bsoc\b/gi,
  /\bt\/a\b/gi,
  /\btrading\s+as\b/gi,
];

function normalize(name: string): string {
  let s = name.toLowerCase().trim();
  for (const pattern of STRIP_PATTERNS) {
    s = s.replace(pattern, '');
  }
  // Remove punctuation and collapse whitespace
  s = s.replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  return s;
}

// ---------------------------------------------------------------------------
// Dice coefficient on bigrams
// ---------------------------------------------------------------------------

function bigrams(str: string): Set<string> {
  const result = new Set<string>();
  for (let i = 0; i < str.length - 1; i++) {
    result.add(str.substring(i, i + 2));
  }
  return result;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;

  const bigramsA = bigrams(a);
  const bigramsB = bigrams(b);

  let intersectionSize = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersectionSize++;
  }

  return (2 * intersectionSize) / (bigramsA.size + bigramsB.size);
}

/**
 * Payslip/IRP5 Cross-Verification Service
 * Pure business logic — no database dependencies.
 */

import type { ValidationDiscrepancy } from '@/modules/accounting/types/documentCapture.types';

export interface ExtractedPayslip {
  employeeName: string | null;
  idNumber: string | null;
  taxNumber: string | null;
  employerName: string | null;
  employerPayeRef: string | null;
  period: string | null;
  grossPay: number | null;
  netPay: number | null;
  paye: number | null;
  uif: number | null;
  sdl: number | null;
  pensionContrib: number | null;
  medicalAid: number | null;
  overtime: number | null;
  bonus: number | null;
  confidence: number;
}

export interface PayrollRecord {
  employeeId: string;
  employeeName: string;
  idNumber: string;
  grossPay: number;
  netPay: number;
  paye: number;
  uif: number;
  sdl: number;
  pension: number;
  medical: number;
}

export interface PayslipVerificationResult {
  valid: boolean;
  score: number;
  discrepancies: ValidationDiscrepancy[];
  verifiedAt: string;
}

export interface EmployeeMatch {
  employeeId: string;
  employeeName: string;
  confidence: number;
  matchMethod: 'id_number' | 'name';
}

export function parsePayslipExtractionResponse(response: string): ExtractedPayslip | null {
  let jsonStr = response.trim();
  if (jsonStr.includes('<think>')) jsonStr = jsonStr.replace(/<think>[\s\S]*?<\/think>\s*/g, '').trim();
  const match = jsonStr.match(/\{[\s\S]*\}/);
  if (match) jsonStr = match[0];

  try {
    const p = JSON.parse(jsonStr) as Record<string, unknown>;
    return {
      employeeName: typeof p.employeeName === 'string' ? p.employeeName : null,
      idNumber: typeof p.idNumber === 'string' ? p.idNumber : null,
      taxNumber: typeof p.taxNumber === 'string' ? p.taxNumber : null,
      employerName: typeof p.employerName === 'string' ? p.employerName : null,
      employerPayeRef: typeof p.employerPayeRef === 'string' ? p.employerPayeRef : null,
      period: typeof p.period === 'string' ? p.period : null,
      grossPay: typeof p.grossPay === 'number' ? p.grossPay : null,
      netPay: typeof p.netPay === 'number' ? p.netPay : null,
      paye: typeof p.paye === 'number' ? p.paye : null,
      uif: typeof p.uif === 'number' ? p.uif : null,
      sdl: typeof p.sdl === 'number' ? p.sdl : null,
      pensionContrib: typeof p.pensionContrib === 'number' ? p.pensionContrib : null,
      medicalAid: typeof p.medicalAid === 'number' ? p.medicalAid : null,
      overtime: typeof p.overtime === 'number' ? p.overtime : null,
      bonus: typeof p.bonus === 'number' ? p.bonus : null,
      confidence: typeof p.confidence === 'number' ? p.confidence : 0.5,
    };
  } catch {
    return null;
  }
}

export function matchEmployeeFromExtraction(
  payslip: ExtractedPayslip,
  employees: Array<{ id: string; name: string; idNumber: string }>,
): EmployeeMatch | null {
  // Prefer ID number match
  if (payslip.idNumber) {
    const match = employees.find(e => e.idNumber === payslip.idNumber);
    if (match) return { employeeId: match.id, employeeName: match.name, confidence: 1.0, matchMethod: 'id_number' };
  }

  // Fall back to name match
  if (payslip.employeeName) {
    const normPayslip = payslip.employeeName.toLowerCase().trim();
    const match = employees.find(e => e.name.toLowerCase().trim() === normPayslip);
    if (match) return { employeeId: match.id, employeeName: match.name, confidence: 0.85, matchMethod: 'name' };

    // Partial match
    const partial = employees.find(e =>
      normPayslip.includes(e.name.toLowerCase().trim()) || e.name.toLowerCase().trim().includes(normPayslip)
    );
    if (partial) return { employeeId: partial.id, employeeName: partial.name, confidence: 0.7, matchMethod: 'name' };
  }

  return null;
}

export function verifyPayslipAgainstPayroll(
  payslip: ExtractedPayslip,
  payroll: PayrollRecord,
): PayslipVerificationResult {
  const discrepancies: ValidationDiscrepancy[] = [];
  const tolerance = 1.01; // R1 rounding tolerance

  const checks: Array<{ field: string; extracted: number | null; expected: number; severity: 'error' | 'warning' }> = [
    { field: 'grossPay', extracted: payslip.grossPay, expected: payroll.grossPay, severity: 'error' },
    { field: 'netPay', extracted: payslip.netPay, expected: payroll.netPay, severity: 'error' },
    { field: 'paye', extracted: payslip.paye, expected: payroll.paye, severity: 'error' },
    { field: 'uif', extracted: payslip.uif, expected: payroll.uif, severity: 'warning' },
    { field: 'sdl', extracted: payslip.sdl, expected: payroll.sdl, severity: 'warning' },
  ];

  let matched = 0;
  let checked = 0;

  for (const check of checks) {
    if (check.extracted === null) continue;
    checked++;

    const diff = Math.abs(check.extracted - check.expected);
    if (diff > tolerance) {
      discrepancies.push({
        field: check.field,
        expected: check.expected,
        actual: check.extracted,
        severity: check.severity,
        message: `${check.field} mismatch: payslip shows ${check.extracted}, payroll has ${check.expected}`,
      });
    } else {
      matched++;
    }
  }

  const hasErrors = discrepancies.some(d => d.severity === 'error');
  const score = checked > 0 ? Math.round((matched / checked) * 100) / 100 : 0;

  return {
    valid: !hasErrors,
    score,
    discrepancies,
    verifiedAt: new Date().toISOString(),
  };
}

export function validatePayslipExtraction(payslip: ExtractedPayslip): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  if (payslip.grossPay === null) errors.push('grossPay is required');
  if (!payslip.employeeName && !payslip.idNumber) errors.push('employeeName or idNumber is required');

  return { valid: errors.length === 0, errors };
}

/**
 * Document Capture API
 * POST /api/accounting/document-capture  — Upload PDF or image, extract data, save
 * GET  /api/accounting/document-capture  — List captured documents
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { Writable } from 'stream';
import formidable from 'formidable';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import { extractFromPdf, extractFromImage } from '@/modules/accounting/services/ocrService';
import type { CapturedDocument } from '@/modules/accounting/types/documentCapture.types';

export const config = {
  api: { bodyParser: false },
};

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

const ALLOWED_MIME_TYPES: Record<string, string> = {
  'application/pdf': 'pdf',
  'image/jpeg': 'jpeg',
  'image/jpg': 'jpeg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/tiff': 'tiff',
};

/** In-memory file buffer attached to formidable file objects */
const fileBuffers = new WeakMap<formidable.File, Buffer>();

function parseForm(req: NextApiRequest): Promise<{ fields: formidable.Fields; files: formidable.Files }> {
  return new Promise((resolve, reject) => {
    const form = formidable({
      maxFileSize: MAX_FILE_SIZE,
      keepExtensions: true,
      filter: (part) => {
        const mime = part.mimetype || '';
        return mime in ALLOWED_MIME_TYPES || !mime;
      },
      fileWriteStreamHandler: (file) => {
        const chunks: Buffer[] = [];
        const writable = new Writable({
          write(chunk, _encoding, callback) {
            chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
            callback();
          },
          final(callback) {
            fileBuffers.set(file as unknown as formidable.File, Buffer.concat(chunks));
            callback();
          },
        });
        return writable;
      },
    });
    form.parse(req, (err, fields, files) => {
      if (err) reject(err);
      else resolve({ fields, files });
    });
  });
}

function mapRow(row: Record<string, unknown>): CapturedDocument {
  return {
    id: row.id as string,
    fileName: row.file_name as string,
    fileType: row.file_type as string,
    fileSize: row.file_size as number | null,
    documentType: row.document_type as string | null,
    extractedData: row.extracted_data ? (typeof row.extracted_data === 'string' ? JSON.parse(row.extracted_data as string) : row.extracted_data) : null,
    vendorName: row.vendor_name as string | null,
    documentDate: row.document_date ? new Date(row.document_date as string).toISOString().split('T')[0]! : null,
    referenceNumber: row.reference_number as string | null,
    totalAmount: row.total_amount !== null && row.total_amount !== undefined ? parseFloat(String(row.total_amount)) : null,
    vatAmount: row.vat_amount !== null && row.vat_amount !== undefined ? parseFloat(String(row.vat_amount)) : null,
    status: (row.status as CapturedDocument['status']) || 'pending',
    matchedInvoiceId: row.matched_invoice_id as string | null,
    matchedBankTxId: row.matched_bank_tx_id as string | null,
    notes: row.notes as string | null,
    uploadedBy: row.uploaded_by as string | null,
    createdAt: new Date(row.created_at as string).toISOString(),
  };
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') return handleGet(req, res);
  if (req.method === 'POST') return handlePost(req, res);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

/** GET — List captured documents */
async function handleGet(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const status = req.query.status as string | undefined;
  const page = Math.max(1, parseInt(String(req.query.page || '1'), 10));
  const pageSize = Math.min(100, Math.max(1, parseInt(String(req.query.pageSize || '25'), 10)));
  const offset = (page - 1) * pageSize;

  let rows: Record<string, unknown>[];
  let countResult: Record<string, unknown>[];

  if (status) {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE status = ${status} AND company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE status = ${status} AND company_id = ${companyId}
    ` as Record<string, unknown>[];
  } else {
    rows = await sql`
      SELECT * FROM captured_documents
      WHERE company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT ${pageSize} OFFSET ${offset}
    ` as Record<string, unknown>[];

    countResult = await sql`
      SELECT COUNT(*)::int AS total FROM captured_documents WHERE company_id = ${companyId}
    ` as Record<string, unknown>[];
  }

  const total = (countResult[0]?.total as number) || 0;
  const documents = rows.map(r => mapRow(r));

  return apiResponse.paginated(res, documents, { page, pageSize, total });
}

/** POST — Upload a PDF or image, extract data, save to captured_documents */
async function handlePost(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;
  const user = (req as NextApiRequest & { user: { id: string } }).user;
  try {
    const { files } = await parseForm(req);

    const fileField = files.file;
    const file = Array.isArray(fileField) ? fileField[0] : fileField;

    if (!file) {
      return apiResponse.badRequest(res, 'No file uploaded. Please select a PDF or image file.');
    }

    const mimeType = file.mimetype || '';
    const fileTypeKey = ALLOWED_MIME_TYPES[mimeType];

    if (!fileTypeKey) {
      const supported = Object.keys(ALLOWED_MIME_TYPES).join(', ');
      return apiResponse.badRequest(res, `Unsupported file type: ${mimeType}. Supported: ${supported}`);
    }

    if (file.size > MAX_FILE_SIZE) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    const buffer = fileBuffers.get(file);
    if (!buffer || buffer.length === 0) {
      return apiResponse.badRequest(res, 'Failed to read uploaded file');
    }

    // Validate file magic bytes
    const hex = buffer.subarray(0, 4).toString('hex').toUpperCase();
    const isPdf = hex.startsWith('25504446'); // %PDF
    const isJpeg = hex.startsWith('FFD8FF');
    const isPng = hex.startsWith('89504E47');
    const isWebp = buffer.subarray(0, 4).toString('ascii') === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WEBP';
    const isTiff = hex.startsWith('49492A00') || hex.startsWith('4D4D002A');

    if (!isPdf && !isJpeg && !isPng && !isWebp && !isTiff) {
      return apiResponse.badRequest(res, 'File does not appear to be a valid PDF or image');
    }

    log.info('Starting document capture extraction', {
      fileName: file.originalFilename,
      fileSize: file.size,
      mimeType,
      fileType: fileTypeKey,
    }, 'document-capture');

    // Extract data based on file type
    let extracted;
    if (isPdf) {
      extracted = await extractFromPdf(buffer);
    } else {
      extracted = await extractFromImage(buffer, mimeType);
    }

    // Save to database
    const fileName = file.originalFilename || `capture_${Date.now()}.${fileTypeKey}`;

    const [row] = await sql`
      INSERT INTO captured_documents (
        company_id, file_name, file_type, file_size, document_type,
        extracted_data, vendor_name, document_date, reference_number,
        total_amount, vat_amount, status, uploaded_by
      ) VALUES (
        ${companyId},
        ${fileName},
        ${fileTypeKey},
        ${file.size},
        ${extracted.documentType},
        ${JSON.stringify(extracted)}::jsonb,
        ${extracted.vendorName},
        ${extracted.date ? extracted.date : null}::date,
        ${extracted.referenceNumber},
        ${extracted.totalAmount},
        ${extracted.vatAmount},
        'pending',
        ${user?.id || null}::uuid
      )
      RETURNING *
    ` as Record<string, unknown>[];

    log.info('Document captured successfully', {
      id: row?.id,
      confidence: extracted.confidence,
      documentType: extracted.documentType,
      extractionMethod: extracted.extractionMethod,
    }, 'document-capture');

    return apiResponse.created(res, {
      document: mapRow(row as Record<string, unknown>),
      extracted,
    });
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('Document capture failed', { error: msg }, 'document-capture');

    if (msg.includes('maxFileSize')) {
      return apiResponse.badRequest(res, `File too large. Maximum size: ${MAX_FILE_SIZE / (1024 * 1024)}MB`);
    }

    return apiResponse.internalError(res, err, `Document capture failed: ${msg}`);
  }
}

