export function projectBalanceSheet(
  historical: HistoricalFinancials,
  params: ForecastParams,
  monthIndex: number,
  netProfit: number,
): ForecastBalanceSheet {
  // AR grows proportionally with revenue growth
  const monthlyRevRate = params.revenueGrowthRate / 100 / 12;
  const accountsReceivable = Math.round(historical.accountsReceivable * Math.pow(1 + monthlyRevRate, monthIndex) * 100) / 100;

  // AP grows proportionally with COGS growth
  const monthlyCOGSRate = params.costOfSalesGrowthRate / 100 / 12;
  const accountsPayable = Math.round(historical.accountsPayable * Math.pow(1 + monthlyCOGSRate, monthIndex) * 100) / 100;

  // Fixed assets: prior + capex (simple model, no depreciation for projection)
  const cumulativeCapex = params.capitalExpenditure * monthIndex;
  const fixedAssets = Math.max(0, Math.round((historical.totalAssets - historical.currentAssets + cumulativeCapex) * 100) / 100);

  // Other current assets remain stable (inventory, prepayments)
  const otherCurrentAssets = historical.currentAssets - historical.cash - historical.accountsReceivable;

  // Cash will be set after CF projection — use provisional value here
  // We'll recalculate after CF is known; use a placeholder for now
  const provisionalCash = historical.cash;
  const currentAssets = Math.round((provisionalCash + accountsReceivable + Math.max(0, otherCurrentAssets)) * 100) / 100;
  const totalAssets = Math.round((currentAssets + fixedAssets) * 100) / 100;

  // Liabilities
  const otherCurrentLiabilities = Math.max(0, historical.currentLiabilities - historical.accountsPayable);
  const currentLiabilities = Math.round((accountsPayable + otherCurrentLiabilities) * 100) / 100;
  const longTermLiabilities = Math.round((historical.totalLiabilities - historical.currentLiabilities) * 100) / 100;
  const totalLiabilities = Math.round((currentLiabilities + longTermLiabilities) * 100) / 100;

  // Equity: opening equity + cumulative retained earnings
  const cumulativeRetained = netProfit * monthIndex;
  const retainedEarnings = Math.round((historical.totalEquity - historical.totalLiabilities + cumulativeRetained) * 100) / 100;
  const totalEquity = Math.round((historical.totalEquity + cumulativeRetained) * 100) / 100;

  // Force balance: A = L + E by adjusting retained earnings
  const impliedAssets = Math.round((totalLiabilities + totalEquity) * 100) / 100;
  const balancedTotalAssets = impliedAssets;
  const balancedCurrentAssets = Math.round((balancedTotalAssets - fixedAssets) * 100) / 100;

  return {
    cash: provisionalCash,
    accountsReceivable,
    otherCurrentAssets: Math.max(0, Math.round(otherCurrentAssets * 100) / 100),
    currentAssets: balancedCurrentAssets,
    fixedAssets,
    totalAssets: balancedTotalAssets,
    accountsPayable,
    otherCurrentLiabilities,
    currentLiabilities,
    longTermLiabilities,
    totalLiabilities,
    retainedEarnings,
    totalEquity,
  };
}

