    otherCurrentAssets: Math.round(otherCurrentAssets * 100) / 100,
    currentAssets,
    fixedAssets,
    totalAssets,
    accountsPayable,
    otherCurrentLiabilities,
    currentLiabilities,
    longTermLiabilities,
    totalLiabilities,
    retainedEarnings,
    totalEquity,
  };
}

