### Critical API route pattern to follow exactly:

```typescript
import { sql } from '@/lib/neon';
import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    // ... handle GET
    return apiResponse.success(res, data);
  }

  if (req.method === 'POST') {
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    // ... handle POST
    return apiResponse.success(res, data);
  }

  return apiResponse.methodNotAllowed(res, req.method || '', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));
```

### apiResponse helpers available:
- `apiResponse.success(res, data)` — 200 with `{ success: true, data }`
- `apiResponse.created(res, data)` — 201
- `apiResponse.badRequest(res, message)` — 400
- `apiResponse.validationError(res, errors)` — 422
- `apiResponse.methodNotAllowed(res, method, allowed)` — 405
- `apiResponse.databaseError(res, err, message)` — 500

### Import paths for services (these will exist — another agent creates them):
```typescript
