              </div>

              {/* Validation note */}
              <div className="flex items-start gap-2 p-3 rounded-lg border border-teal-500/20 bg-teal-500/5 text-xs text-teal-400">
                <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" />
