/**
 * System Account Resolver
 *
 * Resolves system GL accounts by their account_subtype instead of hardcoded
 * account codes. This decouples business logic from specific numbering schemes,
 * allowing customers to use any chart of accounts numbering (Sage, Xero, etc.).
 *
 * Usage:
 *   const arAccountId = await getSystemAccountId('receivable');
 *   const arAccount   = await getSystemAccount('receivable');
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { GLAccount, GLAccountSubtype } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Subtypes that the system requires for auto-posting and reporting.
 * Each maps to exactly one system account (is_system_account = true).
 */
export type SystemAccountKey =
  | 'bank'                      // Primary bank account
  | 'receivable'                // Accounts Receivable
  | 'payable'                   // Accounts Payable
  | 'vat_input'                 // VAT Input (claimable)
  | 'vat_output'                // VAT Output (payable)
  | 'retained_earnings'         // Retained Earnings
  | 'default_revenue'           // Default revenue account
  | 'other_income'              // Other Income
  | 'default_expense'           // Default expense (Materials & Supplies)
  | 'admin_expense'             // Administrative Expenses
  | 'accumulated_depreciation'  // Accumulated Depreciation
  | 'depreciation_expense';     // Depreciation Expense

// ── In-memory cache ─────────────────────────────────────────────────────────

interface CachedAccount {
  id: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string;
}

let cache: Map<string, CachedAccount> | null = null;
let cacheLoadedAt = 0;
const CACHE_TTL_MS = 60_000; // 1 minute

/** Clear the cache (call after chart of accounts changes) */
export function clearSystemAccountCache(): void {
  cache = null;
  cacheLoadedAt = 0;
}

async function ensureCache(): Promise<Map<string, CachedAccount>> {
  if (cache && Date.now() - cacheLoadedAt < CACHE_TTL_MS) return cache;

  const rows = (await sql`
    SELECT id, account_code, account_name, account_type, account_subtype
    FROM gl_accounts
    WHERE is_system_account = true
      AND is_active = true
      AND account_subtype IS NOT NULL
  `) as Row[];

  const map = new Map<string, CachedAccount>();
  for (const r of rows) {
    const subtype = String(r.account_subtype);
    map.set(subtype, {
      id: String(r.id),
      accountCode: String(r.account_code),
      accountName: String(r.account_name),
      accountType: String(r.account_type),
      accountSubtype: subtype,
    });
  }

  cache = map;
  cacheLoadedAt = Date.now();
  return map;
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * Get a system account by its subtype key.
 * Throws if the account is not found (misconfigured chart of accounts).
 */
export async function getSystemAccount(key: SystemAccountKey): Promise<CachedAccount> {
  const map = await ensureCache();
  const account = map.get(key);
  if (!account) {
    log.error('System account not found', { key }, 'accounting');
    throw new Error(
      `System account with subtype '${key}' not found. ` +
      `Ensure the chart of accounts has a system account with account_subtype = '${key}'.`
    );
  }
  return account;
}

/**
 * Get only the account ID for a system account.
 * Convenience wrapper for the most common use case (building journal lines).
 */
export async function getSystemAccountId(key: SystemAccountKey): Promise<string> {
  const account = await getSystemAccount(key);
  return account.id;
}

/**
 * Check whether all required system accounts are configured.
 * Returns a list of missing subtypes (empty = all good).
 */
export async function validateSystemAccounts(): Promise<string[]> {
  const required: SystemAccountKey[] = [
    'bank', 'receivable', 'payable',
    'vat_input', 'vat_output', 'retained_earnings',
    'default_revenue', 'default_expense', 'admin_expense',
  ];

  const map = await ensureCache();
  return required.filter(key => !map.has(key));
}

/**
 * Fuzzy Match Utility
 * Matches extracted vendor/customer names against existing database records
 * using Dice coefficient on bigrams for SA business name matching.
 */

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

interface MatchCandidate {
  id: string | number;
  name: string;
}

interface MatchResult {
  id: string | number;
  name: string;
  score: number;
}

const DEFAULT_THRESHOLD = 0.6;

/**
 * Find the best matching supplier from a list.
 */
export function fuzzyMatchSupplier(
  extractedName: string,
  suppliers: Array<{ id: string | number; name: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  return findBestMatch(extractedName, suppliers, threshold);
}

/**
 * Find the best matching client from a list.
 * Handles `companyName` field mapping.
 */
export function fuzzyMatchClient(
  extractedName: string,
  clients: Array<{ id: string | number; companyName?: string; name?: string; company_name?: string }>,
  threshold = DEFAULT_THRESHOLD,
): MatchResult | null {
  const candidates: MatchCandidate[] = clients.map(c => ({
    id: c.id,
    name: c.companyName || c.company_name || c.name || '',
  }));
  return findBestMatch(extractedName, candidates, threshold);
}

// ---------------------------------------------------------------------------
// Core matching
// ---------------------------------------------------------------------------

function findBestMatch(
  query: string,
  candidates: MatchCandidate[],
  threshold: number,
): MatchResult | null {
  if (!query || candidates.length === 0) return null;

  const normalizedQuery = normalize(query);
  if (!normalizedQuery) return null;

  let best: MatchResult | null = null;

  for (const candidate of candidates) {
    const normalizedCandidate = normalize(candidate.name);
    if (!normalizedCandidate) continue;

    // Exact match after normalization
    if (normalizedQuery === normalizedCandidate) {
      return { id: candidate.id, name: candidate.name, score: 1.0 };
    }

    // Containment check (one contains the other)
    if (normalizedQuery.includes(normalizedCandidate) || normalizedCandidate.includes(normalizedQuery)) {
      const score = Math.min(normalizedQuery.length, normalizedCandidate.length) /
        Math.max(normalizedQuery.length, normalizedCandidate.length);
      const adjustedScore = 0.7 + score * 0.3; // Range: 0.7 - 1.0
      if (adjustedScore >= threshold && (!best || adjustedScore > best.score)) {
        best = { id: candidate.id, name: candidate.name, score: Math.round(adjustedScore * 100) / 100 };
      }
      continue;
    }

    // Dice coefficient on bigrams
    const score = diceCoefficient(normalizedQuery, normalizedCandidate);
    if (score >= threshold && (!best || score > best.score)) {
      best = { id: candidate.id, name: candidate.name, score: Math.round(score * 100) / 100 };
    }
  }

  return best;
}

// ---------------------------------------------------------------------------
// Normalization — strips SA business suffixes and noise
// ---------------------------------------------------------------------------

const STRIP_PATTERNS = [
  /\b\(pty\)\b/gi,
  /\bpty\b/gi,
  /\bltd\b/gi,
  /\blimited\b/gi,
  /\binc\b/gi,
  /\bincorporated\b/gi,
  /\bcc\b/gi,
  /\bnpc\b/gi,
  /\bsoc\b/gi,
  /\bt\/a\b/gi,
  /\btrading\s+as\b/gi,
];

function normalize(name: string): string {
  let s = name.toLowerCase().trim();
  for (const pattern of STRIP_PATTERNS) {
    s = s.replace(pattern, '');
  }
  // Remove punctuation and collapse whitespace
  s = s.replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
  return s;
}

// ---------------------------------------------------------------------------
// Dice coefficient on bigrams
// ---------------------------------------------------------------------------

function bigrams(str: string): Set<string> {
  const result = new Set<string>();
  for (let i = 0; i < str.length - 1; i++) {
    result.add(str.substring(i, i + 2));
  }
  return result;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;

  const bigramsA = bigrams(a);
  const bigramsB = bigrams(b);

  let intersectionSize = 0;
  for (const bg of bigramsA) {
    if (bigramsB.has(bg)) intersectionSize++;
  }

  return (2 * intersectionSize) / (bigramsA.size + bigramsB.size);
}

