async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    const rows = await sql`
      SELECT * FROM migration_sessions
      WHERE company_id = ${companyId} AND status = 'in_progress'
      ORDER BY started_at DESC
      LIMIT 1
    `;
    return apiResponse.success(res, { session: rows[0] ?? null });
  }

  if (req.method === 'POST') {
    const userId = (req as AuthenticatedNextApiRequest).user.id;
    const { sourceSystem } = req.body as { sourceSystem?: string };

    if (!sourceSystem) {
      return apiResponse.validationError(res, { sourceSystem: 'sourceSystem is required' });
    }

    const rows = await sql`
      INSERT INTO migration_sessions (
        id, company_id, source_system, status, started_by, started_at, created_at
      ) VALUES (
