/**
 * Migration Chart of Accounts API
 * POST /api/accounting/migration/chart-of-accounts — import accounts from source system
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { importChartOfAccounts } from '@/modules/accounting/services/migrationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);
  }

  const { sessionId, accounts, systemAccountMap } = req.body as {
    sessionId?: string;
    accounts?: unknown[];
    systemAccountMap?: Record<string, string>;
  };

  if (!sessionId) {
    return apiResponse.validationError(res, { sessionId: 'sessionId is required' });
  }
  if (!accounts || !Array.isArray(accounts) || accounts.length === 0) {
    return apiResponse.validationError(res, { accounts: 'accounts array is required and must not be empty' });
  }
  if (!systemAccountMap || typeof systemAccountMap !== 'object') {
    return apiResponse.validationError(res, { systemAccountMap: 'systemAccountMap is required' });
