import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { importSuppliers } from '@/modules/accounting/services/migrationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);
  }

  const { sessionId, suppliers, duplicateStrategy } = req.body as {
    sessionId?: string;
    suppliers?: unknown[];
    duplicateStrategy?: string;
  };

  if (!sessionId) {
    return apiResponse.validationError(res, { sessionId: 'sessionId is required' });
  }
  if (!suppliers || !Array.isArray(suppliers) || suppliers.length === 0) {
    return apiResponse.validationError(res, { suppliers: 'suppliers array is required and must not be empty' });
  }

  const result = await importSuppliers(companyId, sessionId, suppliers, duplicateStrategy);

  log.info('Suppliers imported', { sessionId, count: suppliers.length, duplicateStrategy, module: 'migration' });
  return apiResponse.success(res, result);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

