/**
 * Migration AP Invoices API
 * POST /api/accounting/migration/ap-invoices — import accounts payable invoices from source system
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { importAPInvoices } from '@/modules/accounting/services/migrationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || '', ['POST']);
  }

  const { sessionId, invoices } = req.body as {
    sessionId?: string;
    invoices?: unknown[];
  };

  if (!sessionId) {
    return apiResponse.validationError(res, { sessionId: 'sessionId is required' });
  }
  if (!invoices || !Array.isArray(invoices) || invoices.length === 0) {
    return apiResponse.validationError(res, { invoices: 'invoices array is required and must not be empty' });
  }

  const result = await importAPInvoices(companyId, sessionId, invoices);

  log.info('AP invoices imported', { sessionId, count: invoices.length, module: 'migration' });
  return apiResponse.success(res, result);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

