    UPDATE migration_sessions SET
      source_system       = COALESCE(${updates.sourceSystem ?? null}, source_system),
      status              = COALESCE(${updates.status ?? null}, status),
      steps_completed     = COALESCE(${updates.stepsCompleted ? JSON.stringify(updates.stepsCompleted) : null}::JSONB, steps_completed),
      coa_records_imported  = COALESCE(${updates.coaRecordsImported ?? null}, coa_records_imported),
      customers_imported  = COALESCE(${updates.customersImported ?? null}, customers_imported),
      suppliers_imported  = COALESCE(${updates.suppliersImported ?? null}, suppliers_imported),
      opening_balances_set = COALESCE(${updates.openingBalancesSet ?? null}, opening_balances_set),
      ar_invoices_imported = COALESCE(${updates.arInvoicesImported ?? null}, ar_invoices_imported),
      ap_invoices_imported = COALESCE(${updates.apInvoicesImported ?? null}, ap_invoices_imported),
      errors              = COALESCE(${updates.errors ? JSON.stringify(updates.errors) : null}::JSONB, errors),
      notes               = COALESCE(${updates.notes ?? null}, notes),
      completed_at        = COALESCE(${updates.completedAt ?? null}::TIMESTAMPTZ, completed_at)
    WHERE id = ${sessionId}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `) as Row[];
  return mapSessionRow(rows[0]);
}

export async function completeSession(
  sessionId: string,
  companyId: string,
): Promise<MigrationSession> {
  const rows = (await sql`
    UPDATE migration_sessions
    SET status = 'completed', completed_at = NOW()
    WHERE id = ${sessionId}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `) as Row[];
  log.info('Migration session completed', { sessionId, companyId }, 'migration');
  return mapSessionRow(rows[0]);
}

// ── Chart of Accounts Import ─────────────────────────────────────────────────

export async function importChartOfAccounts(
  companyId: string,
  sessionId: string,
  accounts: AccountImportRow[],
  systemAccountMap: SystemAccountMap,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  // Sort by level: parent codes with no parent first, then by depth
  const sorted = sortAccountsByHierarchy(accounts);

  for (let i = 0; i < sorted.length; i++) {
    const acct = sorted[i];
    try {
      // Resolve parent_account_id if parentCode provided
      let parentAccountId: string | null = null;
      if (acct.parentCode) {
        const parentRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE account_code = ${acct.parentCode} AND company_id = ${companyId}::UUID
        `) as Row[];
        if (parentRows.length === 0) {
          errors.push({ step: 'coa', row: i, field: 'parentCode', message: `Parent code ${acct.parentCode} not found` });
          skipped++;
          continue;
        }
        parentAccountId = String(parentRows[0].id);
      }

      const subtypeEntry = Object.entries(systemAccountMap).find(([, code]) => code === acct.accountCode);
      const accountSubtype = subtypeEntry ? subtypeEntry[0] : (acct.accountSubtype ?? null);
      const isSystem = subtypeEntry != null;

      await sql`
        INSERT INTO gl_accounts (
          company_id, account_code, account_name, account_type, account_subtype,
          normal_balance, parent_account_id, description, is_system_account,
          level, display_order
        ) VALUES (
          ${companyId}::UUID,
          ${acct.accountCode},
          ${acct.accountName},
          ${acct.accountType},
          ${accountSubtype},
          ${acct.normalBalance},
          ${parentAccountId}::UUID,
          ${acct.description ?? null},
          ${isSystem},
          ${parentAccountId ? 2 : 1},
          0
        )
        ON CONFLICT (company_id, account_code) DO UPDATE SET
          account_name    = EXCLUDED.account_name,
          account_type    = EXCLUDED.account_type,
          account_subtype = COALESCE(EXCLUDED.account_subtype, gl_accounts.account_subtype),
          normal_balance  = EXCLUDED.normal_balance,
          description     = COALESCE(EXCLUDED.description, gl_accounts.description),
          is_system_account = EXCLUDED.is_system_account OR gl_accounts.is_system_account
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'coa', row: i, field: 'accountCode', message: msg });
      skipped++;
    }
  }

  // Apply system account subtypes from the explicit map
  for (const [subtype, accountCode] of Object.entries(systemAccountMap)) {
    await sql`
      UPDATE gl_accounts
      SET account_subtype = ${subtype}, is_system_account = true
      WHERE company_id = ${companyId}::UUID AND account_code = ${accountCode}
    `;
  }

  clearSystemAccountCache();

  await updateSession(sessionId, companyId, {
    coaRecordsImported: imported,
    stepsCompleted: { coa: true },
    errors,
  });

  log.info('COA import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

function sortAccountsByHierarchy(accounts: AccountImportRow[]): AccountImportRow[] {
  const withParent = accounts.filter(a => a.parentCode);
  const withoutParent = accounts.filter(a => !a.parentCode);
  return [...withoutParent, ...withParent];
}

// ── Customer Import ──────────────────────────────────────────────────────────

export async function importCustomers(
  companyId: string,
  sessionId: string,
  customers: CustomerImportRow[],
  duplicateStrategy: 'skip' | 'overwrite' | 'merge' = 'skip',
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  // Load existing customer names for duplicate detection
  const existingRows = (await sql`
    SELECT id, name FROM customers WHERE company_id = ${companyId}::UUID
  `) as Row[];
  const existing = existingRows.map(r => ({ id: String(r.id), name: String(r.name) }));

  for (let i = 0; i < customers.length; i++) {
    const cust = customers[i];
    if (!cust.name?.trim()) {
      errors.push({ step: 'customers', row: i, field: 'name', message: 'Name is required' });
      skipped++;
      continue;
    }

    try {
      const duplicate = findExactOrFuzzyDuplicate(cust.name, existing);

      if (duplicate && duplicateStrategy === 'skip') {
        skipped++;
        continue;
      }

      if (duplicate && duplicateStrategy === 'overwrite') {
        await sql`
          UPDATE customers SET
            email              = COALESCE(${cust.email ?? null}, email),
            phone              = COALESCE(${cust.phone ?? null}, phone),
            vat_number         = COALESCE(${cust.vatNumber ?? null}, vat_number),
            billing_address    = COALESCE(${cust.billingAddress ?? null}, billing_address),
            contact_person     = COALESCE(${cust.contactPerson ?? null}, contact_person),
            payment_terms      = COALESCE(${cust.paymentTerms ?? null}, payment_terms),
            credit_limit       = COALESCE(${cust.creditLimit ?? null}, credit_limit)
          WHERE id = ${duplicate.id}::UUID AND company_id = ${companyId}::UUID
        `;
        imported++;
        continue;
      }

      await sql`
        INSERT INTO customers (
          company_id, name, email, phone, vat_number, registration_number,
          billing_address, contact_person, payment_terms, credit_limit, notes
        ) VALUES (
          ${companyId}::UUID,
          ${cust.name},
          ${cust.email ?? null},
          ${cust.phone ?? null},
          ${cust.vatNumber ?? null},
          ${cust.registrationNumber ?? null},
          ${cust.billingAddress ?? null},
          ${cust.contactPerson ?? null},
          ${cust.paymentTerms ?? 30},
          ${cust.creditLimit ?? null},
          ${cust.notes ?? null}
        )
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'customers', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, {
    customersImported: imported,
    stepsCompleted: { customers: true },
  });

  log.info('Customer import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Supplier Import ──────────────────────────────────────────────────────────

export async function importSuppliers(
  companyId: string,
  sessionId: string,
  suppliers: SupplierImportRow[],
  duplicateStrategy: 'skip' | 'overwrite' | 'merge' = 'skip',
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const existingRows = (await sql`
    SELECT id, COALESCE(company_name, name) AS name FROM suppliers
    WHERE company_id = ${companyId}::UUID
  `) as Row[];
  const existing = existingRows.map(r => ({ id: String(r.id), name: String(r.name) }));

  for (let i = 0; i < suppliers.length; i++) {
    const sup = suppliers[i];
    if (!sup.name?.trim()) {
      errors.push({ step: 'suppliers', row: i, field: 'name', message: 'Name is required' });
      skipped++;
      continue;
    }

    try {
      const duplicate = findExactOrFuzzyDuplicate(sup.name, existing);

      if (duplicate && duplicateStrategy === 'skip') {
        skipped++;
        continue;
      }

      if (duplicate && duplicateStrategy === 'overwrite') {
        await sql`
          UPDATE suppliers SET
            email              = COALESCE(${sup.email ?? null}, email),
            phone              = COALESCE(${sup.phone ?? null}, phone),
            vat_number         = COALESCE(${sup.vatNumber ?? null}, vat_number),
            bank_name          = COALESCE(${sup.bankName ?? null}, bank_name),
            bank_account_number = COALESCE(${sup.bankAccountNumber ?? null}, bank_account_number),
            bank_branch_code   = COALESCE(${sup.bankBranchCode ?? null}, bank_branch_code),
            bank_account_type  = COALESCE(${sup.bankAccountType ?? null}, bank_account_type)
          WHERE id = ${duplicate.id}::UUID AND company_id = ${companyId}::UUID
        `;
        imported++;
        continue;
      }

      await sql`
        INSERT INTO suppliers (
          company_id, name, email, phone, vat_number, registration_number,
          billing_address, contact_person, payment_terms,
          bank_name, bank_account_number, bank_branch_code, bank_account_type, notes
        ) VALUES (
          ${companyId}::UUID,
          ${sup.name},
          ${sup.email ?? null},
          ${sup.phone ?? null},
          ${sup.vatNumber ?? null},
          ${sup.registrationNumber ?? null},
          ${sup.billingAddress ?? null},
          ${sup.contactPerson ?? null},
          ${sup.paymentTerms ?? 30},
          ${sup.bankName ?? null},
          ${sup.bankAccountNumber ?? null},
          ${sup.bankBranchCode ?? null},
          ${sup.bankAccountType ?? null},
          ${sup.notes ?? null}
        )
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'suppliers', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, {
    suppliersImported: imported,
    stepsCompleted: { suppliers: true },
  });

  log.info('Supplier import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function findExactOrFuzzyDuplicate(
  name: string,
  existing: Array<{ id: string; name: string }>,
): { id: string; name: string } | null {
  const normalized = name.toLowerCase().trim();
  const exact = existing.find(e => e.name.toLowerCase().trim() === normalized);
  if (exact) return exact;

  // 80% similarity threshold via bigram dice coefficient
  for (const e of existing) {
    const score = diceCoefficient(normalized, e.name.toLowerCase().trim());
    if (score >= 0.8) return e;
  }
  return null;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const bigramsA = new Set<string>();
  const bigramsB = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) bigramsA.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bigramsB.add(b.substring(i, i + 2));
  let intersection = 0;
  for (const bg of bigramsA) { if (bigramsB.has(bg)) intersection++; }
  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

// Re-export createJournalEntry and postJournalEntry for use in migrationImportService
export { createJournalEntry, postJournalEntry };

