      if (invRows.length === 0) { skipped++; continue; }
      const invoiceId = String(invRows[0].id);

      // Post GL: DR Expense + VAT Input, CR Payable
      const journalLines = [
        { glAccountId: expenseAccountId, debit: inv.subtotal, credit: 0, description: `Expense — ${inv.invoiceNumber}` },
        { glAccountId: apAccountId, debit: 0, credit: inv.totalAmount, description: `AP — ${inv.invoiceNumber}` },
      ];
      if (inv.taxAmount > 0) {
        journalLines.push({ glAccountId: vatInputId, debit: inv.taxAmount, credit: 0, description: `VAT Input — ${inv.invoiceNumber}` });
        // Adjust AP credit to match total (already correct above)
      }

      const entry = await createJournalEntry(companyId, {
        entryDate: inv.invoiceDate,
        description: `Migrated AP invoice ${inv.invoiceNumber}`,
        source: 'auto_migration',
        sourceDocumentId: invoiceId,
        lines: journalLines,
      });
      await postJournalEntry(companyId, entry.id, userId);
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'ap_invoices', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, {
    apInvoicesImported: imported,
    stepsCompleted: { ap_invoices: true },
    errors,
  });

  log.info('AP invoices imported', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function matchContact(name: string, candidates: Row[]): string | null {
  const normalized = name.toLowerCase().trim();
  const exact = candidates.find(c => String(c.name).toLowerCase().trim() === normalized);
  if (exact) return String(exact.id);

  let best: { id: string; score: number } | null = null;
  for (const c of candidates) {
    const score = diceCoefficient(normalized, String(c.name).toLowerCase().trim());
    if (score >= 0.7 && (!best || score > best.score)) {
      best = { id: String(c.id), score };
    }
  }
  return best?.id ?? null;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const bigramsA = new Set<string>();
  const bigramsB = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) bigramsA.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bigramsB.add(b.substring(i, i + 2));
  let intersection = 0;
  for (const bg of bigramsA) { if (bigramsB.has(bg)) intersection++; }
  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

