 * PRD: Customer Migration Wizard — Phase 1
 *
 * Handles session management and data import for each wizard step.
 * Split into two files: this file (sessions + COA + contacts) and
 * migrationImportService.ts (balances + invoices).
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { clearSystemAccountCache } from './systemAccountResolver';
import type { GLAccountType } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type MigrationStatus = 'in_progress' | 'completed' | 'abandoned';

export interface MigrationSession {
  id: string;
  companyId: string;
  sourceSystem: string | null;
  status: MigrationStatus;
  stepsCompleted: Record<string, boolean>;
  coaRecordsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: boolean;
  arInvoicesImported: number;
  apInvoicesImported: number;
  errors: MigrationError[];
  startedBy: string;
  startedAt: string;
  completedAt: string | null;
  notes: string | null;
}

export interface MigrationError {
  step: string;
  row?: number;
  field?: string;
  message: string;
}

export interface AccountImportRow {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentCode?: string;
  normalBalance: 'debit' | 'credit';
  description?: string;
}

export interface SystemAccountMap {
  bank: string;
  receivable: string;
  payable: string;
  vat_input: string;
  vat_output: string;
  retained_earnings: string;
  default_revenue: string;
  default_expense: string;
  admin_expense: string;
}

export interface CustomerImportRow {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  registrationNumber?: string;
  billingAddress?: string;
  contactPerson?: string;
  paymentTerms?: number;
  creditLimit?: number;
  notes?: string;
}

export interface SupplierImportRow {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  registrationNumber?: string;
  billingAddress?: string;
  contactPerson?: string;
  paymentTerms?: number;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  notes?: string;
}

export interface ImportResult {
  imported: number;
  skipped: number;
  errors: MigrationError[];
}

// ── Session Management ───────────────────────────────────────────────────────

function mapSessionRow(r: Row): MigrationSession {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    sourceSystem: r.source_system ?? null,
    status: r.status as MigrationStatus,
