// ── Source system → step → alias map ────────────────────────────────────────

type AliasMap = Record<string, Record<string, Record<string, string>>>;

const ALIAS_MAP: AliasMap = {
  sage_cloud: {
    'chart-of-accounts': SAGE_CLOUD_COA_ALIASES,
