  'customers': {
    default: CUSTOMERS_TEMPLATE,
  },
  'suppliers': {
    default: SUPPLIERS_TEMPLATE,
  },
  'opening-balances': {
    default: OPENING_BALANCES_TEMPLATE,
  },
