import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  CheckCircle2, AlertCircle, Loader2, Circle,
  BookOpen, Users, Truck, Scale, FileText, ClipboardList, ShieldCheck,
  Building2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface StepsCompleted {
  coa?: boolean;
  customers?: boolean;
  suppliers?: boolean;
  opening_balances?: boolean;
  ar_invoices?: boolean;
  ap_invoices?: boolean;
  validated?: boolean;
}

interface MigrationSession {
  id: string;
  sourceSystem: string | null;
  status: string;
  stepsCompleted: StepsCompleted;
  coaRecordsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: boolean;
  arInvoicesImported: number;
  apInvoicesImported: number;
  startedAt: string;
}

const SOURCE_SYSTEMS = [
  { id: 'sage_cloud', label: 'Sage Business Cloud', icon: '☁️', desc: '3-digit account codes' },
  { id: 'sage_50', label: 'Sage 50 / Pastel', icon: '📊', desc: '7-digit account codes' },
  { id: 'xero', label: 'Xero', icon: '✕', desc: 'Flexible code format' },
  { id: 'quickbooks', label: 'QuickBooks Online', icon: '🔵', desc: 'Account type driven' },
  { id: 'wave', label: 'Wave / FreshBooks', icon: '🌊', desc: 'Simple CSV export' },
  { id: 'other', label: 'Other / Manual CSV', icon: '📁', desc: 'Generic CSV format' },
];

interface WizardStep {
  id: keyof StepsCompleted;
  label: string;
  href: string;
  icon: React.ReactNode;
  desc: string;
}

const STEPS: WizardStep[] = [
  { id: 'coa', label: 'Chart of Accounts', href: '/accounting/migration/chart-of-accounts', icon: <BookOpen className="h-5 w-5" />, desc: 'Import your accounts structure' },
  { id: 'customers', label: 'Customers', href: '/accounting/migration/customers', icon: <Users className="h-5 w-5" />, desc: 'Import customer records' },
  { id: 'suppliers', label: 'Suppliers', href: '/accounting/migration/suppliers', icon: <Truck className="h-5 w-5" />, desc: 'Import supplier records' },
  { id: 'opening_balances', label: 'Opening Balances', href: '/accounting/migration/opening-balances', icon: <Scale className="h-5 w-5" />, desc: 'Set trial balance' },
  { id: 'ar_invoices', label: 'Outstanding AR Invoices', href: '/accounting/migration/ar-invoices', icon: <FileText className="h-5 w-5" />, desc: 'Unpaid customer invoices' },
  { id: 'ap_invoices', label: 'Outstanding AP Invoices', href: '/accounting/migration/ap-invoices', icon: <ClipboardList className="h-5 w-5" />, desc: 'Unpaid supplier invoices' },
  { id: 'validated', label: 'Validation & Go-Live', href: '/accounting/migration/validate', icon: <ShieldCheck className="h-5 w-5" />, desc: 'Verify and complete migration' },
];

export default function MigrationHubPage() {
  const [session, setSession] = useState<MigrationSession | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');
  const [selecting, setSelecting] = useState(false);

  const loadSession = useCallback(async () => {
    try {
      const res = await apiFetch('/api/accounting/migration/session');
      const json = await res.json();
      if (res.ok && json.data) {
        setSession(json.data);
      }
    } catch {
      // No session yet — show source selection
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadSession(); }, [loadSession]);

  const selectSource = async (sourceSystem: string) => {
    setSelecting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/migration/session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sourceSystem }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to create session');
      setSession(json.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start migration');
    } finally {
      setSelecting(false);
    }
  };

  const stepStatus = (id: keyof StepsCompleted): 'completed' | 'not_started' => {
    if (!session) return 'not_started';
    return session.stepsCompleted[id] ? 'completed' : 'not_started';
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10">
                <Building2 className="h-6 w-6 text-blue-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Migration Wizard</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">Migrate your data from any accounting system to ISAFlow</p>
              </div>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-4xl space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {isLoading ? (
            <div className="flex items-center justify-center py-16">
              <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
            </div>
          ) : !session ? (
            <SourceSelection onSelect={selectSource} selecting={selecting} />
          ) : (
            <div className="space-y-6">
              <SessionSummary session={session} onReset={() => setSession(null)} />
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
                <div className="px-5 py-4 border-b border-[var(--ff-border-light)]">
                  <h2 className="font-semibold text-[var(--ff-text-primary)]">Migration Steps</h2>
                  <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">Complete each step in order for best results</p>
                </div>
                <div className="divide-y divide-[var(--ff-border-light)]">
                  {STEPS.map((step, i) => {
                    const status = stepStatus(step.id);
                    return (
                      <Link
                        key={step.id}
                        href={step.href}
                        className="flex items-center gap-4 px-5 py-4 hover:bg-[var(--ff-bg-primary)] transition-colors"
                      >
                        <div className="flex items-center justify-center w-8 h-8 rounded-full bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] text-sm font-bold shrink-0">
                          {status === 'completed'
                            ? <CheckCircle2 className="h-5 w-5 text-teal-400" />
                            : <span className="text-xs">{i + 1}</span>
                          }
                        </div>
                        <div className="text-[var(--ff-text-secondary)] shrink-0">{step.icon}</div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-[var(--ff-text-primary)]">{step.label}</p>
                          <p className="text-xs text-[var(--ff-text-secondary)]">{step.desc}</p>
                        </div>
                        <StepBadge status={status} />
                      </Link>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

function SourceSelection({ onSelect, selecting }: { onSelect: (s: string) => void; selecting: boolean }) {
  return (
    <div className="space-y-4">
      <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
        <h2 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-1">Step 1: Choose Your Source System</h2>
        <p className="text-sm text-[var(--ff-text-secondary)] mb-5">Select the accounting software you are migrating from.</p>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {SOURCE_SYSTEMS.map(sys => (
            <button
              key={sys.id}
              onClick={() => onSelect(sys.id)}
              disabled={selecting}
              className="flex flex-col gap-1 p-4 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] hover:border-blue-500 hover:bg-blue-500/5 transition-colors text-left disabled:opacity-50"
            >
              <span className="text-2xl">{sys.icon}</span>
              <span className="text-sm font-medium text-[var(--ff-text-primary)]">{sys.label}</span>
              <span className="text-xs text-[var(--ff-text-secondary)]">{sys.desc}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

function SessionSummary({ session, onReset }: { session: MigrationSession; onReset: () => void }) {
  const sourceLabel = SOURCE_SYSTEMS.find(s => s.id === session.sourceSystem)?.label ?? session.sourceSystem ?? 'Unknown';
  const completed = Object.values(session.stepsCompleted).filter(Boolean).length;
  return (
    <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-5">
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-xs text-[var(--ff-text-tertiary)] uppercase tracking-wide mb-1">Active Migration</p>
          <p className="font-semibold text-[var(--ff-text-primary)]">From: {sourceLabel}</p>
          <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
            {completed}/{STEPS.length} steps completed &bull; Started {new Date(session.startedAt).toLocaleDateString('en-ZA')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <StatusBadge status={session.status} />
          {session.status !== 'completed' && (
            <button
              onClick={onReset}
              className="text-xs text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] underline"
            >
              Start over
            </button>
          )}
        </div>
      </div>
      <div className="mt-4 h-2 rounded-full bg-[var(--ff-bg-primary)] overflow-hidden">
        <div
          className="h-full rounded-full bg-blue-500 transition-all"
          style={{ width: `${(completed / STEPS.length) * 100}%` }}
        />
      </div>
    </div>
  );
}

function StepBadge({ status }: { status: 'completed' | 'not_started' }) {
  if (status === 'completed') {
    return <span className="px-2 py-0.5 rounded text-xs font-medium bg-teal-500/20 text-teal-400">Completed</span>;
  }
  return <span className="px-2 py-0.5 rounded text-xs font-medium bg-gray-500/20 text-gray-400">Not started</span>;
}

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    in_progress: 'bg-blue-500/20 text-blue-400',
    completed: 'bg-teal-500/20 text-teal-400',
    abandoned: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`px-2 py-0.5 rounded text-xs font-medium ${colors[status] ?? 'bg-gray-500/20 text-gray-400'}`}>
      {status.replace('_', ' ')}
    </span>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Upload, Download, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import Papa from 'papaparse';

const COA_FIELDS = ['account_code', 'account_name', 'account_type', 'normal_balance', 'parent_code', 'description'] as const;
type CoaField = typeof COA_FIELDS[number];

const SYSTEM_ACCOUNT_ROLES = [
  { key: 'bank', label: 'Primary Bank Account' },
  { key: 'receivable', label: 'Accounts Receivable' },
  { key: 'payable', label: 'Accounts Payable' },
  { key: 'vat_input', label: 'VAT Input (Claimable)' },
  { key: 'vat_output', label: 'VAT Output (Payable)' },
  { key: 'retained_earnings', label: 'Retained Earnings' },
  { key: 'default_revenue', label: 'Default Revenue' },
  { key: 'default_expense', label: 'Default Expense' },
  { key: 'admin_expense', label: 'Admin / General Expense' },
] as const;

type SystemAccountRole = typeof SYSTEM_ACCOUNT_ROLES[number]['key'];

const AUTO_DETECT_PATTERNS: Record<SystemAccountRole, string[]> = { bank: ['bank', 'cheque', 'current account', 'fnb', 'absa', 'nedbank', 'standard bank', 'capitec'], receivable: ['receivable', 'debtors', 'trade debtors'], payable: ['payable', 'creditors', 'trade creditors'], vat_input: ['vat input', 'input tax', 'vat claimable'], vat_output: ['vat output', 'output tax', 'vat payable'], retained_earnings: ['retained earnings', 'retained profit'], default_revenue: ['sales revenue', 'revenue', 'income', 'turnover'], default_expense: ['cost of sales', 'cost of goods', 'materials'], admin_expense: ['admin', 'general expenses', 'administration'] };

interface ParsedRow {
  raw: Record<string, string>;
  mapped: Partial<Record<CoaField, string>>;
}

type FieldMapping = Partial<Record<CoaField, string>>;
type SystemAccountMap = Partial<Record<SystemAccountRole, string>>;

export default function ChartOfAccountsPage() {
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [sourceSystem, setSourceSystem] = useState<string>('other');
  const [columns, setColumns] = useState<string[]>([]);
  const [rows, setRows] = useState<ParsedRow[]>([]);
  const [fieldMapping, setFieldMapping] = useState<FieldMapping>({});
  const [systemMap, setSystemMap] = useState<SystemAccountMap>({});
  const [isImporting, setIsImporting] = useState(false);
  const [importResult, setImportResult] = useState<{ succeeded: number; failed: number } | null>(null);
  const [error, setError] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    apiFetch('/api/accounting/migration/session').then(async res => {
      if (!res.ok) return;
      const json = await res.json();
      if (json.data) {
        setSessionId(json.data.id);
        setSourceSystem(json.data.sourceSystem ?? 'other');
      }
    }).catch(() => {});
  }, []);

  const applyAutoDetect = useCallback((parsedRows: ParsedRow[], mapping: FieldMapping) => {
    const nameField = mapping.account_name;
    if (!nameField) return;
    const detected: SystemAccountMap = {};
    for (const { key } of SYSTEM_ACCOUNT_ROLES) {
      const patterns = AUTO_DETECT_PATTERNS[key as SystemAccountRole];
      const match = parsedRows.find(r => {
        const name = (r.raw[nameField] ?? '').toLowerCase();
        return patterns.some(p => name.includes(p));
      });
      if (match) {
        const codeField = mapping.account_code;
        detected[key as SystemAccountRole] = codeField ? (match.raw[codeField] ?? '') : '';
      }
    }
    setSystemMap(detected);
  }, []);

  const handleFile = (file: File) => {
    setError('');
    setImportResult(null);
    Papa.parse<Record<string, string>>(file, {
      header: true,
      skipEmptyLines: true,
      complete: ({ data, meta }) => {
        const cols = meta.fields ?? [];
        setColumns(cols);
        const autoMapping: FieldMapping = {};
        for (const field of COA_FIELDS) {
          const match = cols.find(c => c.toLowerCase().replace(/[\s_-]/g, '') === field.replace(/_/g, ''));
          if (match) autoMapping[field] = match;
        }
        setFieldMapping(autoMapping);
        const parsed: ParsedRow[] = data.map(raw => ({
          raw,
          mapped: Object.fromEntries(
            COA_FIELDS.filter(f => autoMapping[f]).map(f => [f, raw[autoMapping[f]!] ?? ''])
          ) as Partial<Record<CoaField, string>>,
        }));
        setRows(parsed);
        applyAutoDetect(parsed, autoMapping);
      },
      error: err => setError(`CSV parse error: ${err.message}`),
    });
  };

  const onFieldMapChange = (field: CoaField, col: string) => {
    const updated = { ...fieldMapping, [field]: col };
    setFieldMapping(updated);
    const reMapped: ParsedRow[] = rows.map(r => ({
      ...r,
      mapped: Object.fromEntries(
        COA_FIELDS.filter(f => updated[f]).map(f => [f, r.raw[updated[f]!] ?? ''])
      ) as Partial<Record<CoaField, string>>,
    }));
    setRows(reMapped);
    applyAutoDetect(reMapped, updated);
  };

  const handleImport = async () => {
    if (!sessionId) { setError('No active migration session'); return; }
    setIsImporting(true);
    setError('');
    try {
      const accounts = rows.map(r => ({
        accountCode: r.mapped.account_code ?? '',
        accountName: r.mapped.account_name ?? '',
        accountType: r.mapped.account_type ?? '',
        normalBalance: r.mapped.normal_balance ?? 'debit',
        parentCode: r.mapped.parent_code,
        description: r.mapped.description,
      }));
      const res = await apiFetch('/api/accounting/migration/chart-of-accounts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId, accounts, systemAccountMap: systemMap }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Import failed');
      setImportResult(json.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setIsImporting(false);
    }
  };

  const downloadTemplate = async () => {
    const res = await apiFetch(`/api/accounting/migration/templates?sourceSystem=${sourceSystem}&step=chart-of-accounts`);
    if (!res.ok) return;
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `coa-template-${sourceSystem}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <AppLayout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <Link href="/accounting/migration" className="flex items-center gap-2 text-blue-600 hover:text-blue-800 mb-6 text-sm">
          <ArrowLeft className="h-4 w-4" /> Back to Migration Hub
        </Link>
        <h1 className="text-2xl font-bold text-[var(--ff-text-primary)] mb-2">Chart of Accounts Import</h1>
        <p className="text-sm text-[var(--ff-text-secondary)] mb-6">Upload your existing chart of accounts as a CSV file.</p>

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
            <AlertCircle className="h-4 w-4" /> {error}
          </div>
        )}

        {importResult && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm mb-4">
            <CheckCircle2 className="h-4 w-4" />
            Imported {importResult.succeeded} accounts{importResult.failed > 0 ? `, ${importResult.failed} failed` : ''}.
          </div>
        )}

        <div className="space-y-6">
          {/* Download template */}
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">1. Download Template</h2>
            <button onClick={downloadTemplate} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm">
              <Download className="h-4 w-4" /> Download CSV Template
            </button>
          </div>

          {/* Upload */}
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">2. Upload Your CSV</h2>
            <input ref={fileRef} type="file" accept=".csv" className="hidden" onChange={e => { if (e.target.files?.[0]) handleFile(e.target.files[0]); }} />
            <button
              onClick={() => fileRef.current?.click()}
              className="flex items-center gap-2 px-4 py-2 border-2 border-dashed border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:border-blue-500 hover:text-blue-500 text-sm transition-colors"
            >
              <Upload className="h-4 w-4" /> Choose CSV file
            </button>
            {rows.length > 0 && <p className="text-xs text-[var(--ff-text-secondary)] mt-2">{rows.length} rows parsed</p>}
          </div>

          {/* Field mapping */}
          {columns.length > 0 && (
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
              <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">3. Map Columns</h2>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                {COA_FIELDS.map(field => (
                  <div key={field}>
                    <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">{field}</label>
                    <select
                      value={fieldMapping[field] ?? ''}
                      onChange={e => onFieldMapChange(field, e.target.value)}
                      className="w-full text-sm border border-[var(--ff-border-light)] rounded px-2 py-1.5 bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)]"
                    >
                      <option value="">-- skip --</option>
                      {columns.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Preview table */}
          {rows.length > 0 && (
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
              <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">4. Preview ({rows.length} rows)</h2>
              <div className="overflow-x-auto">
                <table className="min-w-full text-xs divide-y divide-gray-200 dark:divide-gray-700">
                  <thead>
                    <tr className="bg-[var(--ff-bg-primary)]">
                      {COA_FIELDS.filter(f => fieldMapping[f]).map(f => (
                        <th key={f} className="px-3 py-2 text-left text-[var(--ff-text-secondary)] font-medium">{f}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                    {rows.slice(0, 10).map((r, i) => (
                      <tr key={i}>
                        {COA_FIELDS.filter(f => fieldMapping[f]).map(f => (
                          <td key={f} className="px-3 py-1.5 text-[var(--ff-text-primary)]">{r.mapped[f] ?? ''}</td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {rows.length > 10 && <p className="text-xs text-[var(--ff-text-tertiary)] mt-2">... and {rows.length - 10} more rows</p>}
            </div>
          )}

          {/* System account mapping */}
          {rows.length > 0 && (
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
              <h2 className="font-semibold text-[var(--ff-text-primary)] mb-1">5. Map System Accounts</h2>
              <p className="text-xs text-[var(--ff-text-secondary)] mb-4">ISAFlow needs to know which accounts serve these system roles.</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {SYSTEM_ACCOUNT_ROLES.map(({ key, label }) => (
                  <div key={key}>
                    <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">{label}</label>
                    <select
                      value={systemMap[key as SystemAccountRole] ?? ''}
                      onChange={e => setSystemMap(prev => ({ ...prev, [key]: e.target.value }))}
                      className="w-full text-sm border border-[var(--ff-border-light)] rounded px-2 py-1.5 bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)]"
                    >
                      <option value="">-- select --</option>
                      {rows.map((r, i) => {
                        const code = fieldMapping.account_code ? r.raw[fieldMapping.account_code] ?? '' : '';
