          <ArrowLeft className="h-4 w-4" /> Back to Migration Hub
        </Link>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 rounded-lg bg-teal-500/10">
            <ShieldCheck className="h-6 w-6 text-teal-500" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Validation & Go-Live</h1>
            <p className="text-sm text-[var(--ff-text-secondary)]">Verify your migration data before activating ISAFlow</p>
          </div>
        </div>

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
            <AlertCircle className="h-4 w-4" /> {error}
          </div>
        )}

        {completed ? (
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-8 text-center">
            <PartyPopper className="h-12 w-12 text-teal-400 mx-auto mb-4" />
            <h2 className="text-xl font-bold text-[var(--ff-text-primary)] mb-2">Migration Complete!</h2>
            <p className="text-[var(--ff-text-secondary)] mb-6">Your data has been successfully migrated to ISAFlow.</p>
            <div className="flex justify-center gap-3">
              <Link href="/accounting" className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm">
                Go to Dashboard
              </Link>
              <Link href="/accounting/chart-of-accounts" className="px-4 py-2 border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] rounded-lg hover:bg-[var(--ff-bg-primary)] text-sm">
                View Chart of Accounts
              </Link>
            </div>
          </div>
        ) : isLoading ? (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
            <span className="ml-2 text-[var(--ff-text-secondary)]">Running validation checks...</span>
          </div>
        ) : validation ? (
          <div className="space-y-4">
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow overflow-hidden">
              <div className="px-5 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
                <h2 className="font-semibold text-[var(--ff-text-primary)]">Validation Checks</h2>
                <button
                  onClick={() => sessionId && runValidation(sessionId)}
                  className="text-xs text-blue-500 hover:text-blue-400"
                >
                  Re-run
                </button>
              </div>
              <div className="divide-y divide-[var(--ff-border-light)]">
                {validation.checks.map(check => (
                  <div key={check.id} className="flex items-start gap-3 px-5 py-4">
                    {check.passed
                      ? <CheckCircle2 className="h-5 w-5 text-teal-400 mt-0.5 shrink-0" />
                      : <AlertCircle className="h-5 w-5 text-red-400 mt-0.5 shrink-0" />
                    }
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium text-[var(--ff-text-primary)]">{check.label}</p>
                      {check.detail && <p className="text-xs text-[var(--ff-text-secondary)] mt-0.5">{check.detail}</p>}
                    </div>
                    <span className={`px-2 py-0.5 rounded text-xs font-medium ${check.passed ? 'bg-teal-500/20 text-teal-400' : 'bg-red-500/20 text-red-400'}`}>
                      {check.passed ? 'Pass' : 'Fail'}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {!validation.allPassed && (
              <div className="p-4 rounded-lg bg-amber-500/10 border border-amber-500/20 text-sm text-amber-400">
                <p className="font-medium mb-1">Some checks failed</p>
                <p>Please resolve the issues above before completing your migration. Return to the relevant steps to fix them.</p>
              </div>
            )}

            <div className="flex justify-end">
              <button
                onClick={completeMigration}
                disabled={isCompleting || !validation.allPassed}
                className="flex items-center gap-2 px-6 py-2.5 bg-teal-600 text-white rounded-lg hover:bg-teal-500 disabled:opacity-50 font-medium"
              >
                {isCompleting ? <Loader2 className="h-4 w-4 animate-spin" /> : <ShieldCheck className="h-4 w-4" />}
                Complete Migration
              </button>
            </div>
          </div>
        ) : null}
      </div>
    </AppLayout>
  );
}

import { useState, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Upload, Download, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import Papa from 'papaparse';

const AP_FIELDS = [
  'invoice_number', 'supplier_name', 'invoice_date', 'due_date',
  'subtotal', 'tax_amount', 'total_amount', 'amount_paid', 'reference',
] as const;
type ApField = typeof AP_FIELDS[number];

type FieldMapping = Partial<Record<ApField, string>>;
type MatchConfidence = 'HIGH' | 'MEDIUM' | 'LOW' | 'NONE';

interface ParsedInvoice {
  raw: Record<string, string>;
  mapped: Partial<Record<ApField, string>>;
  matchedSupplierId?: string;
  matchConfidence: MatchConfidence;
  overrideSupplierId?: string;
}

interface SupplierOption {
  id: string;
  name: string;
}

interface ImportResult {
  succeeded: number;
  failed: number;
}

export default function ApInvoicesPage() {
  const [columns, setColumns] = useState<string[]>([]);
  const [rows, setRows] = useState<ParsedInvoice[]>([]);
  const [fieldMapping, setFieldMapping] = useState<FieldMapping>({});
  const [suppliers, setSuppliers] = useState<SupplierOption[]>([]);
  const [isImporting, setIsImporting] = useState(false);
  const [importResult, setImportResult] = useState<ImportResult | null>(null);
  const [error, setError] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);

  const loadSuppliers = async () => {
    try {
      const res = await apiFetch('/api/accounting/suppliers?limit=500');
      const json = await res.json();
      const list: SupplierOption[] = (json.data ?? json.suppliers ?? []).map((s: { id: string; name: string }) => ({ id: s.id, name: s.name }));
      setSuppliers(list);
    } catch {
      // Non-fatal
    }
  };

  const fuzzyMatch = (name: string, list: SupplierOption[]): { id?: string; confidence: MatchConfidence } => {
    const n = name.toLowerCase().trim();
    const exact = list.find(s => s.name.toLowerCase().trim() === n);
    if (exact) return { id: exact.id, confidence: 'HIGH' };
    const partial = list.find(s => s.name.toLowerCase().includes(n) || n.includes(s.name.toLowerCase()));
    if (partial) return { id: partial.id, confidence: 'MEDIUM' };
    return { confidence: 'NONE' };
  };

  const handleFile = async (file: File) => {
    setError('');
    setImportResult(null);
    if (suppliers.length === 0) await loadSuppliers();
    Papa.parse<Record<string, string>>(file, {
      header: true,
      skipEmptyLines: true,
      complete: ({ data, meta }) => {
        const cols = meta.fields ?? [];
        setColumns(cols);
        const autoMapping: FieldMapping = {};
        for (const field of AP_FIELDS) {
          const match = cols.find(c => c.toLowerCase().replace(/[\s_-]/g, '') === field.replace(/_/g, ''));
          if (match) autoMapping[field] = match;
        }
        setFieldMapping(autoMapping);
        setRows(data.map(raw => {
          const mapped = Object.fromEntries(
            AP_FIELDS.filter(f => autoMapping[f]).map(f => [f, raw[autoMapping[f]!] ?? ''])
          ) as Partial<Record<ApField, string>>;
          const suppName = mapped.supplier_name ?? '';
          const { id, confidence } = fuzzyMatch(suppName, suppliers);
          return { raw, mapped, matchedSupplierId: id, matchConfidence: confidence };
        }));
      },
      error: err => setError(`CSV parse error: ${err.message}`),
    });
  };

  const onFieldMapChange = (field: ApField, col: string) => {
    const updated = { ...fieldMapping, [field]: col };
    setFieldMapping(updated);
    setRows(prev => prev.map(r => ({
      ...r,
      mapped: Object.fromEntries(
        AP_FIELDS.filter(f => updated[f]).map(f => [f, r.raw[updated[f]!] ?? ''])
      ) as Partial<Record<ApField, string>>,
    })));
  };

  const setOverride = (i: number, supplierId: string) => {
    setRows(prev => prev.map((r, idx) => idx === i ? { ...r, overrideSupplierId: supplierId } : r));
  };

  const handleImport = async () => {
    setIsImporting(true);
    setError('');
    try {
      const sessionRes = await apiFetch('/api/accounting/migration/session');
      const sessionJson = await sessionRes.json();
      const sessionId = sessionJson.data?.id;
      if (!sessionId) throw new Error('No active migration session');

      const invoices = rows.map(r => ({
        invoiceNumber: r.mapped.invoice_number ?? '',
        supplierId: r.overrideSupplierId ?? r.matchedSupplierId ?? '',
        supplierName: r.mapped.supplier_name ?? '',
        invoiceDate: r.mapped.invoice_date ?? '',
        dueDate: r.mapped.due_date ?? '',
        subtotal: parseFloat(r.mapped.subtotal ?? '0') || 0,
        taxAmount: parseFloat(r.mapped.tax_amount ?? '0') || 0,
        totalAmount: parseFloat(r.mapped.total_amount ?? '0') || 0,
        amountPaid: parseFloat(r.mapped.amount_paid ?? '0') || 0,
        reference: r.mapped.reference,
      }));

      const res = await apiFetch('/api/accounting/migration/ap-invoices', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId, invoices }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Import failed');
      setImportResult(json.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setIsImporting(false);
    }
  };

  const downloadTemplate = async () => {
    const res = await apiFetch('/api/accounting/migration/templates?step=ap-invoices');
    if (!res.ok) return;
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'ap-invoices-template.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const confidenceColor = (c: MatchConfidence) => ({
    HIGH: 'bg-teal-500/20 text-teal-400',
    MEDIUM: 'bg-amber-500/20 text-amber-400',
    LOW: 'bg-orange-500/20 text-orange-400',
    NONE: 'bg-red-500/20 text-red-400',
  }[c]);

  const visibleFields = AP_FIELDS.filter(f => fieldMapping[f]);

  return (
    <AppLayout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <Link href="/accounting/migration" className="flex items-center gap-2 text-blue-600 hover:text-blue-800 mb-6 text-sm">
          <ArrowLeft className="h-4 w-4" /> Back to Migration Hub
        </Link>
        <h1 className="text-2xl font-bold text-[var(--ff-text-primary)] mb-2">Outstanding AP Invoices</h1>
        <p className="text-sm text-[var(--ff-text-secondary)] mb-6">Import outstanding supplier invoices from a CSV file.</p>

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
            <AlertCircle className="h-4 w-4" /> {error}
          </div>
        )}
        {importResult && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm mb-4">
            <CheckCircle2 className="h-4 w-4" />
            Imported {importResult.succeeded} invoices. Failed: {importResult.failed}.
          </div>
        )}

        <div className="space-y-6">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">1. Download Template</h2>
            <button onClick={downloadTemplate} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm">
              <Download className="h-4 w-4" /> Download CSV Template
            </button>
          </div>

          <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
            <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">2. Upload Your CSV</h2>
            <input ref={fileRef} type="file" accept=".csv" className="hidden" onChange={e => { if (e.target.files?.[0]) handleFile(e.target.files[0]); }} />
            <button
              onClick={() => fileRef.current?.click()}
              className="flex items-center gap-2 px-4 py-2 border-2 border-dashed border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-secondary)] hover:border-blue-500 hover:text-blue-500 text-sm transition-colors"
            >
              <Upload className="h-4 w-4" /> Choose CSV file
            </button>
            {rows.length > 0 && <p className="text-xs text-[var(--ff-text-secondary)] mt-2">{rows.length} rows parsed</p>}
          </div>

          {columns.length > 0 && (
            <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
              <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">3. Map Columns</h2>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                {AP_FIELDS.map(field => (
                  <div key={field}>
                    <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">{field}</label>
                    <select
                      value={fieldMapping[field] ?? ''}
                      onChange={e => onFieldMapChange(field, e.target.value)}
                      className="w-full text-sm border border-[var(--ff-border-light)] rounded px-2 py-1.5 bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)]"
                    >
                      <option value="">-- skip --</option>
                      {columns.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                ))}
              </div>
            </div>
          )}

          {rows.length > 0 && (
            <>
              <div className="bg-white dark:bg-gray-800 rounded-lg shadow p-6">
                <h2 className="font-semibold text-[var(--ff-text-primary)] mb-3">4. Supplier Matching Preview</h2>
                <div className="overflow-x-auto">
                  <table className="min-w-full text-xs divide-y divide-gray-200 dark:divide-gray-700">
                    <thead>
                      <tr className="bg-[var(--ff-bg-primary)]">
                        <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)] font-medium">Invoice #</th>
                        <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)] font-medium">Supplier Name</th>
                        <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)] font-medium">Match</th>
                        <th className="px-3 py-2 text-right text-[var(--ff-text-secondary)] font-medium">Total</th>
                        <th className="px-3 py-2 text-left text-[var(--ff-text-secondary)] font-medium">Override</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                      {rows.slice(0, 15).map((r, i) => (
                        <tr key={i}>
                          <td className="px-3 py-1.5 font-mono text-[var(--ff-text-primary)]">{r.mapped.invoice_number ?? ''}</td>
                          <td className="px-3 py-1.5 text-[var(--ff-text-primary)]">{r.mapped.supplier_name ?? ''}</td>
                          <td className="px-3 py-1.5">
                            <span className={`px-1.5 py-0.5 rounded text-xs font-medium ${confidenceColor(r.matchConfidence)}`}>
                              {r.matchConfidence}
                            </span>
                          </td>
                          <td className="px-3 py-1.5 text-right text-[var(--ff-text-primary)]">{r.mapped.total_amount ?? ''}</td>
                          <td className="px-3 py-1.5">
                            {r.matchConfidence !== 'HIGH' && (
                              <select
                                value={r.overrideSupplierId ?? ''}
                                onChange={e => setOverride(i, e.target.value)}
                                className="text-xs border border-[var(--ff-border-light)] rounded px-1.5 py-1 bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)]"
                              >
                                <option value="">-- select --</option>
                                {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                              </select>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              <div className="flex justify-end">
                <button
                  onClick={handleImport}
                  disabled={isImporting}
                  className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                >
                  {isImporting ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                  Import {rows.length} Invoices
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

