    'ap-invoices':        GENERIC_AP_ALIASES,
  },
  xero: {
    'chart-of-accounts': XERO_COA_ALIASES,
    customers:            GENERIC_CUSTOMER_ALIASES,
    suppliers:            GENERIC_SUPPLIER_ALIASES,
    'opening-balances':   GENERIC_OB_ALIASES,
