/**
 * Auto-map CSV column headers to ISAFlow field names.
 *
 * @param headers     Array of raw header strings from the CSV
 * @param sourceSystem Source system key (e.g. 'sage_cloud', 'xero')
 * @param step        Wizard step key (e.g. 'chart-of-accounts', 'customers')
 * @returns           Record<csvHeader, isafieldName> for matched columns.
 *                    Unrecognized headers are returned as-is (identity mapping).
 */
export function autoMapFields(
  headers: string[],
  sourceSystem: string,
  step: string,
): Record<string, string> {
  const aliases =
    ALIAS_MAP[sourceSystem]?.[step] ??
    ALIAS_MAP['other']?.[step] ??
    {};

  const result: Record<string, string> = {};

  for (const header of headers) {
    const normalized = normalizeHeader(header);
    const mapped = aliases[normalized];
    result[header] = mapped ?? header;
  }

  return result;
}

function normalizeHeader(header: string): string {
  return header
    .toLowerCase()
    .replace(/[\s_\-.]+/g, '')    // strip spaces, underscores, dashes, dots
    .replace(/[^a-z0-9]/g, '');   // strip remaining non-alphanumeric
}

/**
 * Fuzzy Matcher Utility
 * PRD: Customer Migration Wizard — Phase 1
 *
 * Generic fuzzy matching for migration contact name resolution.
 * Complements fuzzyMatch.ts (which is supplier/client specific) with a
 * simpler needle-in-haystack API used by migration services.
 *
 * Uses Levenshtein edit distance normalized to [0, 1] similarity score,
 * with a Dice bigram coefficient fallback for longer strings (>6 chars).
 */

export interface FuzzyMatchResult {
  match: string;
  score: number;  // 0.0 – 1.0, higher is better
}

const DEFAULT_THRESHOLD = 0.7;

/**
 * Find the best fuzzy match for needle in a haystack of strings.
 *
 * @param needle    String to search for
 * @param haystack  Candidate strings
 * @param threshold Minimum score to accept (default 0.7)
 * @returns Best match with score, or null if nothing meets the threshold
 */
export function fuzzyMatch(
  needle: string,
  haystack: string[],
  threshold = DEFAULT_THRESHOLD,
): FuzzyMatchResult | null {
  if (!needle || haystack.length === 0) return null;

  const normalizedNeedle = normalize(needle);
  if (!normalizedNeedle) return null;

  let best: FuzzyMatchResult | null = null;

  for (const candidate of haystack) {
    const normalizedCandidate = normalize(candidate);
    if (!normalizedCandidate) continue;

    // Exact match shortcut
    if (normalizedNeedle === normalizedCandidate) {
      return { match: candidate, score: 1.0 };
    }

    const score = scoreStrings(normalizedNeedle, normalizedCandidate);
    if (score >= threshold && (!best || score > best.score)) {
      best = { match: candidate, score: Math.round(score * 1000) / 1000 };
    }
  }

  return best;
}

/**
 * Score all haystack items against needle, returning sorted results.
 * Useful for showing ranked match suggestions in the UI.
 */
export function fuzzyRank(
  needle: string,
  haystack: string[],
  threshold = 0.5,
): FuzzyMatchResult[] {
  if (!needle || haystack.length === 0) return [];

  const normalizedNeedle = normalize(needle);
  if (!normalizedNeedle) return [];

  const results: FuzzyMatchResult[] = [];

  for (const candidate of haystack) {
    const normalizedCandidate = normalize(candidate);
    if (!normalizedCandidate) continue;
    const score = normalizedNeedle === normalizedCandidate ? 1.0 : scoreStrings(normalizedNeedle, normalizedCandidate);
    if (score >= threshold) {
      results.push({ match: candidate, score: Math.round(score * 1000) / 1000 });
    }
  }

  return results.sort((a, b) => b.score - a.score);
}

// ── Scoring ──────────────────────────────────────────────────────────────────

function scoreStrings(a: string, b: string): number {
  // For short strings (<= 6 chars), Levenshtein is more accurate
  if (a.length <= 6 || b.length <= 6) {
    return levenshteinSimilarity(a, b);
  }
  // For longer strings, average Dice + Levenshtein
  const dice = diceCoefficient(a, b);
  const lev  = levenshteinSimilarity(a, b);
  return (dice + lev) / 2;
}

function levenshteinSimilarity(a: string, b: string): number {
  const dist = levenshtein(a, b);
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1.0;
  return 1 - dist / maxLen;
}

function levenshtein(a: string, b: string): number {
  const m = a.length;
  const n = b.length;
  const dp: number[][] = Array.from({ length: m + 1 }, (_, i) =>
    Array.from({ length: n + 1 }, (__, j) => (i === 0 ? j : j === 0 ? i : 0))
  );
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i]![j] = dp[i - 1]![j - 1]!;
      } else {
        dp[i]![j] = 1 + Math.min(dp[i - 1]![j]!, dp[i]![j - 1]!, dp[i - 1]![j - 1]!);
      }
    }
  }
  return dp[m]![n]!;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const bigramsA = new Set<string>();
  const bigramsB = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) bigramsA.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bigramsB.add(b.substring(i, i + 2));
  let intersection = 0;
  for (const bg of bigramsA) { if (bigramsB.has(bg)) intersection++; }
  return (2 * intersection) / (bigramsA.size + bigramsB.size);
}

// ── Normalization ─────────────────────────────────────────────────────────────

const STRIP_PATTERNS = [
  /\b\(pty\)\b/gi,
  /\bpty\b/gi,
  /\bltd\b/gi,
  /\blimited\b/gi,
  /\binc\b/gi,
  /\bcc\b/gi,
  /\bnpc\b/gi,
  /\bt\/a\b/gi,
];

function normalize(name: string): string {
  let s = name.toLowerCase().trim();
  for (const pattern of STRIP_PATTERNS) {
    s = s.replace(pattern, '');
  }
  return s.replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
}

/**
 * Migration COA Service — Chart of Accounts import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { clearSystemAccountCache } from './systemAccountResolver';
import { updateSession } from './migrationService';
import type { ImportResult, MigrationError } from './migrationService';
import type { GLAccountType } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface AccountImportRow {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentCode?: string;
  normalBalance: 'debit' | 'credit';
  description?: string;
}

export interface SystemAccountMap {
  bank: string;
  receivable: string;
  payable: string;
  vat_input: string;
  vat_output: string;
  retained_earnings: string;
  default_revenue: string;
  default_expense: string;
  admin_expense: string;
}

// ── Public API ───────────────────────────────────────────────────────────────

export async function importChartOfAccounts(
  companyId: string,
  sessionId: string,
  accounts: AccountImportRow[],
  systemAccountMap: SystemAccountMap,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  // Sort: accounts without parents first, then those with parents (preserves hierarchy)
  const sorted = [...accounts.filter(a => !a.parentCode), ...accounts.filter(a => a.parentCode)];

  for (let i = 0; i < sorted.length; i++) {
    const acct = sorted[i]!;
    try {
      let parentAccountId: string | null = null;
      if (acct.parentCode) {
        const parentRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE account_code = ${acct.parentCode} AND company_id = ${companyId}::UUID
        `) as Row[];
        if (parentRows.length === 0) {
          errors.push({ step: 'coa', row: i, field: 'parentCode', message: `Parent code ${acct.parentCode} not found` });
          skipped++;
          continue;
        }
        parentAccountId = String(parentRows[0].id);
      }

      const subtypeEntry = Object.entries(systemAccountMap).find(([, code]) => code === acct.accountCode);
      const accountSubtype = subtypeEntry ? subtypeEntry[0] : (acct.accountSubtype ?? null);
      const isSystem = subtypeEntry != null;

      await sql`
        INSERT INTO gl_accounts (
          company_id, account_code, account_name, account_type, account_subtype,
          normal_balance, parent_account_id, description, is_system_account,
          level, display_order
        ) VALUES (
          ${companyId}::UUID,
          ${acct.accountCode},
          ${acct.accountName},
          ${acct.accountType},
          ${accountSubtype},
          ${acct.normalBalance},
          ${parentAccountId}::UUID,
          ${acct.description ?? null},
          ${isSystem},
          ${parentAccountId ? 2 : 1},
          0
        )
        ON CONFLICT (company_id, account_code) DO UPDATE SET
          account_name      = EXCLUDED.account_name,
          account_type      = EXCLUDED.account_type,
          account_subtype   = COALESCE(EXCLUDED.account_subtype, gl_accounts.account_subtype),
          normal_balance    = EXCLUDED.normal_balance,
          description       = COALESCE(EXCLUDED.description, gl_accounts.description),
          is_system_account = EXCLUDED.is_system_account OR gl_accounts.is_system_account
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'coa', row: i, field: 'accountCode', message: msg });
      skipped++;
    }
  }

  // Enforce system account subtype + flag for explicitly mapped accounts
  for (const [subtype, accountCode] of Object.entries(systemAccountMap)) {
    await sql`
      UPDATE gl_accounts
      SET account_subtype = ${subtype}, is_system_account = true
      WHERE company_id = ${companyId}::UUID AND account_code = ${accountCode}
    `;
  }

  clearSystemAccountCache();

  await updateSession(sessionId, companyId, {
    coaRecordsImported: imported,
    stepsCompleted: { coa: true },
    errors,
  });

  log.info('COA import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

/**
 * Migration Contact Service — Customers + Suppliers import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { updateSession } from './migrationService';
import type { ImportResult, MigrationError } from './migrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface CustomerImportRow {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  registrationNumber?: string;
  billingAddress?: string;
  contactPerson?: string;
  paymentTerms?: number;
  creditLimit?: number;
  notes?: string;
}

export interface SupplierImportRow {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  registrationNumber?: string;
  billingAddress?: string;
  contactPerson?: string;
  paymentTerms?: number;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  notes?: string;
}

export type DuplicateStrategy = 'skip' | 'overwrite' | 'merge';

// ── Customers ────────────────────────────────────────────────────────────────

export async function importCustomers(
  companyId: string,
  sessionId: string,
  customers: CustomerImportRow[],
  duplicateStrategy: DuplicateStrategy = 'skip',
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const existingRows = (await sql`
    SELECT id, name FROM customers WHERE company_id = ${companyId}::UUID
  `) as Row[];
  const existing = existingRows.map(r => ({ id: String(r.id), name: String(r.name) }));

  for (let i = 0; i < customers.length; i++) {
    const cust = customers[i]!;
    if (!cust.name?.trim()) {
      errors.push({ step: 'customers', row: i, field: 'name', message: 'Name is required' });
      skipped++;
      continue;
    }

    try {
      const duplicate = findDuplicate(cust.name, existing);

      if (duplicate && duplicateStrategy === 'skip') { skipped++; continue; }

      if (duplicate && duplicateStrategy === 'overwrite') {
        await sql`
          UPDATE customers SET
            email           = COALESCE(${cust.email ?? null}, email),
            phone           = COALESCE(${cust.phone ?? null}, phone),
            vat_number      = COALESCE(${cust.vatNumber ?? null}, vat_number),
            billing_address = COALESCE(${cust.billingAddress ?? null}, billing_address),
            contact_person  = COALESCE(${cust.contactPerson ?? null}, contact_person),
            payment_terms   = COALESCE(${cust.paymentTerms ?? null}, payment_terms),
            credit_limit    = COALESCE(${cust.creditLimit ?? null}, credit_limit)
          WHERE id = ${duplicate.id}::UUID AND company_id = ${companyId}::UUID
        `;
        imported++;
        continue;
      }

      await sql`
        INSERT INTO customers (
          company_id, name, email, phone, vat_number, registration_number,
          billing_address, contact_person, payment_terms, credit_limit, notes
        ) VALUES (
          ${companyId}::UUID, ${cust.name}, ${cust.email ?? null}, ${cust.phone ?? null},
          ${cust.vatNumber ?? null}, ${cust.registrationNumber ?? null},
          ${cust.billingAddress ?? null}, ${cust.contactPerson ?? null},
          ${cust.paymentTerms ?? 30}, ${cust.creditLimit ?? null}, ${cust.notes ?? null}
        )
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'customers', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { customersImported: imported, stepsCompleted: { customers: true } });
  log.info('Customer import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

