async () => {
  const emailInput = document.getElementById('email');
  const passwordInput = document.getElementById('password');

  // Focus and type using keyboard events
  emailInput.focus();
  emailInput.value = '';

  // Use React's fiber to set value
  const reactKey = Object.keys(emailInput).find(key => key.startsWith('__reactFiber') || key.startsWith('__reactInternalInstance'));

  // Try with React's internal setState via nativeInputValueSetter
  const descriptor = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
  descriptor.set.call(emailInput, 'admin@isaflow.co.za');
  emailInput.dispatchEvent(new Event('input', { bubbles: true }));
  emailInput.dispatchEvent(new Event('change', { bubbles: true }));
  emailInput.dispatchEvent(new Event('blur', { bubbles: true }));

  descriptor.set.call(passwordInput, 'admin123');
  passwordInput.dispatchEvent(new Event('input', { bubbles: true }));
  passwordInput.dispatchEvent(new Event('change', { bubbles: true }));
  passwordInput.dispatchEvent(new Event('blur', { bubbles: true }));

  return { 
    emailValue: emailInput.value, 
    passwordFilled: passwordInput.value.length > 0,
    reactKey: reactKey || 'not found'
  };
}

