async () => {
  const emailInput = document.querySelector('input[type="email"]');
  const passwordInput = document.querySelector('input[type="password"]');

  // React uses _valueTracker to detect changes
  function setNativeValue(element, value) {
    const tracker = element._valueTracker;
    if (tracker) {
      tracker.setValue('');
    }
    element.value = value;
    if (tracker) {
      tracker.setValue(value);
    }
    element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
  }

  emailInput.focus();
  setNativeValue(emailInput, 'admin@isaflow.co.za');

  await new Promise(r => setTimeout(r, 300));

  passwordInput.focus();
  setNativeValue(passwordInput, 'admin123');

  await new Promise(r => setTimeout(r, 300));

  // Check the submit button state
  const btn = document.querySelector('button[type="submit"]');

  return {
    emailVal: emailInput.value,
    passwordVal: passwordInput.value.length,
    btnDisabled: btn.disabled,
    btnText: btn.textContent.trim()
  };
}

