async function testPage(context, pageInfo) {
  const page = await context.newPage();
  const result = { ...pageInfo, pass: false, actualUrl: '', content: '', errors: [] };

  try {
    await page.goto(BASE + pageInfo.path, { timeout: 10000 });
    await page.waitForTimeout(2500);

    result.actualUrl = page.url();

    // Check for redirect to login
    if (result.actualUrl.includes('/login')) {
      result.errors.push('Redirected to login - auth failed');
      result.pass = false;
      await page.screenshot({ path: `${SCREENSHOTS}/${pageInfo.name}.png`, fullPage: false });
      await page.close();
      return result;
    }

    // Get page text
    const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 600));
    result.content = bodyText;

    // Check for errors
    const hasError = bodyText.includes('404') || 
                     bodyText.includes('Page Not Found') || 
                     bodyText.toLowerCase().includes('something went wrong') ||
                     bodyText.toLowerCase().includes('application error');

    const hasContent = bodyText.length > 50 && !bodyText.includes('Loading...');

    // Get console errors
    const consoleErrors = [];
    page.on('console', msg => {
      if (msg.type() === 'error') consoleErrors.push(msg.text().substring(0, 100));
    });

    result.pass = !hasError && hasContent;
    result.errors = consoleErrors;

    await page.screenshot({ path: `${SCREENSHOTS}/${pageInfo.name}.png`, fullPage: false });

  } catch (e) {
    result.errors.push(e.message);
    result.pass = false;
  }

  await page.close();
  return result;
}

