  const failed = results.filter(r => !r.pass).length;
  console.log(`\n========================================`);
  console.log(`FINAL: ${passed}/${results.length} PASSED | ${failed} FAILED`);

  fs.writeFileSync('/tmp/assets-qa-results-final.json', JSON.stringify(results, null, 2));

  await browser.close();
})();
