const results = [];

async function test(page, name, url, checks) {
  console.log(`\nTesting: ${name} (${url})`);
  try {
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 15000 });
    await page.waitForTimeout(3000);

    const currentUrl = page.url();
    const bodyText = await page.evaluate(() => document.body.innerText.substring(0, 2000));
    const hasError = bodyText.includes('Error') || bodyText.includes('404') || bodyText.includes('500');
    const redirectedToLogin = currentUrl.includes('/login');

    await page.screenshot({ path: `${SCREENSHOT_DIR}/${name.replace(/\s+/g, '-').toLowerCase()}.png` });

    const result = {
      name,
      url,
      currentUrl,
      redirectedToLogin,
      hasError,
      bodySnippet: bodyText.substring(0, 300),
      pass: !redirectedToLogin && !hasError
    };

    // Run custom checks
    if (checks) {
      const checkResult = await checks(page, bodyText);
      result.checks = checkResult;
    }

    results.push(result);
    console.log(`  URL: ${currentUrl}`);
    console.log(`  Pass: ${result.pass}`);
    console.log(`  Body: ${bodyText.substring(0, 150)}`);

  } catch (err) {
    console.log(`  ERROR: ${err.message}`);
    results.push({ name, url, error: err.message, pass: false });
  }
}

